use wezterm_dynamic::{Array, Value, Error};
use ordered_float::OrderedFloat;

fn array_to_f64_vec(arr: &Array) -> Result<Vec<f64>, Error> {
    let mut result = Vec::new();
    for item in arr {
        let value = item?;
        if let Value::Integer(i) = value {
            result.push(*i as f64);
        } else if let Value::UInteger(ui) = value {
            result.push(*ui as f64);
        } else if let Value::Float(f) = value {
            result.push(*f);
        } else {
            return Err(Error::new("Array contains non-numeric value"));
        }
    }
    Ok(result)
}

use rfc2047_decoder::{Decoder, Error};

pub struct MimeHeaderDecoder {
    decoder: Decoder,
    buffer: Vec<u8>,
    decoded: String,
}

impl MimeHeaderDecoder {
    fn new() -> Self {
        MimeHeaderDecoder {
            decoder: Decoder::new(),
            buffer: Vec::new(),
            decoded: String::new(),
        }
    }

    pub fn feed(&mut self, data: &[u8]) {
        self.buffer.extend_from_slice(data);
        while self.buffer.len() > 0 {
            match self.decoder.decode(&mut self.buffer) {
                Ok(decoded) => {
                    self.decoded.push_str(&decoded);
                }
                Err(Error::Incomplete) => {
                    break;
                }
                Err(e) => {
                    panic!("Decoding error: {:?}", e);
                }
            }
        }
    }

    pub fn take(&mut self) -> String {
        let result = self.decoded.clone();
        self.decoded.clear();
        result
    }
}

impl Default for MimeHeaderDecoder {
    fn default() -> Self {
        Self::new()
    }
}

use forc_util::restricted;

fn validate_project_name_with_messages(name: &str) -> Result<(), String> {
    if name.is_empty() {
        return Err("Project name cannot be empty.".to_string());
    }

    if name.contains('/') || name.contains('\\') {
        return Err("Project name cannot contain slashes ('/' or '\\').".to_string());
    }

    if name.chars().any(|c| !c.is_alphanumeric() && c != '_' && c != '-') {
        return Err("Project name can only contain alphanumeric characters, underscores (_), and hyphens (-).".to_string());
    }

    if name.starts_with('-') || name.ends_with('-') {
        return Err("Project name cannot start or end with a hyphen (-).".to_string());
    }

    if name.eq("main") || name.eq("mod") || name.eq("pub") || name.eq("use") || name.eq("as") {
        return Err("Project name cannot be a reserved keyword.".to_string());
    }

    if restricted::is_windows_reserved(name) {
        return Err("Project name is a Windows reserved filename.".to_string());
    }

    Ok(())
}

