struct TradeVolumeTransformer {
    capacity: usize,
    window: VecDeque<f64>,
    sum: f64,
}

impl TradeVolumeTransformer {
    fn new(capacity: usize) -> Self {
        TradeVolumeTransformer {
            capacity,
            window: VecDeque::with_capacity(capacity),
            sum: 0.0,
        }
    }

    fn update(&mut self, quantity: f64) -> Result<f64, SocketError> {
        if self.window.len() >= self.capacity {
            let oldest = self.window.pop_front().unwrap();
            self.sum -= oldest;
        }
        self.window.push_back(quantity);
        self.sum += quantity;
        Ok(self.sum / self.window.len() as f64)
    }
}

impl Transformer for TradeVolumeTransformer {
    type Item = BinanceMessage;

    fn transform(&mut self, item: Self::Item) -> Result<Option<Self::Item>, SocketError> {
        match item {
            BinanceMessage::Trade { quantity } => {
                let avg = self.update(quantity)?;
                Ok(Some(BinanceMessage::Trade { quantity: avg }))
            }
            BinanceMessage::SubResponse { .. } => Ok(Some(item)),
            _ => Ok(None),
        }
    }
}

