fn retrieve_preimage(context: &GatewayClientContext, operation_id: OperationId) -> Result<Preimage, anyhow::Error> {
    let state_machines = context.state_machines();
    let incoming_sm_states = state_machines.incoming();

    let mut stream = incoming_sm_states
        .subscribe()
        .map(|event| event.state)
        .filter_map(|state| {
            if let IncomingSmStates::PreimageReceived { preimage, .. } = state {
                Some(preimage)
            } else {
                None
            }
        });

    for preimage in stream {
        if preimage.operation_id() == operation_id {
            return Ok(preimage);
        }
    }

    Err(anyhow::anyhow!("Preimage not found for operation ID: {}", operation_id))
}

fn filtered_account_subscription(
    url: &str,
    target_pubkeys: &[Pubkey],
) -> Result<(PubsubClientSubscription<RpcResponse<UiAccount>>, crossbeam_channel::Receiver<RpcResponse<UiAccount>>), PubsubClientError> {
    let (sender, receiver) = crossbeam_channel::unbounded();
    let mut client = PubsubClient::new(url)?;
    let subscription = client.account_subscribe()?;

    crossbeam::thread::scoped(move || {
        for msg in subscription {
            if let Ok(account) = msg {
                if target_pubkeys.iter().any(|&pubkey| pubkey == account.account.owner) {
                    if let Err(e) = sender.send(account) {
                        eprintln!("Failed to send filtered account update: {}", e);
                    }
                }
            }
        }
    });

    Ok((subscription, receiver))
}

use fedimint_wallet_common::{Descriptor, CompressedPublicKey};
use miniscript::descriptor::{Wpkh, Wsh};
use miniscript::Script;
use miniscript::miniscript::{Key, Miniscript};
use miniscript::miniscript::{Policy, PolicyBuilder};
use miniscript::miniscript::{ScriptPublicKey, ScriptPublicKeyBuilder};
use miniscript::miniscript::{ScriptPublicKeyType, ScriptPublicKeyType::Wpkh};
use miniscript::miniscript::{ScriptType, ScriptType::Wsh};
use miniscript::miniscript::{WitnessType, WitnessType::Pk};
use miniscript::miniscript::{WitnessType::PkScript};
use miniscript::miniscript::{WitnessType::PkScriptMulti};

fn generate_tweakable_descriptor(public_keys: &[CompressedPublicKey], threshold: usize) -> Result<Descriptor<CompressedPublicKey>, Box<dyn std::error::Error>> {
    if public_keys.is_empty() {
        return Err("At least one public key is required".into());
    }
    if threshold > public_keys.len() {
        return Err("Threshold cannot exceed the number of public keys".into());
    }

    // Single-key (WPKH) case
    if public_keys.len() == 1 {
        let pk = public_keys[0];
        let wpkh = Wpkh::new(pk);
        let descriptor = Descriptor::Wpkh(wpkh);
        return Ok(descriptor);
    }

    // Multi-key (WSH) case with sorted-multi
    let mut sorted_keys = public_keys.to_vec();
    sorted_keys.sort();

    let mut script_pubkeys = Vec::new();
    for &pk in &sorted_keys {
        script_pubkeys.push(ScriptPublicKey::new(Wpkh::new(pk)));
    }

    let policy = PolicyBuilder::new()
        .threshold(threshold)
        .keys(sorted_keys.iter().map(|&pk| Key::from(pk)))
        .script_type(ScriptType::Wsh)
        .build()
        .map_err(|e| format!("Failed to build policy: {}", e))?;

    let script = Script::new(policy);
    let wsh = Wsh::new(script);
    let descriptor = Descriptor::Wsh(wsh);
    Ok(descriptor)
}

fn transfer_buffers(src: &Arc<RingBuffer>, dst: &Arc<RingBuffer>, chunk_size: usize) -> futures::io::Result<()> {
    let reader = RingBufferReader::new(src.clone());
    let writer = RingBufferWriter::new(dst.clone());

    let mut buffer = vec![0; chunk_size];

    let mut reader_fut = reader.read(&mut buffer);
    let mut writer_fut = writer.write(&buffer);

    loop {
        tokio::select! {
            result = reader_fut => {
                match result {
                    Ok(0) => break,
                    Ok(n) => {
                        writer_fut = writer.write(&buffer[..n]);
                    },
                    Err(e) => return Err(e),
                }
            },
            result = writer_fut => {
                match result {
                    Ok(n) => {
                        if n < chunk_size {
                            // Writer is full, wait for space
                            tokio::task::yield_now().await;
                            writer_fut = writer.write(&buffer[..n]);
                        } else {
                            // Continue reading
                            reader_fut = reader.read(&mut buffer);
                        }
                    },
                    Err(e) => return Err(e),
                }
            },
        }
    }

    Ok(())
}

