use crate::{Db, Key, Value};
use anyhow::{Result, anyhow};

fn check_tree_consistency<K, V>(db: &Db<K, V>) -> Result<bool>
where
    K: Key,
    V: Value,
{
    let mut tree_data = std::collections::HashMap::new();
    let mut total_keys = 0;

    // Collect all keys and their values from the database
    for key in db.iter() {
        let value = db.get(&key).ok_or_else(|| anyhow!("Failed to retrieve value for key: {}", key))?;
        tree_data.insert(key, value);
        total_keys += 1;
    }

    // Check if all trees have the same number of keys
    if tree_data.len() != total_keys {
        return Ok(false);
    }

    // Check if all trees have the same key-value pairs
    for (key, value) in tree_data.iter() {
        if db.get(key).ok_or_else(|| anyhow!("Failed to retrieve value for key: {}", key))?
            != value
        {
            return Ok(false);
        }
    }

    Ok(true)
}

fn export_csv<W: Write>(mounts: &[&Mount], cols: &Cols, separator: char, mut writer: W) -> std::io::Result<()> {
    // Write the header row
    for (i, col) in cols.iter().enumerate() {
        if i > 0 {
            writer.write_all(bseparator)?;
        }
        writer.write_all(col.header.as_bytes())?;
    }
    writer.write_all(b"\n")?;

    // Write the data rows
    for mount in mounts {
        for (i, col) in cols.iter().enumerate() {
            if i > 0 {
                writer.write_all(bseparator)?;
            }
            let value = match col {
                Col::Name => mount.name.clone(),
                Col::Path => mount.path.clone(),
                Col::Size => format!("{}", mount.size),
                Col::Mountpoint => mount.mountpoint.clone(),
                Col::FsType => mount.fs_type.clone(),
                Col::Options => mount.options.clone(),
                Col::Status => match mount.status {
                    true => "mounted".to_string(),
                    false => "unmounted".to_string(),
                },
            };
            writer.write_all(value.as_bytes())?;
        }
        writer.write_all(b"\n")?;
    }

    Ok(())
}

use gluesql_mongo_storage::{MongoStorage, utils};
