use crate::error::ResultExt;

fn create_collection_from_schema(storage: &MongoStorage, schema: &Schema) -> Result<()> {
    let collection_name = schema.name.clone();
    let validator = build_validator_from_schema(schema)?;
    let options = CreateCollectionOptions::builder()
        .validator(validator)
        .build();

    storage.client
        .database(&storage.database_name)
        .create_collection(&collection_name, options)
        .map_err(|e| Error::new(format!("Failed to create collection: {}", e)))?;

    Ok(())
}

fn build_validator_from_schema(schema: &Schema) -> Result<Document> {
    let mut validator = Document::new();
    validator.insert("validator", Document::new());
    validator.insert("validationLevel", "strict");
    validator.insert("validationAction", "warn");

    let mut validator_doc = Document::new();
    for column in &schema.columns {
        let field_name = column.name.clone();
        let field_type = match column.typ {
            "string" => "string",
            "integer" => "integer",
            "boolean" => "boolean",
            "float" => "double",
            "timestamp" => "date",
            _ => return Err(Error::new(format!("Unsupported type: {}", column.typ))),
        };

        let mut schema = Document::new();
        schema.insert("$schema", "http://json-schema.org/draft-07/schema#");
        schema.insert("type", field_type);
        schema.insert("description", column.comment.clone().unwrap_or_default());

        validator_doc.insert(field_name, schema);
    }

    validator.insert("validator", validator_doc);
    Ok(validator)
}

use hifijson::value::Value;

pub enum PathSegment<'a> {
    Key(&'a str),
    Index(usize),
}

fn get_by_path<'a>(value: &'a Value<&'a str, &'a str>, path: &[PathSegment<'a>]) -> Vec<&'a Value<&'a str, &'a str>> {
    if path.is_empty() {
        return vec![value];
    }

    let current_segment = &path[0];
    let remaining_path = &path[1..];

    match current_segment {
        PathSegment::Key(key) => {
            if let Some(next_value) = value.get(key) {
                get_by_path(next_value, remaining_path)
            } else {
                Vec::new()
            }
        }
        PathSegment::Index(index) => {
            if let Some(next_value) = value.get_index(*index) {
                get_by_path(next_value, remaining_path)
            } else {
                Vec::new()
            }
        }
    }
}

