fn get_detailed_indexer_status(
    pool: &IndexerConnectionPool,
    claims: &Claims,
    namespace: Option<&str>,
    identifier: Option<&str>,
) -> ApiResult<Json<Value>> {
    let mut conn = pool.get()?;
    let indexers = queries::indexers(&mut conn, namespace, identifier)?;

    let mut status_data = json!({});

    for indexer in indexers {
        let status = queries::indexer_status(&mut conn, &indexer.identifier)?;
        let metadata = queries::indexer_metadata(&mut conn, &indexer.identifier)?;

        let mut status_map = json!({
            "status": status.status,
            "last_updated": status.last_updated,
            "block_number": status.block_number,
            "error": status.error,
            "metadata": metadata
        });

        status_data[&indexer.identifier] = status_map;
    }

    Ok(Json(status_data))
}

