fn aggregate_transactions(txs: &[RuntimeTransaction<SanitizedTransaction>]) -> AggregatedMeta {
    let mut total_instruction_data_length = 0;
    let mut total_signature_count = 0;

    for tx in txs {
        if let Some(sanitized_tx) = &tx.transaction {
            total_instruction_data_length += sanitized_tx.instructions_data_length();
            total_signature_count += sanitized_tx.signature_count();
        }
    }

    AggregatedMeta {
        total_instruction_data_length,
        total_signature_count,
    }
}

