fn batch_add_g1_points(points: &[u8]) -> Result<[u8; 64], AltBn128Error> {
    if points.len() % 64 != 0 {
        return Err(AltBn128Error::InvalidLength);
    }

    let num_points = points.len() / 64;
    let mut result = [0u8; 64];
    let mut current_point = [0u8; 64];

    // Initialize result with the first point
    let mut offset = 0;
    current_point.copy_from_slice(&points[offset..offset + 64]);
    offset += 64;

    // Add all remaining points
    for _ in 1..num_points {
        let mut point = [0u8; 64];
        point.copy_from_slice(&points[offset..offset + 64]);
        offset += 64;

        let res = alt_bn128_addition(&mut [current_point, point].concat());
        match res {
            Ok(val) => current_point = val,
            Err(e) => return Err(e),
        }
    }

    Ok(current_point)
}

use crate::layer::Layer;
use crate::Primitive;
use crate::core::Rectangle;

fn layer_bounds(layer: &Layer) -> Option<Rectangle> {
    if layer.primitives.is_empty() {
        return None;
    }

    let mut min_x = f64::MAX;
    let mut min_y = f64::MAX;
    let mut max_x = f64::MIN;
    let mut max_y = f64::MIN;

    for primitive in &layer.primitives {
        if let Some(bounds) = primitive.bounds() {
            min_x = min_x.min(bounds.min_x);
            min_y = min_y.min(bounds.min_y);
            max_x = max_x.max(bounds.max_x);
            max_y = max_y.max(bounds.max_y);
        }
    }

    Some(Rectangle {
        min_x,
        min_y,
        max_x,
        max_y,
    })
}

