use image::{RgbImage, Rgb};
use ndarray::{ArrayView2, Axis};

fn normalize_and_rgb_image(image_data: &[u8]) -> RgbImage {
    // MNIST images are 28x28 pixels, stored as a single row of bytes
    let image_view: ArrayView2<u8> = ArrayView2::from_shape((28, 28), image_data).unwrap();

    // Normalize pixel values to [0.0, 1.0]
    let normalized_view = image_view.map(|&pixel| pixel as f64 / 255.0);

    // Convert to RGB image
    let mut rgb_image = RgbImage::new(28, 28);
    for (i, row) in normalized_view.axis_iter(Axis(0)).enumerate() {
        for (j, &value) in row.iter().enumerate() {
            rgb_image.put_pixel(i as u32, j as u32, Rgb([value, value, value]));
        }
    }
    rgb_image
}

fn jwt_to_custom(claims: JWTClaims) -> Result<CustomClaims, String> {
    let issuer = claims.issuer().ok_or("Missing issuer in JWT claims")?;
    let expiration = claims.expiration_time().ok_or("Missing expiration time in JWT claims")?;

    Ok(CustomClaims {
        issuer: match issuer {
            Issuer::String(s) => s,
            Issuer::URI(uri) => uri.to_string(),
        },
        expiration: expiration
            .as_secs_since_unix_epoch()
            .ok_or("Invalid expiration time in JWT claims")?,
    })
}

