    issuer: String,
    expiration: i64,
}

use crate::client::NodeClient;
use celestia_types::ExtendedHeader;
use std::time::Duration;
use tokio::time;
use crate::error::Error;

fn wait_until_synced(&self) -> Result<(), Error> {
    const MAX_RETRIES: u64 = 60;
    const RETRY_DELAY: Duration = Duration::from_secs(5);

    for _ in 0..MAX_RETRIES {
        let local_head = self.get_local_head()?;
        let network_head = self.get_network_head()?;

        if local_head == network_head {
            return Ok(());
        }

        time::sleep(RETRY_DELAY).await?;
    }

    Err(Error::Timeout("Node did not sync within the allowed time".to_string()))
}

