fn update_subscriptions(
    map: &mut std::collections::HashMap<PeerId, std::collections::HashSet<Topic>>,
    event: &FloodsubSubscription,
) {
    match event.action {
        FloodsubSubscriptionAction::Subscribe => {
            map.entry(event.peer_id)
                .or_insert_with(HashSet::new)
                .insert(event.topic.clone());
        }
        FloodsubSubscriptionAction::Unsubscribe => {
            if let Some(topics) = map.get_mut(&event.peer_id) {
                topics.remove(&event.topic);
                if topics.is_empty() {
                    map.remove(&event.peer_id);
                }
            }
        }
    }
}

fn parse_serve_subcommand(parser: &mut Parser) -> Result<(u16, IpAddr), Error> {
    let mut port = 8080;
    let mut host = IpAddr::from_str("0.0.0.0").unwrap();

    while let Some(arg) = parser.next() {
        match arg {
            Ok(Argument::Flag(name, _)) if name == "serve" => {
                // The 'serve' subcommand is parsed, now process options
            }
            Ok(Argument::Option(name, value)) => {
                match name {
                    "port" => {
                        if let Ok(p) = value.parse::<u16>() {
                            port = p;
                        }
                    }
                    "host" => {
                        if let Ok(ip) = IpAddr::from_str(value) {
                            host = ip;
                        }
                    }
                    _ => {}
                }
            }
            _ => {}
        }
    }

    Ok((port, host))
}

fn batch_tracing_events(events: Vec<HashMap<String, Value>>) -> Vec<Value> {
    let mut result = Vec::new();
    for event in events {
        let mut gelf = HashMap::new();
        gelf.insert("version".to_string(), "1.1".to_string());
        gelf.insert("timestamp".to_string(), event.get("timestamp").cloned().unwrap_or(Value::Number(serde_json::Number::from(std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_secs()))));
        gelf.insert("level".to_string(), event.get("level").cloned().unwrap_or(Value::Number(serde_json::Number::from(6))));
        gelf.insert("facility".to_string(), event.get("facility").cloned().unwrap_or("tracing".to_string()));
        gelf.insert("short_message".to_string(), event.get("short_message").cloned().unwrap_or("Tracing event".to_string()));
        gelf.insert("full_message".to_string(), event.get("full_message").cloned().unwrap_or("Tracing event".to_string()));
        gelf.extend(event);
        result.push(Value::Object(gelf));
    }
    result
}

fn validate_plantuml_code(code: &str) -> Vec<String> {
    let mut errors = Vec::new();
    let mut depth = 0;
    let mut in_code_block = false;
    let mut startuml_pos = None;
    let mut enduml_pos = None;

    for (i, c) in code.chars().enumerate() {
        if c == '@' && i + 8 < code.len() && &code[i..i + 8] == "startuml" {
            in_code_block = true;
            startuml_pos = Some(i);
        } else if c == '@' && i + 7 < code.len() && &code[i..i + 7] == "enduml" {
            if in_code_block {
                in_code_block = false;
                enduml_pos = Some(i);
            } else {
                errors.push(format!("Unexpected '@enduml' at position {}", i));
            }
        } else if c == '{' && in_code_block {
            depth += 1;
        } else if c == '}' && in_code_block {
            if depth == 0 {
                errors.push(format!("Unmatched closing brace at position {}", i));
            } else {
                depth -= 1;
            }
        }

        if in_code_block && depth == 0 && enduml_pos.is_none() {
            errors.push(format!("Unclosed PlantUML block at position {}", i));
        }
    }

    if in_code_block {
        errors.push("PlantUML block not closed".to_string());
    }

    if startuml_pos.is_some() && enduml_pos.is_none() {
        errors.push("Missing '@enduml' in PlantUML block".to_string());
    }

    errors
}

