fn can_approve_proposal(
    deps: Deps,
    env: Env,
    pre_propose_id: u64,
) -> Result<bool, PreProposeError> {
    // Get the pre-proposal approval contract address from storage
    let approval_contract: Addr = PRE_PROPOSE_APPROVAL_CONTRACT.load(deps.storage)?;

    // Query the status of the pre-proposal from the approval contract
    let status_response: StatusResponse = deps
        .querier
        .query::<StatusResponse>(&approval_contract.addr, &ApprovalQueryMsg::Status { pre_propose_id });

    // Check if the proposal is still pending
    if status_response.status != Status::Pending {
        return Ok(false);
    }

    // Query the deposit information for the pre-proposal
    let deposit_info: DepositInfoResponse = deps
        .querier
        .query::<DepositInfoResponse>(&approval_contract.addr, &ApprovalQueryMsg::DepositInfo { pre_propose_id });

    // Ensure the deposit has been provided
    if deposit_info.deposit.is_zero() {
        return Ok(false);
    }

    Ok(true)
}

fn error_to_response(err: ServerError) -> axum::response::Response<axum::body::Body> {
    let problem = HttpApiProblem::from(err);
    let json = serde_json::to_string(&problem).unwrap();
    let mut response = axum::response::Response::new(Body::from(json));
    *response.status_mut() = problem.status();
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        header::HeaderValue::from_static("application/problem+json"),
    );
    response
}

use audiotags::{Tag, Result, Error};
use std::path::Path;

fn copy_album_cover<P: AsRef<Path>>(
    src_path: P,
    dst_path: P,
) -> Result<()> {
    let src = src_path.as_ref();
    let dst = dst_path.as_ref();

    // Read the source file's tag
    let mut src_tag = Tag::read(src).map_err(|e| Error::from(e))?;

    // Extract the album cover from the source
    let cover = src_tag
        .cover_art()
        .ok_or(Error::new("No album cover found in source file"))?;

    // Read the destination file's tag
    let mut dst_tag = Tag::read(dst).map_err(|e| Error::from(e))?;

    // Add the album cover to the destination
    dst_tag.set_cover_art(cover);

    // Write the updated tag back to the destination file
    dst_tag.write(dst).map_err(|e| Error::from(e))?;

    Ok(())
}

fn solar_altitude(coord: Coordinates, datetime: DateTime<Utc>) -> f64 {
    let julian_date = unix_to_julian(datetime.timestamp() as u64);
    let mean_anomaly = solar_mean_anomaly(julian_date);
    let equation_of_center = equation_of_center(mean_anomaly);
    let ecliptic_longitude = ecliptic_longitude(mean_anomaly, equation_of_center);
    let declination = declination(ecliptic_longitude);
    let solar_transit = solar_transit(julian_date);
    let hour_angle = (datetime.hour() as f64 - solar_transit) * 15.0;
    let latitude_rad = coord.latitude.to_radians();
    let declination_rad = declination.to_radians();
    let cos_latitude = cos(latitude_rad);
    let sin_latitude = sin(latitude_rad);
    let cos_declination = cos(declination_rad);
    let sin_declination = sin(declination_rad);
    let cos_hour_angle = cos(hour_angle.to_radians());
    let sin_hour_angle = sin(hour_angle.to_radians());
    let altitude_numerator = sin_latitude * sin_declination + cos_latitude * cos_declination * cos_hour_angle;
    let altitude_denominator = cos_latitude * cos_declination * sin_hour_angle;
    let altitude_rad = asin(altitude_numerator);
    altitude_rad.to_degrees()
}

use deno_webidl::converters;
use serde_json::Value;

fn convert_to_unsigned_longs(values: &[Value]) -> Result<Vec<u32>, String> {
    let mut result = Vec::new();
    for (idx, value) in values.iter().enumerate() {
        match value {
            Value::Number(num) if num.is_u64() => {
                let num = num.as_u64().unwrap();
                if num > u32::MAX as u64 {
                    return Err(format!("Value at index {} is out of range for u32", idx));
                }
                result.push(num as u32);
            }
            Value::Number(num) if num.is_f64() => {
                let num = num.as_f64().unwrap();
                if num < 0.0 || num > u32::MAX as f64 || !num.is_integer() {
                    return Err(format!("Value at index {} is not a valid unsigned long", idx));
                }
                result.push(num as u32);
            }
            Value::Bool(b) => {
                if *b {
                    result.push(1);
                } else {
                    result.push(0);
                }
            }
            Value::String(s) => {
                if let Ok(num) = s.parse::<u32>() {
                    result.push(num);
                } else {
                    return Err(format!("Value at index {} is not a valid unsigned long", idx));
                }
            }
            Value::Null => {
                result.push(0);
            }
            _ => {
                return Err(format!("Value at index {} is not a valid unsigned long", idx));
            }
        }
    }
    Ok(result)
}

fn batch_notify_transactions(
    slot: Slot,
    transactions: &[VersionedTransaction],
    signatures: &[Signature],
    hashes: &[Hash],
    metas: &[TransactionStatusMeta],
    plugin_manager: Arc<RwLock<GeyserPluginManager>>,
) -> Result<(), String> {
    let plugin_manager = plugin_manager.read().unwrap();
    let plugins = plugin_manager.get_plugins();

    for (tx, sig, hash, meta) in transactions.iter().zip(signatures).zip(hashes).zip(metas) {
        let mut notifier = TransactionNotifierImpl::new();
        notifier.set_slot(slot);
        notifier.set_transaction(tx);
        notifier.set_signature(sig);
        notifier.set_hash(hash);
        notifier.set_status_meta(meta);

        for plugin in plugins.values() {
            if let Err(e) = plugin.notify(&notifier) {
                return Err(format!("Plugin notification failed: {}", e));
            }
        }
    }

    Ok(())
}

use v_frame::frame::Frame;
