pub fn downscale_frame(frame: &Frame<u8>) -> Frame<u8> {
    let src_luma = &frame.planes[0];
    let preview_width = src_luma.cfg.width / 2;
    let preview_height = src_luma.cfg.height / 2;
    let mut preview = Frame::new_with_padding(preview_width, preview_height, ChromaSampling::Cs420, 0);
    for (src_plane, dst_plane) in frame.planes.iter().zip(preview.planes.iter_mut()) {
        src_plane.downscale_in_place::<2>(dst_plane);
    }
    preview
}

use solana_tpu_client::tpu_client::TpuClient;
use solana_transaction_error::TransportResult;
use solana_connection_cache::{ConnectionPool, ConnectionManager, NewConnectionConfig};
use indicatif::ProgressBar;

fn send_wire_batch_with_progress<P, M, C>(
    tpu_client: &TpuClient<P, M, C>,
    wire_transactions: &[Vec<u8>],
) -> TransportResult<()>
where
    P: ConnectionPool<NewConnectionConfig = C>,
    M: ConnectionManager<ConnectionPool = P, NewConnectionConfig = C>,
    C: NewConnectionConfig,
{
    let total = wire_transactions.len() as u64;
    let mut progress_bar = ProgressBar::new(total);
    progress_bar.set_message("Sending wire transactions...");

    for (index, wire_tx) in wire_transactions.iter().enumerate() {
        let result = tpu_client.send_wire_transaction(wire_tx);
        match result {
            Ok(_) => {
                progress_bar.inc(1);
            }
            Err(e) => {
                eprintln!("Error sending transaction at index {}: {}", index, e);
                progress_bar.inc(1);
            }
        }
    }

    progress_bar.finish_with_message("Wire transactions sent successfully.");
    Ok(())
}

