use std::path::Path;
use std::collections::HashMap;
use typescript_tools::monorepo_manifest::MonorepoManifest;
use typescript_tools::package_manifest::{PackageManifest, DependencyGroup};
use typescript_tools::pin::PinError;
use typescript_tools::types::PackageName;

fn sync_internal_dependency_versions(root: &Path) -> Result<(), PinError> {
    let manifest = MonorepoManifest::load(root)?;
    let packages = manifest.packages();

    let version_map: HashMap<PackageName, String> = packages
        .iter()
        .map(|(name, manifest)| {
            let version = manifest.version.clone();
            (name.clone(), version)
        })
        .collect();

    for (package_name, package_manifest) in packages {
        let manifest_path = package_manifest.path.clone();
        let mut manifest = PackageManifest::load(&manifest_path)?;

        for (dependency_name, dependency) in &mut manifest.dependencies {
            if let Some(version) = version_map.get(dependency_name) {
                if dependency.version != *version {
                    dependency.version = version.clone();
                }
            }
        }

        manifest.save(&manifest_path)?;
    }

    Ok(())
}

