fn stream_block_range(
    view_client: &Addr<ViewClientActor>,
    shard_tracker: &ShardTracker,
    indexer_config: &IndexerConfig,
    store_config: &StoreConfig,
    blocks_sink: mpsc::Sender<StreamerMessage>,
) -> Result<(), anyhow::Error> {
    let start_height = indexer_config.start_height;
    let latest_height = fetch_latest_block(view_client, shard_tracker, indexer_config, store_config)?;
    let last_synced_height = get_last_synced_height(store_config)?;

    if start_height > latest_height {
        return Ok(());
    }

    let mut current_height = last_synced_height + 1;
    let mut sync_mode = SyncModeEnum::Full;

    while current_height <= latest_height {
        let block_view = fetch_block_by_height(view_client, shard_tracker, current_height, sync_mode)?;
        let streamer_msg = build_streamer_message(block_view, current_height, sync_mode, indexer_config)?;
        blocks_sink.send(streamer_msg).await?;
        current_height += 1;
    }

    set_last_synced_height(store_config, latest_height)?;
    Ok(())
}

fn fetch_latest_block(
    view_client: &Addr<ViewClientActor>,
    shard_tracker: &ShardTracker,
    indexer_config: &IndexerConfig,
    store_config: &StoreConfig,
) -> Result<u64, anyhow::Error> {
    let latest_height = view_client.send(near_client::GetBlockRequest::Final {}).await?.height;
    Ok(latest_height)
}

fn fetch_block_by_height(
    view_client: &Addr<ViewClientActor>,
    shard_tracker: &ShardTracker,
    height: u64,
    sync_mode: SyncModeEnum,
) -> Result<BlockView, anyhow::Error> {
    let block = view_client
        .send(near_client::GetBlockRequest::Height(height, sync_mode))
        .await?
        .block;
    Ok(block)
}

fn build_streamer_message(
    block_view: BlockView,
    height: u64,
    sync_mode: SyncModeEnum,
    indexer_config: &IndexerConfig,
) -> Result<StreamerMessage, anyhow::Error> {
    let finality = if sync_mode == SyncModeEnum::Final {
        Finality::Final
    } else {
        Finality::Finalized
    };
    let streamer_msg = StreamerMessage {
        block: block_view,
        height,
        finality,
        ..Default::default()
    };
    Ok(streamer_msg)
}

fn get_last_synced_height(store_config: &StoreConfig) -> Result<u64, anyhow::Error> {
    let last_synced_height = near_store::get_last_synced_height(store_config)?;
