}

fn optimize_account_update_notifications(
    plugin_manager: std::sync::Arc<std::sync::RwLock<crate::geyser_plugin_manager::GeyserPluginManager>>,
    account_info: &agave_geyser_plugin_interface::geyser_plugin_interface::ReplicaAccountInfoV3<'_>,
    slot: solana_clock::Slot,
    is_startup: bool,
) -> Result<(), Box<dyn std::error::Error>> {
    let plugin_manager = plugin_manager.read().unwrap();
    let plugins = plugin_manager.get_plugins();

    if plugins.is_empty() {
        return Ok(());
    }

    let mut batch_notifications = Vec::new();
    let mut plugin_latencies = std::collections::HashMap::new();

    for plugin in plugins {
        let plugin_name = plugin.name();
        let plugin = plugin.as_ref();

        let measure = Measure::start(format!("account_update_notification_{}", plugin_name));
        let result = plugin.notify_account_update(account_info, slot, is_startup);
        measure.stop();

        plugin_latencies.insert(plugin_name.to_string(), measure.as_nanos());

        if let Err(e) = result {
            warn!("Plugin {} failed to process account update: {}", plugin_name, e);
        } else {
            batch_notifications.push(plugin_name.to_string());
        }
    }

    if !batch_notifications.is_empty() {
        let mut notifier = plugin_manager.notifier().write().unwrap();
        notifier.notify_batch(batch_notifications);
    }

    metrics::record("account_update_notification_latency", plugin_latencies);

    Ok(())
}

use std::collections::{HashMap, HashSet};
use std::sync::{Arc, Mutex};
use std::collections::hash_map::Entry;

#[derive(Debug, PartialEq, Eq)]
pub enum CacheError {
    CacheNotFound,
    TagNotFound,
    InvalidOperation,
}

struct CacheEntry {
    tags: HashSet<String>,
}

struct TagMapping {
    cache_id: i64,
    request_url: String,
    tags: HashSet<String>,
}

struct CacheSystem {
    cache_items: HashMap<i64, HashMap<String, CacheEntry>>,
    tag_to_caches: HashMap<String, HashSet<TagMapping>>,
}

impl CacheSystem {
    fn new() -> Self {
        CacheSystem {
            cache_items: HashMap::new(),
            tag_to_caches: HashMap::new(),
        }
    }

    fn get_cache_entry(&self, cache_id: i64, request_url: &str) -> Option<&CacheEntry> {
        self.cache_items.get(&cache_id)
            .and_then(|items| items.get(request_url))
    }

    fn get_tag_mappings(&self, tag: &str) -> Option<&HashSet<TagMapping>> {
        self.tag_to_caches.get(tag)
    }

    fn add_tag_mapping(&mut self, tag: &str, mapping: TagMapping) {
        let entry = self.tag_to_caches.entry(tag.to_string()).or_insert_with(HashSet::new);
        entry.insert(mapping);
    }

    fn remove_tag_mapping(&mut self, tag: &str, mapping: &TagMapping) {
        if let Some(set) = self.tag_to_caches.get_mut(tag) {
            set.remove(mapping);
        }
    }
}

pub struct CacheManager {
    cache_system: Arc<Mutex<CacheSystem>>,
}

impl CacheManager {
    pub fn new() -> Self {
        CacheManager {
            cache_system: Arc::new(Mutex::new(CacheSystem::new())),
        }
    }

    pub fn set_cache_item_tags(
        &self,
        cache_id: i64,
        request_url: &str,
        tags: &[String],
    ) -> Result<(), CacheError> {
        let mut system = self.cache_system.lock().unwrap();

        // Check if cache exists
        if !system.cache_items.contains_key(&cache_id) {
            return Err(CacheError::CacheNotFound);
        }

        let cache_entry = system.cache_items.get_mut(&cache_id).unwrap();
        let entry = cache_entry.entry(request_url.to_string()).or_insert_with(CacheEntry {
            tags: HashSet::new(),
        });

        // Remove existing tags
        for tag in &entry.tags {
            system.remove_tag_mapping(tag, &TagMapping {
                cache_id,
                request_url: request_url.to_string(),
                tags: entry.tags.clone(),
            });
        }

        // Add new tags
        for tag in tags {
            if !entry.tags.contains(tag) {
                system.add_tag_mapping(tag, TagMapping {
                    cache_id,
                    request_url: request_url.to_string(),
                    tags: entry.tags.clone(),
                });
            }
        }

        entry.tags.clear();
        entry.tags.extend(tags.iter().cloned());

        Ok(())
    }
}

use ssi_jws::JwsSlice;
use ssi_jwk::JWK;
use ssi_claims_core::VerificationParameters;
use ssi_vc_jose_cose::JoseVp;
use futures::future::join_all;
use std::sync::Arc;
use std::collections::HashMap;
use std::thread;
use std::error::Error;

fn validate_batch_jose_vps(
    vps: Vec<(&str, &ssi_jwk::JWK)>,
) -> Result<Vec<(String, Result<(), Box<dyn std::error::Error>>)>, Box<dyn std::error::Error>> {
    let mut results = Vec::new();
    let mut handles = Vec::new();

    for (vp_str, key) in vps {
        let vp_str = vp_str.to_string();
        let key = Arc::new(key.clone());
        let handle = thread::spawn(move || {
            let vp = JoseVp::from_slice(vp_str.as_bytes()).map_err(|e| e.into())?;
            let jws_slice = JwsSlice::from_slice(vp_str.as_bytes()).map_err(|e| e.into())?;

            let params = VerificationParameters::new()
                .with_jws_slice(jws_slice)
                .with_jwk(key.clone())
                .with_issuers(vec![vp.iss().unwrap_or_default()])
                .with_subscriptions(vec![])
                .with_claims_context(vec![])
                .with_signature_check(true)
                .with_proof_check(true);

            let result = vp.verify(&params).map_err(|e| e.into());

            Ok((vp_str, result))
        });

        handles.push(handle);
    }

    for handle in handles {
        let result = handle.join().map_err(|e| e.into())?;
        results.push(result);
    }

    Ok(results)
}

use ico::{IconDir, IconImage};
use std::fs::File;
use std::io;

fn ico_to_png(input_path: &str, output_path: &str) -> io::Result<()> {
    let file = File::open(input_path)?;
    let icon_dir = IconDir::read_from(file)?;

    let largest_image = icon_dir
        .images
        .iter()
        .max_by_key(|img| img.width * img.height)
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "No images found in ICO file"))?;

    let mut output_file = File::create(output_path)?;
    largest_image.write_to(&mut output_file, ico::ImageFormat::PNG)
}

fn query_approval_status(
    deps: Deps,
    pre_propose_id: u64,
) -> Result<dao_interface::status::Status, dao_pre_propose_base::error::PreProposeError> {
    // Retrieve the linked main DAO proposal ID from the map
    let proposal_id = PROPOSAL_IDS.load(&deps.storage, pre_propose_id)
        .map_err(|_| PreProposeError::ProposalIdNotFound)?;

    // Load the address of the pre-proposal approval contract
    let approval_contract_addr = PRE_PROPOSE_APPROVAL_CONTRACT
        .load(&deps.storage)
        .map_err(|_| PreProposeError::ApprovalContractNotSet)?;

    // Query the approval contract for the status of this proposal
    let response: StatusResponse = deps.querier.query_wasm_smart(
        approval_contract_addr,
        &ApprovalQueryMsg::GetStatus { proposal_id },
    )
    .map_err(|_| PreProposeError::ApprovalQueryFailed)?;

    Ok(response.status)
}

fn batch_decode<D>(decoder: &mut D, batch_size: usize) -> Result<Vec<D::Item>, D::Error>
where
    D: Decoder,
{
    let mut items = Vec::with_capacity(batch_size);
    for _ in 0..batch_size {
        if let Some(item) = decoder.next() {
            items.push(item);
        } else {
            break;
        }
    }
    Ok(items)
}

use std::env::var;
use std::fs::File;
use std::io::Write;
use std::path::Path;
use camino::Utf8Path;

fn link_resources<P: AsRef<Utf8Path>>(resource_paths: &[P], output_name: &str) -> std::io::Result<()> {
    let out_dir = var("OUT_DIR").expect("OUT_DIR not set");
    let temp_path = Utf8Path::new(&out_dir).join(format!("{}.rc", output_name));

    let mut temp_file = File::create(&temp_path)?;

    for &path in resource_paths {
        let path_str = path.as_ref().to_string();
        let include_line = format!("{}{}\n", "include ", path_str);
        temp_file.write_all(include_line.as_bytes())?;
    }

    let link_result = link(&temp_path, output_name);
    std::fs::remove_file(temp_path)?;
    link_result
}

struct RateLimiter {
    window: Duration,
    limits: HashMap<String, Vec<SystemTime>>,
}

impl RateLimiter {
    fn new(window: Duration) -> Self {
        RateLimiter {
            window,
            limits: HashMap::new(),
        }
    }

    fn is_allowed(&mut self, ip: &str) -> bool {
        let now = SystemTime::now();
        let entry = self.limits.entry(ip.to_string()).or_insert_with(Vec::new);

        // Remove old timestamps that are outside the time window
        entry.retain(|&timestamp| timestamp > now - self.window);

        if entry.len() >= 100 {
            return false;
        }

        entry.push(now);
        true
    }
}

fn negotiate_with_timeout<R>(socket: R, protocols: Vec<&'static str>, dur: std::time::Duration) -> Result<(String, Negotiated<R>), NegotiationError>
where
    R: AsyncRead + AsyncWrite + Unpin,
{
    let mut fut = dialer_select_proto(socket, protocols);
    let timeout = time::timeout(dur, fut);

    match timeout.await {
        Ok(Ok((proto, negotiated))) => Ok((proto, negotiated)),
        Ok(Err(e)) => Err(e),
        Err(_) => Err(NegotiationError::Timeout),
    }
}

struct Writer {
    buffer: [u8; 32],
    pos: usize,
}

impl Writer {
    fn new() -> Self {
        Writer {
            buffer: [0; 32],
            pos: 0,
        }
    }
}

impl Write for Writer {
    fn write_str(&mut self, s: &str) -> core::fmt::Result {
        for &c in s.as_bytes() {
            if self.pos == self.buffer.len() {
                return Err(core::fmt::Error);
            }
            self.buffer[self.pos] = c;
            self.pos += 1;
        }
        Ok(())
    }
}

fn new() -> Writer {
    Writer::new()
}

use std::time::{Duration, Instant};
use tokio::time::sleep;
use fedimint_server_core::bitcoin_rpc::{ServerBitcoinRpcMonitor, ServerBitcoinRpcStatus};
use anyhow;

fn monitor_bitcoin_fees(
    monitor: &ServerBitcoinRpcMonitor,
    threshold: u64,
    interval: Duration,
    timeout: Duration,
) -> anyhow::Result<()> {
    let start = Instant::now();
    loop {
        // Check if the operation has timed out
        if start.elapsed() > timeout {
            return Err(anyhow::anyhow!("Bitcoin fee monitoring timed out"));
        }

        // Get the current fee rate
        let status = monitor.get_status().map_err(|e| anyhow::anyhow!("Failed to get Bitcoin status: {}", e))?;
        let fee_rate = status.fee_rate;

        // Check if the fee rate exceeds the threshold
        if fee_rate > threshold {
            return Err(anyhow::anyhow!("High Bitcoin fee rate detected: {} sat/vB (threshold: {} sat/vB)", fee_rate, threshold));
        }

        // Wait for the next interval
        sleep(interval).await;
    }
}

use fax::{encoder::Encoder, VecWriter, Color, slice_bits, slice_reader, BitReader};

fn pbm_to_fax(pbm: &[u8]) -> Vec<u8> {
    let mut reader = BitReader::new(pbm);
    let width = reader.read_u32() as usize;
    let height = reader.read_u32() as usize;

    // Skip the comment line if present
    if reader.read_u8() == b'P' && reader.read_u8() == b'4' {
        let _ = reader.read_u8(); // Skip the '4' character
    }

    let mut writer = VecWriter::new();
    let mut encoder = Encoder::new(&mut writer);

    for row in 0..height {
        let mut previous_row = vec![Color::Black; width];
        let mut current_row = vec![Color::Black; width];

        for col in 0..width {
            current_row[col] = match reader.read_bit() {
                Some(b) => if b == 1 { Color::White } else { Color::Black },
                None => Color::Black,
            };
        }

        encoder.encode_row(&current_row, &previous_row);
        previous_row = current_row;
    }

    writer.into_inner()
}

fn send_transactions_with_report(&self, transactions: &[Transaction]) -> TransportResult<HashMap<SocketAddr, TransportResult<()>>> {
    let leader_addrs = self.get_all_leader_addrs();
    let mut results = HashMap::new();

    let mut futures = Vec::new();

    for &leader_addr in &leader_addrs {
        let transactions = transactions.to_vec();
        let future = async move {
            let mut success = true;
            let mut error = None;

            for &tx in &transactions {
                match send_wire_transaction_to_addr(tx, leader_addr).await {
                    Ok(_) => continue,
                    Err(e) => {
                        success = false;
                        error = Some(e);
                        break;
                    }
                }
            }

            if success {
                Ok(())
            } else {
                Err(error.unwrap())
            }
        };

        futures.push(Box::pin(future));
    }

    let results = join_all(futures).await;

    for (i, &leader_addr) in leader_addrs.iter().enumerate() {
        let result = results[i].map_err(|e| TransportError::with_source(e, format!("Failed to send transactions to leader {}", leader_addr)));
        results.insert(leader_addr, result);
    }

    Ok(results)
}

