use byteorder::ByteOrder;

fn deserialize_complex_struct<B: ByteOrder>(data: &mut &[u8]) -> Option<(Vec<u8>, Vec<u16>, Vec<u32>)> {
    // Read the variable-length byte array
    let len_bytes = data.len();
    if len_bytes == 0 {
        return None;
    }
    let mut len = 0;
    let mut i = 0;
    while i < len_bytes && len == 0 {
        len = (len << 7) | (data[i] as usize & 0x7F);
        i += 1;
    }
    if i >= len_bytes || len == 0 {
        return None;
    }
    let mut bytes = Vec::with_capacity(len);
    bytes.extend_from_slice(&data[..i]);
    *data = &data[i..];

    // Read the variable-length array of u16 values
    let mut u16s = Vec::new();
    while !data.is_empty() {
        let (value, read) = B::read_u16(data);
        if read == 0 {
            break;
        }
        u16s.push(value);
        *data = &data[read..];
    }

    // Read the variable-length array of u32 values
    let mut u32s = Vec::new();
    while !data.is_empty() {
        let (value, read) = B::read_u32(data);
        if read == 0 {
            break;
        }
        u32s.push(value);
        *data = &data[read..];
    }

    Some((bytes, u16s, u32s))
}

use anyhow::Result;
use crate::model::Model;
use crate::openai::OpenAIClient;
use crate::cli::Options;

fn generate_message_with_fallback(
    primary: Model,
    fallback: Model,
    system_msg: &str,
    diff: &str,
    extra_msg: &str,
    options: &Options,
) -> Result<String> {
    let combined = format!("{}{}", system_msg, diff);
    let total_tokens = OpenAIClient::count_tokens(&combined, options)?;
    let max_tokens = match primary {
        Model::Gpt35Turbo => 4096,
        Model::Gpt4 => 8192,
        _ => 4096,
    };

    if total_tokens > max_tokens {
        // Fallback to smaller model
        let fallback_model = fallback;
        let fallback_client = OpenAIClient::new(fallback_model, options)?;
        let response = fallback_client.generate(
            &format!("System: {}\n\nDiff: {}\n\nExtra: {}", system_msg, diff, extra_msg),
            options,
        )?;
        Ok(response)
    } else {
        // Use primary model
        let primary_client = OpenAIClient::new(primary, options)?;
        let response = primary_client.generate(
            &format!("System: {}\n\nDiff: {}\n\nExtra: {}", system_msg, diff, extra_msg),
            options,
        )?;
        Ok(response)
    }
}

