use crate::ast::{Stmt, Expr};
use crate::operator::{BinaryOperator, UnaryOperator, TernaryOperator};
use serde_json::json;

fn stmt_to_json(stmt: &Stmt) -> serde_json::Value {
    match stmt {
        Stmt::Expr(expr) => json!({
            "type": "Stmt::Expr",
            "expr": expr_to_json(expr)
        }),
        Stmt::If(cond, then, else_) => json!({
            "type": "Stmt::If",
            "condition": expr_to_json(cond),
            "then": stmt_to_json(then),
            "else": stmt_to_json(else_)
        }),
        Stmt::While(cond, body) => json!({
            "type": "Stmt::While",
            "condition": expr_to_json(cond),
            "body": stmt_to_json(body)
        }),
        Stmt::For(var, range, body) => json!({
            "type": "Stmt::For",
            "variable": var.clone(),
            "range": expr_to_json(range),
            "body": stmt_to_json(body)
        }),
        Stmt::Break => json!({
            "type": "Stmt::Break"
        }),
        Stmt::Continue => json!({
            "type": "Stmt::Continue"
        }),
        Stmt::Return(expr) => json!({
            "type": "Stmt::Return",
            "expr": expr_to_json(expr)
        }),
        Stmt::Assign(target, value) => json!({
            "type": "Stmt::Assign",
            "target": target.clone(),
            "value": expr_to_json(value)
        }),
        Stmt::Block(stmts) => json!({
            "type": "Stmt::Block",
            "statements": stmts.iter().map(stmt_to_json).collect::<Vec<_>>()
        }),
    }
}

fn expr_to_json(expr: &Expr) -> serde_json::Value {
    match expr {
        Expr::Identifier(name) => json!({
            "type": "Expr::Identifier",
            "name": name.clone()
        }),
        Expr::Literal(value) => json!({
            "type": "Expr::Literal",
            "value": value.clone()
        }),
        Expr::Binary(op, left, right) => json!({
            "type": "Expr::Binary",
            "operator": op.to_string(),
            "left": expr_to_json(left),
            "right": expr_to_json(right)
        }),
        Expr::Unary(op, expr) => json!({
            "type": "Expr::Unary",
            "operator": op.to_string(),
            "expr": expr_to_json(expr)
        }),
        Expr::Ternary(cond, then, else_) => json!({
            "type": "Expr::Ternary",
            "condition": expr_to_json(cond),
            "then": expr_to_json(then),
            "else": expr_to_json(else_)
        }),
        Expr::Call(func, args) => json!({
            "type": "Expr::Call",
            "function": expr_to_json(func),
            "arguments": args.iter().map(expr_to_json).collect::<Vec<_>>()
        }),
        Expr::Index(expr, index) => json!({
            "type": "Expr::Index",
            "expr": expr_to_json(expr),
            "index": expr_to_json(index)
        }),
        Expr::Member(expr, name) => json!({
            "type": "Expr::Member",
            "expr": expr_to_json(expr),
            "name": name.clone()
        }),
        Expr::Tuple(exprs) => json!({
            "type": "Expr::Tuple",
            "expressions": exprs.iter().map(expr_to_json).collect::<Vec<_>>()
        }),
        Expr::List(exprs) => json!({
            "type": "Expr::List",
            "expressions": exprs.iter().map(expr_to_json).collect::<Vec<_>>()
        }),
    }
}

use std::time::Duration;
use dora_node_api::event_stream::{EventStream, Event};
