use arrow::array::Array;

fn next_input_for_id(
    stream: &mut EventStream,
    target_id: DataId,
    timeout: Duration,
) -> Result<Option<(Metadata, Array)>> {
    let start = Instant::now();
    loop {
        tokio::select! {
            _ = tokio::time::sleep(timeout) => {
                return Ok(None);
            },
            event = stream.next() => {
                let event = event?;
                if event.data_id() == target_id {
                    let metadata = event.metadata().cloned();
                    let array = event.array().clone();
                    return Ok(Some((metadata, array)));
                }
            }
        }
        if start.elapsed() >= timeout {
            return Ok(None);
        }
    }
}

