use git_url_parse::{GitUrl, Scheme, GitUrlParseError};

fn public_https_url(url: &str) -> Result<String, GitUrlParseError> {
    let git_url = GitUrl::parse(url)?;
    let mut scheme = git_url.scheme();
    let host = git_url.host().unwrap_or("");
    let path = git_url.path().unwrap_or("");

    // Ensure the scheme is HTTPS
    if scheme != Scheme::Https {
        scheme = Scheme::Https;
    }

    // Ensure the path ends with .git
    let path = if path.ends_with(".git") {
        path
    } else {
        format!("{}.git", path)
    };

    // Reconstruct the URL with the modified scheme and path
    let url_str = format!("{}://{}{}", scheme.to_string(), host, path);

    Ok(url_str)
}

use {bincode::serialize, solana_transaction::Transaction, solana_transaction_error::TransportResult, tokio::time::{sleep, Duration}};

fn send_transaction_with_retry(&self, transaction: &Transaction, max_attempts: usize, base_delay: Duration) -> TransportResult<()> {
    let mut attempts = 0;
    loop {
        attempts += 1;
        if attempts > max_attempts {
            return Err(TransportResult::TransactionError("Max retry attempts exceeded".to_string()));
        }

        match self.send_transaction(transaction) {
            Ok(()) => return Ok(()),
            Err(e) => {
                if e.is_transient() {
                    log::warn!("Transient error occurred, retrying... {:?}", e);
                    sleep(base_delay * (1 << (attempts - 1))).await;
                    continue;
                } else {
                    return Err(e);
                }
            }
        }
    }
}

use crate::Request;

fn parse_custom_headers(buffer: &[u8], n: usize) -> Result<Request, String> {
    if n == 0 {
        return Err("Empty buffer provided".to_string());
    }

    let mut buffer = buffer.iter().enumerate();
    let mut request_line = Vec::new();
    let mut headers = Vec::new();
    let mut current_header = String::new();
    let mut current_header_key = String::new();
    let mut current_header_value = String::new();
    let mut in_header = false;
    let mut header_key = String::new();
    let mut header_value = String::new();

    // Parse request line
    while let Some((i, &byte)) = buffer.next() {
        if byte == b'\r' {
            if request_line.is_empty() {
                return Err("Empty request line".to_string());
            }
            let request_line_str = std::str::from_utf8(&request_line).unwrap_or("Invalid UTF-8");
            let mut parts = request_line_str.split_whitespace();
            if let Some(method) = parts.next() {
                if let Some(path) = parts.next() {
                    if let Some(http_version) = parts.next() {
                        if !http_version.starts_with("HTTP/") {
                            return Err("Invalid HTTP version".to_string());
                        }
                        // Parse request line successfully
                        let request = Request {
                            method: method.to_string(),
                            path: path.to_string(),
                            http_version: http_version.to_string(),
                            headers: headers,
                        };
                        return Ok(request);
                    } else {
                        return Err("Incomplete request line".to_string());
                    }
                } else {
                    return Err("Incomplete request line".to_string());
                }
            } else {
                return Err("Incomplete request line".to_string());
            }
        } else if byte == b'\n' {
            if !request_line.is_empty() {
                // End of request line
                request_line.clear();
                in_header = true;
            } else {
                // End of headers
                if headers.is_empty() {
                    return Err("No headers found".to_string());
                }
                break;
            }
        } else if in_header {
            if byte == b':' {
                // End of header key
                if current_header_key.is_empty() {
                    return Err("Header key cannot be empty".to_string());
                }
                current_header = current_header_key.clone();
                current_header_key.clear();
                current_header_value.clear();
                current_header_value.push(byte);
            } else if byte == b'\r' {
                // End of header
                if current_header_value.is_empty() {
                    return Err("Header value cannot be empty".to_string());
                }
                headers.push((current_header_key, current_header_value));
                current_header_key.clear();
                current_header_value.clear();
                current_header = String::new();
            } else if byte == b'\n' {
                // End of header
                if current_header_value.is_empty() {
                    return Err("Header value cannot be empty".to_string());
                }
                headers.push((current_header_key, current_header_value));
                current_header_key.clear();
                current_header_value.clear();
                current_header = String::new();
                in_header = false;
            } else if byte == b' ' {
                // End of header key
                if current_header_key.is_empty() {
                    return Err("Header key cannot be empty".to_string());
                }
                current_header_value.push(byte);
                current_header_key.clear();
                current_header_value.clear();
            } else {
                // Continue building header key or value
                if current_header_key.is_empty() {
                    current_header_key.push(byte as char);
                } else {
                    current_header_value.push(byte as char);
                }
            }
        } else {
            // Building request line
            request_line.push(byte);
        }
    }

    if !in_header {
        if headers.is_empty() {
            return Err("No headers found".to_string());
        }
    }

    Ok(Request {
        method: String::new(),
        path: String::new(),
        http_version: String::new(),
        headers: headers,
    })
}

