use vortex_buffer::{Alignment, ByteBuffer, ByteBufferMut};
use std::io;

fn align_buffer(mut buffer: ByteBufferMut, alignment: Alignment) -> std::io::Result<ByteBuffer> {
    let original_data = buffer.as_mut_slice();
    let original_len = original_data.len();

    // Allocate a new buffer with the required alignment
    let aligned_buffer = ByteBuffer::with_capacity(original_len, alignment)?;

    // Copy data from the original buffer to the aligned buffer
    let aligned_data = aligned_buffer.as_mut_slice();
    aligned_data.copy_from_slice(original_data);

    // Freeze the buffer to make it immutable
    Ok(aligned_buffer.freeze())
}

