fn generate_peg_in_descriptor(public_keys: &[CompressedPublicKey]) -> PegInDescriptor {
    if public_keys.len() == 1 {
        PegInDescriptor::Wpkh(Wpkh {
            pk: public_keys[0].clone(),
        })
    } else {
        let sorted_pks: Vec<_> = public_keys.to_vec();
        sorted_pks.sort();
        PegInDescriptor::Wsh(Wsh {
            script: sorted_pks.iter().map(|pk| pk.clone()).collect(),
        })
    }
}

