use std::path::Path;
use json5::parse;
use std::fs::File;
use std::io::Read;

fn validate_plugin_config(config_path: &Path) -> Result<(), String> {
    if !config_path.exists() {
        return Err(format!("Configuration file not found at: {}", config_path.display()));
    }

    if !config_path.is_file() {
        return Err(format!("Provided path is not a file: {}", config_path.display()));
    }

    let mut file = match File::open(config_path) {
        Ok(file) => file,
        Err(e) => return Err(format!("Failed to open configuration file: {}", e)),
    };

    let mut contents = String::new();
    if let Err(e) = file.read_to_string(&mut contents) {
        return Err(format!("Failed to read configuration file: {}", e));
    }

    let config: Result<json5::Value, _> = parse(contents.as_str());
    match config {
        Ok(_) => {
            // Assuming required fields are 'name' and 'version'
            if let json5::Value::Object(obj) = &contents {
                if !obj.contains_key("name") || !obj.contains_key("version") {
                    return Err("Configuration file is missing required fields 'name' or 'version'".to_string());
                }
            } else {
                return Err("Configuration file is not an object".to_string());
            }
        }
        Err(e) => {
            return Err(format!("Invalid JSON5 configuration: {}", e));
        }
    }

    Ok(())
}

fn summarize_levels_per_facility(entries: &[Entry]) -> std::collections::HashMap<LogFacility, std::collections::HashMap<LogLevel, usize>> {
    let mut facility_counts = HashMap::new();

    for entry in entries {
        let facility = entry.facility;
        let level = entry.level;

        facility_counts
            .entry(facility)
            .or_insert_with(HashMap::new)
            .entry(level)
            .and_modify(|count| *count += 1)
            .or_insert(1);
    }

    facility_counts
}

fn retry_task<F, T>(retries: u32, delay: std::time::Duration, task: F) -> Result<T, tokio_with_wasm::task::JoinError>
where
    F: Fn() -> T + Send + Sync + 'static,
    T: Send + 'static,
{
    for attempt in 0..retries {
        match spawn_blocking(task).await {
            Ok(result) => return Ok(result),
            Err(err) => {
                if attempt < retries - 1 {
                    sleep(delay).await.unwrap();
                } else {
                    return Err(err);
                }
            }
        }
    }
    unreachable!()
}

fn filter_build_plan_by_prefix(builder: libcnb_data::build_plan::BuildPlanBuilder, prefix: &str) -> libcnb_data::build_plan::BuildPlan {
    let mut new_provides = Vec::new();
    for provide in builder.provides() {
        if provide.name().starts_with(prefix) {
            new_provides.push(provide.clone());
        }
    }

    let mut new_alternatives = Vec::new();
    for alternative in builder.alternatives() {
        let mut filtered_provides = Vec::new();
        for provide in alternative.provides() {
            if provide.name().starts_with(prefix) {
                filtered_provides.push(provide.clone());
            }
        }
        let alternative_with_filtered_provides = Or::new()
            .with_provides(filtered_provides);
        new_alternatives.push(alternative_with_filtered_provides);
    }

    let mut new_builder = BuildPlanBuilder::new();
    new_builder = new_builder.with_provides(new_provides);
    new_builder = new_builder.with_alternatives(new_alternatives);
    new_builder.build()
}

use anyhow::Result;
use std::collections::HashMap;
use std::sync::Arc;
use std::time::Duration;
use futures::stream::StreamExt;
use futures::future::ready;
use tokio::time::sleep;

pub fn refresh_gateway_map(
    client_ctx: &ClientContext<LightningClientModule>,
    module_api: &DynModuleApi,
    gateway_conn: &Arc<dyn GatewayConnection + Send + Sync>,
    federation_id: FederationId,
) -> Result<()> {
    let gateways = gateway_conn.get_gateways(federation_id)?;
    let mut gateway_map: HashMap<PublicKey, String> = HashMap::new();

    for gateway in gateways {
        let routing_info = get_routing_info(client_ctx, module_api, &gateway)?;
        gateway_map.insert(gateway.public_key, routing_info.url);
    }

    store_gateway_map(module_api, &gateway_map)?;
    Ok(())
}

fn get_routing_info(
    client_ctx: &ClientContext<LightningClientModule>,
    module_api: &DynModuleApi,
    gateway: &GatewayInfo,
) -> Result<RoutingInfo> {
    let mut routing_info = RoutingInfo::default();
    let mut timeout = tokio::time::sleep(Duration::from_secs(5));
    let mut future = client_ctx.get_route(gateway.public_key, module_api);
    tokio::pin!(future);
    while let Some(result) = future.next().await {
        if let Ok(info) = result {
            routing_info = info;
            break;
        }
    }
    Ok(routing_info)
}

fn store_gateway_map(module_api: &DynModuleApi, gateway_map: &HashMap<PublicKey, String>) -> Result<()> {
    module_api.write(|state| {
        state.gateway_map = Some(gateway_map.clone());
        Ok(())
    })
}

use std::io;
use std::fs;
use fsst::fsst::{decompress, FSST_SYMBOL_TABLE_SIZE};

fn decompress_directory(input_dir: &str, output_dir: &str) -> io::Result<()> {
    // Create the output directory if it doesn't exist
    fs::create_dir_all(output_dir)?;

    // Read all entries in the input directory
    let entries = fs::read_dir(input_dir)?;

    for entry in entries {
        let entry = entry?;
        let path = entry.path();
        let file_name = path.file_name().unwrap().to_string_lossy();

        // Check if the file is a regular file
        if path.is_file() {
            // Open the input file
            let mut reader = std::fs::File::open(&path)?;
            let mut buffer = Vec::new();
            reader.read_to_end(&mut buffer)?;

            // Decompress the file
            let decompressed_data = decompress(&buffer, FSST_SYMBOL_TABLE_SIZE)?;

            // Write the decompressed data to the output file
            let output_path = format!("{}/{}", output_dir, file_name);
            let mut writer = std::fs::File::create(output_path)?;
            writer.write_all(&decompressed_data)?;
        }
    }

    Ok(())
}

fn generate_signed_url(base_url: &str, secret_key: &str, expiry: SystemTime) -> String {
    // Convert base URL to Url object
    let url = Url::parse(base_url).expect("Invalid base URL");

    // Calculate the time difference in seconds since UNIX_EPOCH
    let expiry_duration = expiry.duration_since(UNIX_EPOCH).expect("Expiry time must be in the future");
    let expiry_seconds = expiry_duration.as_secs();

    // Create a string to sign by combining URL and expiry
    let string_to_sign = format!("{}{}", url, expiry_seconds);

    // Create SHA-256 hash of the string_to_sign
    let mut hasher = Sha256::new();
    hasher.update(string_to_sign.as_bytes());
    let mut hash_result = [0u8; 32];
    hasher.finalize_into(&mut hash_result);

    // Convert hash to hexadecimal string
    let signature = hex::encode(hash_result);

    // Construct the signed URL with query parameters
    let mut signed_url = url.to_string();
    signed_url.push_str(&format!("?expiry={}&signature={}", expiry_seconds, signature));

    signed_url
}

use std::net::{Ipv4Addr, Ipv6Addr};
use crate::response::ResponsePeer;

fn serialize_compact_peers(
    ipv4_peers: &[ResponsePeer<Ipv4Addr>],
    ipv6_peers: &[ResponsePeer<Ipv6Addr>],
) -> Vec<u8> {
    let mut result = Vec::new();

    for peer in ipv4_peers {
        result.extend_from_slice(&peer.address().octets());
        result.push(peer.port().to_le_bytes()[0]);
        result.push(peer.port().to_le_bytes()[1]);
        result.push(peer.port().to_le_bytes()[2]);
        result.push(peer.port().to_le_bytes()[3]);
    }

    for peer in ipv6_peers {
        result.extend_from_slice(&peer.address().octets());
        result.push(peer.port().to_le_bytes()[0]);
        result.push(peer.port().to_le_bytes()[1]);
        result.push(peer.port().to_le_bytes()[2]);
        result.push(peer.port().to_le_bytes()[3]);
    }

    result
}

use toml_edit::{Document, Item};

fn get_dependency_version(cargo_toml: &str, dep: &str) -> Option<String> {
    let doc: Document = cargo_toml.parse().ok()?;
    let package = doc.as_table().get("package")?.as_table()?;
    let dependencies = package.get("dependencies")?.as_table()?;

    for (key, value) in dependencies {
        if key == dep {
            if let Some(version) = value.as_str() {
                return Some(version.to_string());
            } else if let Some(table) = value.as_table() {
                if let Some(version) = table.get("version")?.as_str() {
                    return Some(version.to_string());
                }
            }
        }
    }

    None
}

use imgproc::colorcvt::assert;
use yuv_sys;

fn yuv420_copy_with_flip(
    src_y: &[u8],
    src_stride_y: u32,
    src_u: &[u8],
    src_stride_u: u32,
    src_v: &[u8],
    src_stride_v: u32,
    dst_y: &mut [u8],
    dst_stride_y: u32,
    dst_u: &mut [u8],
    dst_stride_u: u32,
    dst_v: &mut [u8],
    dst_stride_v: u32,
    width: u32,
    height: u32,
    flip_y: bool,
) {
    assert!(
        src_y.len() >= (height * src_stride_y as usize),
        "Source Y plane buffer is too small"
    );
    assert!(
        src_u.len() >= ((height + 1) / 2 * src_stride_u as usize),
        "Source U plane buffer is too small"
    );
    assert!(
        src_v.len() >= ((height + 1) / 2 * src_stride_v as usize),
        "Source V plane buffer is too small"
    );
    assert!(
        dst_y.len() >= (height * dst_stride_y as usize),
        "Destination Y plane buffer is too small"
    );
    assert!(
        dst_u.len() >= ((height + 1) / 2 * dst_stride_u as usize),
        "Destination U plane buffer is too small"
    );
    assert!(
        dst_v.len() >= ((height + 1) / 2 * dst_stride_v as usize),
        "Destination V plane buffer is too small"
    );

    let y_offset = if flip_y {
        (height - 1) as usize * src_stride_y as usize
    } else {
        0
    };

    unsafe {
        yuv_sys::yuv420_copy(
            src_y.as_ptr(),
            src_stride_y,
            src_u.as_ptr(),
            src_stride_u,
            src_v.as_ptr(),
            src_stride_v,
            dst_y.as_mut_ptr(),
            dst_stride_y,
            dst_u.as_mut_ptr(),
            dst_stride_u,
            dst_v.as_mut_ptr(),
            dst_stride_v,
            width,
            height,
            flip_y as i32,
        );
    }
}

use crate::fixed_base_msm_window::FixedBaseMSMPrecompWindow;
use crate::lincomb::g1_lincomb;
use crate::{G1Affine, G1Projective, Scalar};

pub struct FixedBaseMSM {
    precomp: Option<FixedBaseMSMPrecompWindow>,
    window_size: usize,
}

impl FixedBaseMSM {
    pub fn new_precomputed(generators: Vec<G1Affine>, window_size: usize) -> Self {
        if generators.is_empty() {
            return Self { precomp: None, window_size };
        }

        let num_generators = generators.len();
        let mut precomp = FixedBaseMSMPrecompWindow::new(generators, window_size);
        precomp.precompute();

        Self { precomp: Some(precomp), window_size }
    }

    pub fn compute(&self, scalars: &[Scalar]) -> Result<G1Projective, String> {
        if self.precomp.is_some() && scalars.len() != self.precomp.as_ref().unwrap().num_generators {
            return Err("Number of scalars must match the number of generators".to_string());
        }

        if self.precomp.is_some() {
            let precomp = self.precomp.as_ref().unwrap();
            let result = precomp.evaluate(scalars);
            return Ok(result);
        }

        if scalars.len() != generators.len() {
            return Err("Number of scalars must match the number of generators".to_string());
        }

        let result = g1_lincomb(scalars, generators.as_slice());
        Ok(result)
    }
}

fn high_res_control_change(
    channel: wmidi::Channel,
    function: wmidi::ControlFunction,
    value: u16,
) -> (wmidi::MidiMessage<'static>, wmidi::MidiMessage<'static>) {
    let msb = (value >> 7) as u8;
    let lsb = (value & 0x7F) as u8;

    let msb_msg = MidiMessage::control_change(
        channel,
        function,
        msb,
        U7::from(msb),
    );

    let lsb_msg = MidiMessage::control_change(
        channel,
        function,
        lsb,
        U7::from(lsb),
    );

    (msb_msg, lsb_msg)
}

