use crate::{Vec3, Mat4};

fn look_at(eye: Vec3, target: Vec3, up: Vec3) -> Mat4 {
    let forward = (target - eye).normalize();
    let right = forward.cross(up).normalize();
    let up = right.cross(forward);

    let mut mat = Mat4::identity();
    mat[0][0] = right.x;
    mat[0][1] = right.y;
    mat[0][2] = right.z;
    mat[1][0] = up.x;
    mat[1][1] = up.y;
    mat[1][2] = up.z;
    mat[2][0] = -forward.x;
    mat[2][1] = -forward.y;
    mat[2][2] = -forward.z;
    mat[3][0] = -right.dot(eye);
    mat[3][1] = -up.dot(eye);
    mat[3][2] = forward.dot(eye);
    mat
}

use wasm_bindgen::prelude::*;
use wasm_bindgen::JsValue;
use web_sys::Request;
use web_sys::Response;
use web_sys::AbortController;
use web_sys::RequestInit;
use js_sys::Promise;
use std::time::Duration;
use std::thread;

fn fetch_with_abort(url: &str, timeout_ms: i32) -> Result<js_sys::Promise, JsValue> {
    let controller = AbortController::new().map_err(|e| JsValue::from(e))?; 
    let controller_ref = controller.clone();

    let init = RequestInit::new();
    init.method("GET");
    init.mode(web_sys::RequestMode::Cors);
    init.credentials(web_sys::RequestCredentials::SameOrigin);
    init.cache(web_sys::RequestCache::Default);
    init.redirect(web_sys::RequestRedirect::Follow);

    let request = Request::new_with_init(url, &init).map_err(|e| JsValue::from(e))?; 

    let promise = Promise::resolve(&JsValue::undefined());

    let timeout = Duration::from_millis(timeout_ms as u64);
    let timeout_handle = thread::spawn(move || {
        thread::sleep(timeout);
        controller_ref.abort();
    });

    let promise = Promise::new(move |resolve, reject| {
        let request_clone = request.clone();
        let controller_ref_clone = controller_ref.clone();

        let on_load = Closure::new(move |event: &web_sys::Event| {
            let response = event.target().unwrap().dyn_ref::<Response>().unwrap();
            resolve(&JsValue::from_serde(&response).unwrap());
        });

        let on_error = Closure::new(move |event: &web_sys::Event| {
            let error = event.target().unwrap().dyn_ref::<JsValue>().unwrap();
            reject(error);
        });

        let on_abort = Closure::new(move |event: &web_sys::Event| {
            let reason = JsValue::from("Fetch request aborted due to timeout");
            reject(reason);
        });

        request_clone.addEventListener("load", on_load.as_ref().unchecked_ref());
        request_clone.addEventListener("error", on_error.as_ref().unchecked_ref());
        request_clone.addEventListener("abort", on_abort.as_ref().unchecked_ref());

        let request_clone = request_clone;
        let controller_ref_clone = controller_ref_clone;

        let promise = Promise::new(move |resolve, reject| {
            let request_clone = request_clone.clone();
            let controller_ref_clone = controller_ref_clone.clone();

            let on_response = Closure::new(move |event: &web_sys::Event| {
                let response = event.target().unwrap().dyn_ref::<Response>().unwrap();
                resolve(&JsValue::from_serde(&response).unwrap());
            });

            let on_error = Closure::new(move |event: &web_sys::Event| {
                let error = event.target().unwrap().dyn_ref::<JsValue>().unwrap();
                reject(error);
            });

            let on_abort = Closure::new(move |event: &web_sys::Event| {
                let reason = JsValue::from("Fetch request aborted due to timeout");
                reject(reason);
            });

            request_clone.addEventListener("load", on_response.as_ref().unchecked_ref());
            request_clone.addEventListener("error", on_error.as_ref().unchecked_ref());
            request_clone.addEventListener("abort", on_abort.as_ref().unchecked_ref());

            let promise = web_sys::fetch_with_request(&request_clone, &controller_ref_clone).unwrap();
            promise.then(|_| {
                Ok(JsValue::from_serde(&JsValue::from("Success")).unwrap())
            }).catch(|e| {
                Err(e)
            });
        });

        promise
    });

    Ok(promise)
}

