use std::io::{Read, Write, Seek, SeekFrom};
use std::path::Path;
use rusoto_s3::{S3, GetObjectRequest};
use tokio::runtime::Runtime;
use zstd_seekable_s3::{GetSeekableObject, SeekableDecompress};
use zstd_seekable::Seekable;

fn extract_range_to_file<A>(
    client: A,
    runtime: &Runtime,
    bucket: &str,
    key: &str,
    start: u64,
    length: usize,
    output_path: &Path,
) -> Result<(), Box<dyn std::error::Error>>
where
    A: rusoto_s3::S3 + Send + Sync + 'static,
{
    let request = GetObjectRequest {
        bucket: bucket.to_string(),
        key: key.to_string(),
        ..Default::default()
    };

    let object = runtime.block_on(client.get_object(request)).map(|res| res.body)?;
    let seekable = GetSeekableObject::new(object);
    let decompressor = SeekableDecompress::new(seekable);

    decompressor.seek(SeekFrom::Start(start))?;

    let mut output_file = std::fs::File::create(output_path)?;
    let mut buffer = vec![0; 1024 * 1024]; // 1MB buffer

    let mut total_read = 0;
    while total_read < length as u64 {
        let bytes_to_read = std::cmp::min(length - total_read as usize, buffer.len());
        let n = decompressor.read(&mut buffer[..bytes_to_read])?;
        if n == 0 {
            break;
        }
        output_file.write_all(&buffer[..n])?;
        total_read += n as u64;
    }

    Ok(())
}

