fn compute_start_syncing_height(
    last_synced: Option<u64>,
    indexer_config: &IndexerConfig,
    latest_block_height: u64,
) -> u64 {
    let sync_mode = indexer_config.sync_mode;
    let catchup_blocks = indexer_config.catchup_blocks;

    match sync_mode {
        SyncModeEnum::Full => {
            if let Some(last_synced) = last_synced {
                if last_synced >= latest_block_height {
                    latest_block_height
                } else {
                    last_synced
                }
            } else {
                latest_block_height
            }
        }
        SyncModeEnum::Fast => {
            if let Some(last_synced) = last_synced {
                let start_height = last_synced.saturating_sub(catchup_blocks);
                start_height.max(1)
            } else {
                latest_block_height.saturating_sub(catchup_blocks).max(1)
            }
        }
        SyncModeEnum::Light => {
            if let Some(last_synced) = last_synced {
                let start_height = last_synced.saturating_sub(catchup_blocks);
                start_height.max(1)
            } else {
                latest_block_height.saturating_sub(catchup_blocks).max(1)
            }
        }
    }
}

