use deno_process::{SpawnArgs, ChildStdio, StdioOrRid, Stdio, ProcessError, SpawnOutput};
use deno_process::op_spawn_child;
use deno_process::op_spawn_wait;
use deno_process::op_spawn_kill;
use deno_core::OpState;
use tokio::time;

fn run_with_timeout(state: &mut OpState, cmd: &str, args: &[&str], timeout_secs: u64) -> Result<SpawnOutput, ProcessError> {
    let mut spawn_args = SpawnArgs::default();
    spawn_args.command = cmd.to_string();
    spawn_args.args = args.to_vec();
    spawn_args.stdin = Stdio::Pipe;
    spawn_args.stdout = Stdio::Pipe;
    spawn_args.stderr = Stdio::Pipe;
    spawn_args.child_stdio = ChildStdio::Inherit;

    let child = op_spawn_child(state, &mut spawn_args)?;

    // Spawn a task to wait for the child to complete
    let timeout = time::sleep(tokio::time::Duration::from_secs(timeout_secs));
    let child_clone = child.clone();
    let child_handle = tokio::spawn(async move {
        tokio::select! {
            _ = timeout => {
                // Timeout occurred, kill the child
                op_spawn_kill(state, child_clone)?;
            },
            result = op_spawn_wait(state, child_clone) => {
                result
            }
        }
    });

    // Wait for the child to finish or timeout
    let result = child_handle.await.map_err(|_| ProcessError::new("Failed to await child process"))?;

    Ok(result)
}

