fn fetch_preimage(context: &GatewayClientContext, operation_id: OperationId) -> Result<Preimage, anyhow::Error> {
    let state_machines = context.state_machines();
    let mut stream = state_machines
        .subscribe(operation_id)
        .map(|state| match state {
            GatewayCompleteStates::HtlcOutcome(HtlcOutcome::Preimage(preimage)) => preimage,
            _ => return Err(anyhow::anyhow!("Unexpected state for operation")),
        });

    if let Some(preimage) = stream.next().transpose()? {
        Ok(preimage)
    } else {
        Err(anyhow::anyhow!("No preimage received for the operation"))
    }
}

