fn batch_echo(multiplexer: std::sync::Arc<MultiplexerSocket>, msgs: Vec<String>) -> Result<Vec<EchoResponse>, SocketError> {
    let mut responses = Vec::new();
    let multiplexer = Arc::clone(&multiplexer);
    let mut handles = Vec::new();

    for msg in msgs {
        let multiplexer = Arc::clone(&multiplexer);
        let request = EchoRequest { message: msg };
        let (tx, rx) = std::sync::mpsc::channel();

        let handle = std::thread::spawn(move || {
            let mut socket = multiplexer.clone();
            let request_msg = RequestMessage::EchoRequest(request);
            match socket.send_request(request_msg) {
                Ok(_) => {
                    match rx.recv() {
                        Ok(response) => response,
                        Err(_) => Err(SocketError::InternalError),
                    }
                }
                Err(e) => Err(e),
            }
        });

        handles.push(handle);
        handles.push(tx.send(handle.join().unwrap()));
    }

    for handle in handles {
        if let Ok(response) = handle {
            responses.push(response);
        }
    }

    Ok(responses)
}

fn dialer_lazy_with_payload<R, I>(
    inner: R,
    protocols: I,
    version: Version,
    payload: &[u8],
) -> Result<(String, Negotiated<R>), NegotiationError>
where
    R: AsyncRead + AsyncWrite + Unpin,
    I: IntoIterator,
    I::Item: AsRef<str>,
{
    let (selected_protocol, negotiated) = dialer_select_proto(inner, protocols, version)?;
    let mut negotiated = Negotiated::new(negotiated);
    Pin::new(&mut negotiated).start_write(payload)?;
    Ok((selected_protocol, negotiated))
}

fn list_supported_protocols<R>(io: R) -> Result<Vec<String>, NegotiationError>
where
    R: AsyncRead + AsyncWrite + Unpin,
{
    let mut message_io = MessageIO::new(io);
    let message = Message::Ls;
    message_io.write_message(&message).await?;
    message_io.flush().await?;
    let response = message_io.read_message().await?;
    if let Message::Protocols(protocols) = response {
        Ok(protocols)
    } else {
        Err(NegotiationError::InvalidResponse)
    }
}

fn rolling_iqr<I, F>(iter: &mut I, window_size: usize) -> Vec<F>
where
    I: Iterator<Item = F>,
    F: Float + FromPrimitive + AddAssign + SubAssign,
{
    let mut rolling_iqr = RollingIQR::new(window_size);
    let mut result = Vec::new();
    let mut buffer = Vec::new();

    for item in iter {
        buffer.push(item);
        if buffer.len() > window_size {
            buffer.remove(0);
        }

        rolling_iqr.update(&buffer);

        result.push(rolling_iqr.iqr());
    }

    result
}

fn create_configured_reader<P: AsRef<std::path::Path>>(path: P) -> Result<csv::Reader<std::fs::File>> {
    let path = path.as_ref();
    let file = File::open(path)?;
    let mut sniffer = Sniffer::new();
    let sample_size = SampleSize::new(1024);
    let dialect = sniffer.sniff(&mut std::io::BufReader::new(file), sample_size)?;
    let mut reader = ReaderBuilder::new()
        .delimiter(dialect.delimiter as u8)
        .has_headers(dialect.has_header)
        .quote(b'"')
        .escape(b'\\')
        .flexible(true)
        .build(file);
    Ok(reader)
}

