fn average_gas_per_account(stats: &GasUsageStats) -> std::collections::BTreeMap<ShardUId, f64> {
    let mut result = std::collections::BTreeMap::new();
    for (shard_uid, shard_usage) in &stats.shards {
        let total_gas = shard_usage.used_gas_total();
        let account_count = shard_usage.used_gas_per_account.len() as u128;
        if account_count > 0 {
            let average = total_gas as f64 / account_count as f64;
            result.insert(*shard_uid, average);
        }
    }
    result
}

