fn secure_free_memfd_secret<T: ?Sized>(ptr: NonNull<T>) {
    unsafe {
        let raw_ptr = ptr.as_ptr() as *mut u8;
        let canary_ptr = raw_ptr.add(alloc::size_of::<T>() - CANARY_SIZE);
        let canary = *canary_ptr as u64;

        if canary != CANARY {
            panic!("Canary verification failed: memory corruption detected");
        }

        // Securely zero the memory
        let size = alloc::size_of::<T>();
        core::ptr::write_bytes(raw_ptr, 0, size);

        // Free the memfd_secret allocation
        allocext::free_memfd_secret(ptr);
    }
}

use foyer::HybridCache;
use foyer::HybridCacheEntry;
use foyer_common::code::{StorageKey, StorageValue, HashBuilder};
use equivalent::Equivalent;
use std::hash::Hash;
use std::fmt::Debug;
use std::future::Future;
use std::pin::Pin;
use std::task::{Context, Poll};
use std::collections::HashMap;

fn batch_get<K, V, S, Q>(cache: &HybridCache<K, V, S>, keys: &[Q>) -> Vec<Option<HybridCacheEntry<K, V, S>>>
where
    K: StorageKey,
    V: StorageValue,
    S: HashBuilder + Debug,
    Q: Hash + Equivalent<K> + Send + Sync + Clone + 'static,
{
    let mut results = Vec::with_capacity(keys.len());
    let mut key_to_index = HashMap::new();

    for (index, key) in keys.iter().enumerate() {
        if let Some(k) = key.clone().try_into() {
            key_to_index.insert(k, index);
        }
    }

    let mut futures = Vec::new();
    for key in keys {
        if let Some(k) = key.clone().try_into() {
            futures.push(cache.get(k));
        }
    }

    let mut pending = futures.len();
    let mut responses = Vec::with_capacity(futures.len());

    let mut cx = Context::from_waker(std::task::noop_waker_ref());
    while pending > 0 {
        for (i, future) in futures.iter_mut().enumerate() {
            if let Some(future) = future.as_mut() {
                match future.poll(&mut cx) {
                    Poll::Ready(Some(entry)) => {
                        responses.push(Some(entry));
                        pending -= 1;
                    }
                    Poll::Ready(None) => {
                        responses.push(None);
                        pending -= 1;
                    }
                    Poll::Pending => {
                        break;
                    }
                }
            }
        }
    }

    for (index, result) in responses.into_iter().enumerate() {
        if let Some(k) = keys[index].clone().try_into() {
            if let Some(entry) = result {
                results.push(Some(entry));
            } else {
                results.push(None);
            }
        }
    }

    results
}

