fn draw_circular_image(
    &mut self,
    image: &Image,
    center: Point,
    radius: f32,
    border: Option<(Color, f32)>,
    transformation: Transformation,
    pixels: &mut tiny_skia::PixmapMut<'_>,
    clip_mask: &mut tiny_skia::Mask,
    clip_bounds: Rectangle,
) {
    let mut paint = tiny_skia::Paint::default();
    let mut image_paint = tiny_skia::Paint::default();

    // Create circular clipping mask
    let circle_path = tiny_skia::Path::new();
    circle_path.add_circle(center.x(), center.y(), radius, tiny_skia::PathData::new());
    clip_mask.set_path(circle_path, &tiny_skia::Mask::default());

    // Set image paint with transformation
    image_paint.set_transform(transformation.to_matrix());
    image_paint.set_filter(tiny_skia::Filter::None);
    image_paint.set_blend_mode(tiny_skia::BlendMode::SrcOver);

    // Draw the image with clipping
    pixels.clip_path(circle_path, tiny_skia::ClipMode::Replace);
    pixels.draw_image(image.bitmap(), image_paint);

    // Draw border if specified
    if let Some((border_color, border_width)) = border {
        let border_radius = radius + border_width / 2.0;
        let border_path = tiny_skia::Path::new();
        border_path.add_circle(center.x(), center.y(), border_radius, tiny_skia::PathData::new());
        border_path.subtract_circle(center.x(), center.y(), radius, tiny_skia::PathData::new());

        paint.set_color(border_color.into());
        paint.set_stroke_width(border_width);
        paint.set_stroke_cap(tiny_skia::StrokeCap::Round);
        paint.set_stroke_join(tiny_skia::StrokeJoin::Round);
        pixels.draw_path(&border_path, &paint);
    }
}

