fn record_body_sizes<B, R>(
    &self,
    request: &http::Request<B>,
    response: &http::Response<R>,
    duration: std::time::Duration,
) where
    B: http_body::Body,
    R: http_body::Body,
{
    let request_size = request.body().size();
    let response_size = response.body().size();

    let mut metrics = RequestMetrics::start();
    metrics.set_status_code(response.status().as_u16());
    metrics.set_server_address(response.headers().get("server").cloned().unwrap_or_default());
    metrics.set_request_body_size(request_size);
    metrics.set_response_body_size(response_size);
    metrics.set_duration(duration.as_nanos() as u64);
    metrics.end();
}

