    slot: Slot,
    threshold: u64,
    transactions: &[(usize, Signature, Hash, bool, TransactionStatusMeta, VersionedTransaction)],
) {
    for (index, signature, _hash, _is_vote, status, transaction) in transactions {
        if let Some(compute_units_consumed) = status.compute_units_consumed {
            if compute_units_consumed > threshold {
                notifier.notify_transaction(slot, *signature, transaction, index, _is_vote);
            }
        }
    }
}

