use crate::state::State;
use std::io;
use std::process::{Command, Stdio};

fn list_images_by_repository(state: &State, repo: &str) -> io::Result<Vec<String>> {
    let output = Command::new("docker")
        .arg("image")
        .arg("ls")
        .arg("--format")
        .arg("{{.Repository}}:{{.Tag}}\t{{.ID}}")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("Failed to execute docker command")
        .wait_with_output()?;

    let output_str = String::from_utf8(output.stdout).expect("Invalid UTF-8 in docker output");

    let mut image_ids = Vec::new();
    for line in output_str.lines() {
        let parts: Vec<&str> = line.split('\t').collect();
        if parts.len() < 2 {
            continue;
        }
        let repo_tag = parts[0];
        let image_id = parts[1];
        if repo_tag == repo {
            image_ids.push(image_id.to_string());
        }
    }

    Ok(image_ids)
}

fn send_and_wait_confirmation(
    &self,
    transaction: &Transaction,
    max_blocks: u64,
) -> TransportResult<Signature> {
    let signature = self.send(transaction)?;
    let mut confirmed = false;
    let mut blockhash_expiry = 0;

    while !confirmed && blockhash_expiry < max_blocks {
        let result = self.get_transaction(&signature);
        match result {
            Ok(Some(tx)) => {
                if tx.confirmations >= 1 {
                    confirmed = true;
                } else {
                    blockhash_expiry = tx.blockhash_expiry;
                }
            }
            Ok(None) => {
                // Transaction not found, check blockhash expiry
                let blockhash = self.get_blockhash()?;
                let expiry = blockhash.expiry;
                blockhash_expiry = expiry - self.get_blockhash().unwrap().expiry;
            }
            Err(e) => {
                // Handle error, e.g., retry or return error
                return Err(e);
            }
        }

        if !confirmed {
            sleep(Duration::from_secs(1)).await;
        }
    }

    if confirmed {
        Ok(signature)
    } else {
        Err(TransportError::new("Transaction confirmation timed out"))
    }
}

