#[derive(Debug, thiserror::Error)]
pub enum SelectGatewayError {
    #[error("Failed to get gateways from API")]
    GetGatewaysFailed,
    #[error("Failed to process gateways")]
    ProcessingFailed,
}

pub trait LightningFederationApi {
    fn get_gateways(&self) -> Result<HashMap<SafeUrl, u64>, SelectGatewayError>;
}

fn count_gateway_usage(gateways: &HashMap<SafeUrl, u64>) -> HashMap<SafeUrl, u64> {
    let mut usage_count = HashMap::new();
    for (&gateway, &usage) in gateways {
        *usage_count.entry(gateway).or_insert(0) += usage;
    }
    usage_count
}

fn sort_gateways_by_least_used(gateways: &HashMap<SafeUrl, u64>) -> Vec<SafeUrl> {
    let mut sorted: Vec<_> = gateways.iter().map(|(k, v)| (k, v)).collect();
    sorted.sort_by(|a, b| a.1.cmp(&b.1));
    sorted.into_iter().map(|(k, _)| k.clone()).collect()
}

pub fn gateways_by_least_used(api: &dyn LightningFederationApi) -> Result<Vec<SafeUrl>, SelectGatewayError> {
    let gateways = api.get_gateways()?;
    let usage_count = count_gateway_usage(&gateways);
    let sorted_gateways = sort_gateways_by_least_used(&usage_count);
    Ok(sorted_gateways)
}

