fn run(self) -> Result<(), Box<dyn std::error::Error>> {
    let RpcClient::Nonblocking(client) = self.client;
    let commitment_config = CommitmentConfig::confirmed();
    let interval = interval(Duration::from_secs(60));

    tokio::spawn(async move {
        interval.await;
        loop {
            interval.await;
            let blockhash = match Source::Cluster.fetch(&client, &commitment_config).await {
                Ok(blockhash) => blockhash,
                Err(e) => {
                    tracing::warn!("Failed to fetch blockhash from cluster: {}", e);
                    continue;
                }
            };
            // Use the blockhash as needed, e.g., update a shared state or trigger a refresh
            tracing::info!("Fetched new blockhash: {}", blockhash);
        }
    });

    Ok(())
}

