    let mut results = Vec::new();
    for (port, transport) in ports {
        match action {
            "open" => {
                let result = open_port(port, transport)?;
                results.push(result as i32);
            }
            "close" => {
                let result = close_port(port, transport)?;
                results.push(result as i32);
            }
            _ => return Err(JujuError::new("Invalid action specified. Use 'open' or 'close'")),
        }
    }
    Ok(results)
}

