fn summarize_peers(events: &[identify::Event]) -> Vec<String> {
    events.iter()
        .filter_map(|event| match event {
            identify::Event::Identified(peer, info) => {
                let peer_id = peer.to_string();
                let protocol_version = info.protocol_version;
                let agent_version = info.agent_version;
                let observed_address = info.observed_address.map_or(String::from("None"), |addr| addr.to_string());
                Some(format!(
                    "PeerId: {}, Protocol Version: {}, Agent Version: {}, Observed Address: {}",
                    peer_id, protocol_version, agent_version, observed_address
                ))
            }
            _ => None,
        })
        .collect()
}

use ckb_app_config::{AppConfig, ExitCode};

fn validate_logger_config(config: &AppConfig) -> Result<(), ExitCode> {
    // Check if log level is specified
    if config.logger.level.is_none() {
        return Err(ExitCode::ConfigInvalid);
    }

    // Check if at least one output destination is enabled
    let has_output = config.logger.output.stdout || config.logger.output.file.is_some();
    if !has_output {
        return Err(ExitCode::ConfigInvalid);
    }

    Ok(())
}

use rand;
use std::vec::Vec;

fn build_custom_query(service_name: &str) -> Vec<u8> {
    // mDNS query packet structure:
    // [Header] [Question] [Answer] [Authority] [Additional]
    // For a minimal query, we include only the Header and Question sections.

    let mut packet = Vec::new();

    // Header (12 bytes)
    packet.push(0x00); // Transaction ID
    packet.push(0x00);
    packet.push(0x00); // Flags: QR=0 (query), OPCODE=0, AA=0, TC=0, RD=1, RA=0, Z=0, RCODE=0
    packet.push(0x81);
    packet.push(0x00); // QDCOUNT = 1
    packet.push(0x00);
    packet.push(0x00); // ANCOUNT = 0
    packet.push(0x00);
    packet.push(0x00); // NSCOUNT = 0
    packet.push(0x00);
    packet.push(0x00); // ARCOUNT = 0

    // Question section (name + type + class)
    // Name: encode as a sequence of labels with length octets
    let name = service_name;
    let mut name_bytes = Vec::new();
    let mut current = 0;
    let name_bytes = encode_domain_name(name, &mut name_bytes);

    // Type: PTR (53)
    packet.extend_from_slice(&[0x00, 0x53]);
    // Class: IN (1)
    packet.extend_from_slice(&[0x00, 0x01]);

    packet.extend_from_slice(&name_bytes);

    packet
}

fn encode_domain_name(name: &str, bytes: &mut Vec<u8>) -> Vec<u8> {
    let mut current = 0;
    let name_bytes = name.as_bytes();
    let mut offset = 0;

    while current < name_bytes.len() {
        let mut label_len = 0;
        while current + label_len < name_bytes.len() && name_bytes[current + label_len] != b'.' {
            label_len += 1;
        }

        if label_len > 0 {
            bytes.push(label_len as u8);
            bytes.extend_from_slice(&name_bytes[current..current + label_len]);
            current += label_len + 1;
        } else {
            // Handle empty label (end of name)
            bytes.push(0);
            break;
        }
    }

    bytes
}

use freedesktop_icons::lookup;
use std::path::PathBuf;

fn find_svg_or_png(name: &str, theme: &str, size: u16, scale: u16) -> Option<PathBuf> {
    // First try to find SVG icon
    if let Some(svg_path) = lookup(name, theme, size, scale, true) {
        return Some(svg_path);
    }

    // If SVG not found, try to find PNG icon
    lookup(name, theme, size, scale, false)
}

fn process_error(response: Response) -> Result<PingResponse, CustomError> {
    let status = response.status();
    if status.is_success() {
        let body = response.text().await?;
        let ping_response: PingResponse = serde_json::from_str(&body)?;
        Ok(ping_response)
    } else {
        let error_response: TwirpErrorResponse = response.json().await?;
        let code = error_response.code;
        let message = error_response.message;
        let meta = error_response.meta;
        Err(CustomError::Twirp {
            message,
            code,
            meta,
        })
    }
}

