use vortex_array::{ArrayRef, IntoArray};
use vortex_array::arrays::PrimitiveArray;
use vortex_buffer::BufferMut;
use vortex_dtype::datetime::{TemporalMetadata, TimeUnit};
use vortex_error::{VortexResult, vortex_bail};
use crate::{DateTimePartsArray, DateTimePartsVTable};

fn time_difference_ns(lhs: &DateTimePartsArray, rhs: &DateTimePartsArray) -> VortexResult<ArrayRef> {
    // Validate that both arrays have the same length
    if lhs.len() != rhs.len() {
        vortex_bail!("Arrays must have the same length");
    }

    // Validate that both arrays have compatible temporal metadata
    if lhs.metadata() != rhs.metadata() {
        vortex_bail!("Arrays must have compatible temporal metadata");
    }

    let metadata = lhs.metadata().clone();
    let time_unit = metadata.time_unit;
    let time_scale = match time_unit {
        TimeUnit::Nanoseconds => 1,
        TimeUnit::Microseconds => 1000,
        TimeUnit::Milliseconds => 1_000_000,
        TimeUnit::Seconds => 1_000_000_000,
        TimeUnit::Minutes => 60_000_000_000,
        TimeUnit::Hours => 3_600_000_000_000,
        TimeUnit::Days => 86_400_000_000_000,
    };

    // Calculate the difference in nanoseconds
    let lhs_data = lhs.data();
    let rhs_data = rhs.data();
    let mut result_data = BufferMut::new(lhs.len() * std::mem::size_of::<i64>());

    let lhs_values = lhs_data.as_slice();
    let rhs_values = rhs_data.as_slice();
    let result_values = result_data.as_mut_slice();

    for i in 0..lhs.len() {
        let lhs_val = i64::from_le_bytes(lhs_values[i * 8..(i + 1) * 8].try_into().unwrap());
        let rhs_val = i64::from_le_bytes(rhs_values[i * 8..(i + 1) * 8].try_into().unwrap());
        let diff = lhs_val as i128 - rhs_val as i128;
        let diff_ns = diff * time_scale as i128;
        let diff_ns = diff_ns as i64;
        let diff_ns_bytes = diff_ns.to_le_bytes();
        result_values[i * 8..(i + 1) * 8].copy_from_slice(&diff_ns_bytes);
    }

    let result_array = PrimitiveArray::new(
        metadata.dtype().with_unit(TimeUnit::Nanoseconds),
        result_data.into(),
    );

    Ok(result_array.into())
}

fn add_cloud_trace_fields(
    json: &mut serde_json::Map<String, serde_json::Value>,
    config: &CloudTraceConfiguration,
    trace_id: &str,
    span_id: u64,
    sampled: bool,
) {
    if config.enabled {
        if let Some(trace_field) = config.trace_field {
            json.insert(trace_field, Value::String(trace_id.to_string()));
        }
        if let Some(span_id_field) = config.span_id_field {
            json.insert(span_id_field, Value::String(format!("{span_id:016x}")));
        }
        if let Some(sampled_field) = config.sampled_field {
            json.insert(sampled_field, Value::Bool(sampled));
        }
    }
}

fn window_with_activation(event_loop: &dyn winit::event_loop::ActiveEventLoop, title: &str) -> Result<Box<dyn winit::window::Window>, winit::error::RequestError> {
