use gluesql_core::data::Key;
use crate::row::key::KeyIntoBson;
use crate::row::value::IntoBson;

fn update_by_id(storage: &MongoStorage, table_name: &str, key: Key, new_values: HashMap<&str, Value>) -> Result<()> {
    // Convert the primary key to a BSON document
    let key_doc = key.into_bson()?;

    // Convert new_values to a BSON document
    let mut update_doc = doc! {};
    for (field, value) in new_values {
        update_doc.insert(field, value.into_bson()?);
    }

    // Update the document in MongoDB
    let collection = storage.client.collection(table_name);
    let result = collection.update_one(key_doc, doc! { "$set": update_doc }, None);

    // Handle the result
    match result {
        Ok(_) => Ok(()),
        Err(e) => Err(e).context("Failed to update document by ID"),
    }
}

