use totp_rs::{TOTP, Secret};

fn steam_token_flow(secret_b32: &str, account_name: &str) -> Result<(String, bool), String> {
    // Parse the base32 secret
    let secret = Secret::new(secret_b32).map_err(|e| e.to_string())?;

    // Create a TOTP instance with the account name and secret
    let totp = TOTP::new(&secret, account_name).map_err(|e| e.to_string())?;

    // Generate the current TOTP token
    let current_token = totp.now().map_err(|e| e.to_string())?;

    // Validate the token against the same instance
    let is_valid = totp.verify(&current_token).map_err(|e| e.to_string())?;

    Ok((current_token, is_valid))
}

fn build_conventional_commit(
    typ: &str,
    scope: Option<&str>,
    description: &str,
    body: Option<&str>,
    footers: Option<&[&str]>,
) -> String {
    let mut message = String::new();
    let mut scope_str = String::new();

    if let Some(scope) = scope {
        scope_str.push_str(scope);
        scope_str.push(':');
    }

    message.push_str(typ);
    message.push_str(&scope_str);
    message.push_str(" ");
    message.push_str(description);

    if let Some(body) = body {
        message.push('\n');
        message.push_str(body);
    }

    if let Some(footers) = footers {
        for &footer in footers {
            message.push('\n');
            message.push_str(footer);
        }
    }

    message
}

fn parse_custom_fill_color(fill: &str) -> Result<Color> {
    if fill.starts_with('#') {
        // Check if it's a hex color
        if fill.len() == 4 || fill.len() == 7 {
            let hex = &fill[1..];
            if hex.len() == 3 || hex.len() == 6 {
                let mut rgb = [0u8; 3];
                for (i, c) in hex.chars().enumerate() {
                    let index = i * 2;
                    if index >= 6 {
                        break;
                    }
                    let value = c.to_digit(16).ok_or(anyhow!("Invalid hex character"))?;
                    rgb[index / 2] = (value as u8) << 4 | (value as u8);
                }
                return Ok(Color::rgb(rgb[0], rgb[1], rgb[2]));
            }
        }
        bail!("Invalid hex color format");
    } else {
        // Check if it's a named color
        let color = Color::from_str(fill).map_err(|_| anyhow!("Invalid named color"))?;
        return Ok(color);
    }
    bail!("Invalid color format")
}

fn upload_image_with_retry(client: &Client, image_id: &str, data: Vec<u8>) -> Result<(), SdkErr> {
    let mut retries = 3;
    let mut delay = Duration::from_secs(1);

    loop {
        match client.upload_image(image_id, data.clone()) {
            Ok(_) => return Ok(()),
            Err(e) => {
                if retries == 0 {
                    return Err(e);
                }
                retries -= 1;
                tokio::time::sleep(delay).await;
                delay = delay * 2;
            }
        }
    }
}

use ssi_jwk::JWK;
use ssi_caips::caip10::BlockchainAccountId;
use ssi_caips::caip2::ChainId;
use crate::GenerateError;

fn generate_account_id(jwk: &JWK, namespace: &str, reference: &str) -> Result<BlockchainAccountId, GenerateError> {
    let chain_id = match namespace {
        "tezos" => ChainId::try_from("eip155:1").map_err(|_| GenerateError::InvalidChainId)?,
        "eip155" => ChainId::try_from("eip155:1").map_err(|_| GenerateError::InvalidChainId)?,
        _ => return Err(GenerateError::UnsupportedNamespace),
    };

    let account_id = match namespace {
        "tezos" => {
            let public_key = jwk.to_public_key()?;
            let hash = blake2b::blake2b_256(public_key.as_bytes());
            let hash_hex = hex::encode(hash);
            BlockchainAccountId::new(chain_id, hash_hex)
        },
        "eip155" => {
            let public_key = jwk.to_public_key()?;
            let hash = keccak::keccak256(public_key.as_bytes());
            let hash_hex = hex::encode(hash);
            BlockchainAccountId::new(chain_id, hash_hex)
        },
        _ => return Err(GenerateError::UnsupportedNamespace),
    };

    Ok(account_id)
}

fn rolling_variance<I, F>(iter: &mut I, window_size: usize) -> Vec<F>
where
    I: Iterator<Item = F>,
    F: Float + FromPrimitive + AddAssign + SubAssign,
{
    let mut rolling = Rolling::new(window_size);
    let mut variance = Variance::new();
    let mut result = Vec::new();

    for item in iter {
        rolling.add(item);
        variance.add(item);

        if rolling.len() == window_size {
            result.push(variance.variance());
        }
    }

    result
}

use anyhow::Result;
use collections::HashSet;
use fs::Fs;
use gpui::AsyncApp;
use std::path::{Path, PathBuf};
use std::ops::ControlFlow;
use crate::Prettier;
use serde_json::Value;

fn load_prettier_config(
    fs: &dyn Fs,
    file_path: &Path,
    cx: &mut AsyncApp,
) -> Result<Value> {
    let mut config = Value::Object(HashMap::new());
    let mut config_paths = HashSet::new();
    let mut config_files = Vec::new();

    // Find all Prettier configuration files
    let config_files = find_config_files(fs, file_path, &mut config_paths, cx)?;

    // Load each configuration file
    for config_file in config_files {
        let config_content = fs.read_to_string(&config_file, cx)?;
        let config_value: Value = serde_json::from_str(&config_content)?;
        merge_config(&mut config, &config_value, cx)?;
    }

    Ok(config)
}

fn find_config_files(
    fs: &dyn Fs,
    file_path: &Path,
    config_paths: &mut HashSet<PathBuf>,
    cx: &mut AsyncApp,
) -> Result<Vec<PathBuf>> {
    let mut config_files = Vec::new();
    let mut current_dir = file_path.parent().unwrap_or(Path::new(".")).to_path_buf();

    loop {
        let config_path = current_dir.join(".prettierrc");
        if fs.exists(&config_path, cx)? {
            config_files.push(config_path);
            config_paths.insert(config_path);
        }

        let config_path = current_dir.join("prettierrc");
        if fs.exists(&config_path, cx)? {
            config_files.push(config_path);
            config_paths.insert(config_path);
        }

        let config_path = current_dir.join(".prettierignore");
        if fs.exists(&config_path, cx)? {
            config_paths.insert(config_path);
        }

        let config_path = current_dir.join("prettierignore");
        if fs.exists(&config_path, cx)? {
            config_paths.insert(config_path);
        }

        if current_dir == Path::new(".") {
            break;
        }

        current_dir = current_dir.parent().unwrap_or(&Path::new(".")).to_path_buf();
    }

    Ok(config_files)
}

fn merge_config(
    target: &mut Value,
    source: &Value,
    cx: &mut AsyncApp,
) -> Result<()> {
    match (target, source) {
        (Value::Object(target_obj), Value::Object(source_obj)) => {
            for (key, value) in source_obj {
                if let Some(target_value) = target_obj.get_mut(key) {
                    merge_config(target_value, value, cx)?;
                } else {
                    target_obj.insert(key.clone(), value.clone());
                }
            }
        }
        _ => {
            // If the target is not an object, just replace it with the source
            *target = source.clone();
        }
    }

    Ok(())
}

fn validate_uncle_cross_chains<P: UncleProvider>(
    provider: &P,
    uncle: &HeaderView,
    block_number: BlockNumber,
) -> Result<(), UnclesError> {
    // Check if the uncle is part of the main chain
    if provider.is_main_chain_uncle(uncle)? {
        // Ensure the uncle is not already included in another block
        if provider.is_uncle_included(uncle, block_number)? {
            return Err(UnclesError::DoubleUncleInclusion);
        }
    }

    // Check if the uncle is part of an alternate chain
    if provider.is_alternate_chain_uncle(uncle)? {
        // Ensure the uncle is not already included in another block
        if provider.is_uncle_included(uncle, block_number)? {
            return Err(UnclesError::DoubleUncleInclusion);
        }

        // Verify the ancestor relationship with the main chain
        if !provider.is_ancestor_of_main_chain(uncle, block_number)? {
            return Err(UnclesError::InvalidUncleAncestor);
        }
    }

    Ok(())
}

fn total_fees_by_account(account: &Pubkey, transactions: &[TransactionWithStatusMeta]) -> u64 {
    transactions
        .iter()
        .filter_map(|tx| {
            let tx = &tx.transaction;
            let meta = &tx.meta;
            if let Some(fee) = meta.get_fee() {
                if tx.is_signer(account) || tx.keys().any(|key| *key == *account) {
                    Some(*fee)
                } else {
                    None
                }
            } else {
                None
            }
        })
        .sum()
}

