use ckb_types::{U256, packed::Byte32};
use ckb_error::Error;
use crate::Shared;
use crate::types::HeaderIndexView;

fn calculate_chain_total_difficulty(&self, block_hash: &Byte32) -> Result<U256, Error> {
    let mut total_difficulty = U256::zero();
    let mut current_hash = *block_hash;

    while current_hash != Byte32::zero() {
        if let Some(header_index) = self.get_header_index(&current_hash) {
            if let Some(header) = header_index.get_header() {
                total_difficulty = total_difficulty.saturating_add(header.total_difficulty());
                current_hash = header.parent_hash();
            } else {
                return Err(Error::HeaderNotFound);
            }
        } else {
            return Err(Error::HeaderNotFound);
        }
    }

    Ok(total_difficulty)
}

use crate::{cbor_values_equal, ProtocolTestFailure, pretty_comparison};
use base64_simd;
use ciborium::de;

fn validate_cbor_body(actual_body: &[u8], expected_body_base64: &str) -> Result<(), ProtocolTestFailure> {
    // Decode the expected body from base64
    let expected_bytes = base64_simd::decode(expected_body_base64).map_err(|_| ProtocolTestFailure::InvalidBase64)?;

    // Decode the expected CBOR value
    let expected_value = match de::from_reader(&expected_bytes[..]) {
        Ok(value) => value,
        Err(_) => return Err(ProtocolTestFailure::InvalidCbor),
    };

    // Decode the actual CBOR value
    let actual_value = match de::from_reader(actual_body) {
        Ok(value) => value,
        Err(_) => return Err(ProtocolTestFailure::InvalidCbor),
    };

    // Check if the actual and expected CBOR values are semantically equal
    if cbor_values_equal(&actual_value, &expected_value) {
        Ok(())
    } else {
        Err(ProtocolTestFailure::CborValuesNotEqual {
            actual: pretty_comparison(&actual_value),
            expected: pretty_comparison(&expected_value),
        })
    }
}

fn rename_resources(
    resources: &[&cloudformation::types::StackResourceSummary],
    id_map: &HashMap<String, String>,
) -> Result<HashMap<String, String>, Box<dyn std::error::Error>> {
    let mut result = HashMap::new();
    let mut missing_ids = Vec::new();

    for resource in resources {
        let old_id = resource.logical_resource_id.clone();
        let new_id = id_map.get(&old_id).ok_or_else(|| {
            format!("Missing mapping for resource ID: {}", old_id).into()
        })?;

        result.insert(new_id.clone(), old_id);
    }

    if !missing_ids.is_empty() {
        return Err(format!("Missing mappings for IDs: {:?}", missing_ids).into());
    }

    Ok(result)
}

fn send_transaction_with_retry(&self, transaction: &Transaction, max_retries: u8) -> TransportResult<()> {
    let mut attempts = 0u8;
    let mut delay = Duration::from_millis(100);
    loop {
        if self.send_transaction(transaction).await {
            return Ok(());
        }
        if attempts >= max_retries {
            return Err(std::io::Error::other("max retries exceeded").into());
        }
        sleep(delay).await;
        delay *= 2;
        attempts += 1;
    }
}

fn count_and_report_redundant_directives(ctx: &Context) -> Result<(), miette::Report> {
    let mut directive_counts = HashMap::new();
    let mut duplicate_directives = HashMap::new();

    for type_def in &ctx.schema.types {
        if let Some(type_kind) = type_def.kind {
            match type_kind {
                TypeKind::Object => {
                    for field in &type_def.fields {
                        let field_name = field.name.clone();
                        let mut field_directives = HashSet::new();

                        for directive in &field.directives {
                            let directive_name = directive.name.clone();
                            let key = (field_name.clone(), directive_name.clone());

                            if field_directives.contains(&directive_name) {
                                duplicate_directives.entry(key).or_insert_with(Vec::new).push(directive_name.clone());
                            } else {
                                field_directives.insert(directive_name.clone());
                            }

                            *directive_counts.entry(directive_name.clone()).or_insert(0) += 1;
                        }
                    }
                }
                TypeKind::Interface => {
                    for field in &type_def.fields {
                        let field_name = field.name.clone();
                        let mut field_directives = HashSet::new();

                        for directive in &field.directives {
                            let directive_name = directive.name.clone();
                            let key = (field_name.clone(), directive_name.clone());

                            if field_directives.contains(&directive_name) {
                                duplicate_directives.entry(key).or_insert_with(Vec::new).push(directive_name.clone());
                            } else {
                                field_directives.insert(directive_name.clone());
                            }

                            *directive_counts.entry(directive_name.clone()).or_insert(0) += 1;
                        }
                    }
                }
                TypeKind::Union => {
                    // No fields, so no directives to check
                }
                TypeKind::Enum => {
                    // No fields, so no directives to check
                }
                TypeKind::Scalar => {
                    // No fields, so no directives to check
                }
                TypeKind::InputObject => {
                    // No fields, so no directives to check
                }
                TypeKind::EnumValue => {
                    // No fields, so no directives to check
                }
                TypeKind::Directive => {
                    // No fields, so no directives to check
                }
                _ => {}
            }
        }
    }

    if !duplicate_directives.is_empty() {
        for (key, directives) in duplicate_directives {
            let (field_name, directive_name) = key;
            let message = format!("Directive '{directive_name}' is applied more than once to field '{field_name}'.");
            return Err(miette::Report::new(message));
        }
    }

    Ok(())
}

use crate::{IndexerConnection, queries::{register_indexer_asset, asset_already_exists, IndexerAsset}};  
use fuel_indexer_database_types::IndexerAssetType;  
use sqlx::postgres::PgPoolOptions;  
use sqlx::Row;  
use std::collections::HashSet;  

fn bulk_register_indexer_assets(  
    conn: &mut IndexerConnection,  
    assets: Vec<(String, String, IndexerAssetType, Vec<u8>, Option<String>)>,  
) -> sqlx::Result<Vec<IndexerAsset>> {  
    let mut inserted_assets = Vec::new();  
    let mut seen_digests = HashSet::new();  

    for (name, content_type, asset_type, content, metadata) in assets {  
        let digest = if let Some(digest) = get_sha256_digest(&content) {  
            digest  
        } else {  
            continue;  
        };  

        if seen_digests.contains(&digest) {  
            continue;  
        }  

        seen_digests.insert(digest.clone());  

        if asset_already_exists(conn, &digest)? {  
            continue;  
        }  

        let asset = register_indexer_asset(conn, name, content_type, asset_type, &digest, metadata)?;  
        inserted_assets.push(asset);  
    }  

    Ok(inserted_assets)  
}  

fn get_sha256_digest(content: &[u8]) -> Option<String> {  
    use sha2::{Digest, Sha256};  
    let mut hasher = Sha256::new();  
    hasher.update(content);  
    let result = hasher.finalize();  
    Some(format!("{:x}", result))  
}

