fn set_locale_all(locale: &str) -> Result<String, io::Error> {
    let c_locale = CString::new(locale).map_err(|e| io::Error::new(io::ErrorKind::InvalidInput, e))?;
    let prev_locale = unsafe { setlocale(0, c_locale.as_ptr()) };

    if prev_locale.is_null() {
        return Err(io::Error::new(io::ErrorKind::Other, "Failed to set locale"));
    }

    let prev_locale_str = unsafe { CStr::from_ptr(prev_locale).to_string_lossy().into_owned() };
    let _ = unsafe { setlocale(0, c_locale.as_ptr()) };

    Ok(prev_locale_str)
}

