use lightspeed_scheduler::{Job, JobScheduler, Scheduler, SchedulerError};
use chrono::{Utc};
use chrono_tz::UTC;
use std::sync::Arc;
use tokio::sync::Mutex;
use std::time::Duration;

struct JobState {
    attempt_count: usize,
}

impl JobState {
    fn new() -> Self {
        JobState { attempt_count: 0 }
    }

    fn increment_attempt(&mut self) {
        self.attempt_count += 1;
    }

    fn get_attempt_count(&self) -> usize {
        self.attempt_count
    }
}

async fn job_task(job_state: Arc<Mutex<JobState>>) {
    let mut state = job_state.lock().await;
    let attempt_count = state.get_attempt_count();

    if attempt_count >= 3 {
        println!("Job succeeded after 3 attempts.");
        return;
    }

    // Simulate job execution that may fail
    if attempt_count == 0 {
        println!("Job failed. Retrying...");
        state.increment_attempt();
        return;
    } else if attempt_count == 1 {
        println!("Job failed again. Retrying...");
        state.increment_attempt();
        return;
    } else {
        println!("Job succeeded after 3 attempts.");
    }
}

fn create_job() -> Job {
    let job_state = Arc::new(Mutex::new(JobState::new()));
    let job = Job::new("periodic_job", move || {
        let job_state = Arc::clone(&job_state);
        async move {
            job_task(job_state).await;
            Ok(())
        }
    });

    job
}

fn schedule_job(scheduler: &mut JobScheduler) -> Result<(), SchedulerError> {
    let job = create_job();
    let utc_time = UTC.ymd(2025, 1, 1).and_hms(0, 0, 0);
    scheduler.schedule(job, utc_time, Duration::seconds(86400))
}

