use zvariant::Value;
use std::collections::HashMap;
use serde::Serialize;

fn serialize_non_optional<T>(value: &T) -> Result<HashMap<String, Value<'static>>, zvariant::Error>
where
    T: Type + Serialize,
{
    let mut dict = HashMap::new();
    let mut fields = value.type_().fields();

    while let Some(field) = fields.next() {
        let field_name = field.name();
        let field_value = value.get_field(field.index()).unwrap();

        if !field.is_optional() {
            let serialized = serde_json::to_value(field_value).map_err(|e| zvariant::Error::Message(format!("Failed to serialize field {}: {}", field_name, e)))?;
            dict.insert(field_name.to_string(), Value::from(serialized));
        }
    }

    Ok(dict)
}

fn fetch_posts_with_associations(query: &Query) -> Result<Vec<Map>, Error> {
    let posts = query.find::<Post>(Post::table())?;
    let mut post_maps = posts.into_iter().map(|post| post.into_map()).collect::<Vec<Map>>();

    if post_maps.is_empty() {
        return Ok(post_maps);
    }

    let post_ids: Vec<Uuid> = post_maps.iter()
        .filter_map(|map| map.get("id").and_then(|id| id.as_uuid()))
        .collect();

    let author_ids: Vec<Uuid> = post_maps.iter()
        .filter_map(|map| map.get("author").and_then(|id| id.as_uuid()))
        .collect();

    let comment_ids: Vec<Uuid> = post_maps.iter()
        .filter_map(|map| {
            if let Some(comment_ids) = map.get("comments") {
                if let Some(ids) = comment_ids.as_array() {
                    ids.iter()
                        .filter_map(|id| id.as_uuid())
                        .collect::<Vec<Uuid>>()
                } else {
                    None
                }
            } else {
                None
            }
        })
        .flatten()
        .collect();

    let users = if !author_ids.is_empty() {
        let user_query = Query::new().filter("id", &author_ids);
        user_query.find::<User>(User::table())?
    } else {
        Vec::new()
    };

    let user_map = users.into_iter()
        .map(|user| user.into_map())
        .collect::<Vec<Map>>();
    let user_map_by_id: std::collections::HashMap<Uuid, Map> = user_map.into_iter()
        .filter_map(|map| {
            if let Some(id) = map.get("id").and_then(|id| id.as_uuid()) {
                Some((id, map))
            } else {
                None
            }
        })
        .collect();

    let comments = if !comment_ids.is_empty() {
        let comment_query = Query::new().filter("id", &comment_ids);
        comment_query.find::<Comment>(Comment::table())?
    } else {
        Vec::new()
    };

    let comment_map = comments.into_iter()
        .map(|comment| comment.into_map())
        .collect::<Vec<Map>>();
    let comment_map_by_id: std::collections::HashMap<Uuid, Map> = comment_map.into_iter()
        .filter_map(|map| {
            if let Some(id) = map.get("id").and_then(|id| id.as_uuid()) {
                Some((id, map))
            } else {
                None
            }
        })
        .collect();

    for post_map in &mut post_maps {
        if let Some(id) = post_map.get("id").and_then(|id| id.as_uuid()) {
            if let Some(user) = user_map_by_id.get(&id) {
                post_map.insert("author".to_string(), user.clone());
            }
        }

        if let Some(comments) = post_map.get("comments").and_then(|c| c.as_array()) {
            let mut populated_comments = Vec::new();
            for comment_id in comments {
                if let Some(id) = comment_id.as_uuid() {
                    if let Some(comment) = comment_map_by_id.get(&id) {
                        populated_comments.push(comment.clone());
                    }
                }
            }
            post_map.insert("comments".to_string(), populated_comments);
        }
    }

    Ok(post_maps)
}

use ansi_term::{Style, Colour};

fn generate_progress_bar(percent: f32) -> ansi_term::ANSIString<'static> {
    let bar_length = 20;
    let filled = (percent / 100.0 * bar_length as f32) as u32;
    let empty = bar_length - filled;

    let filled_str = "█".repeat(filled as usize);
    let empty_str = " ".repeat(empty as usize);

    let filled_style = if percent >= 70.0 {
        Style::new().fg(Colour::Green)
    } else if percent >= 40.0 {
        Style::new().fg(Colour::Yellow)
    } else {
        Style::new().fg(Colour::Red)
    };

    let empty_style = Style::new().fg(Colour::Black);

    let bar = filled_style.paint(filled_str) + &empty_style.paint(empty_str);
    format!("{}% {}", percent as u8, bar).into()
}

fn avro_extension_with_compression(
    format: &datafusion_datasource_avro::file_format::AvroFormat,
    compression: &datafusion_datasource::file_compression_type::FileCompressionType,
) -> datafusion_common::Result<String> {
    if !format.supports_compression() {
        return internal_err!("AvroFormat does not support compression");
    }

    match compression.variant() {
        CompressionTypeVariant::Uncompressed => Ok("avro".to_string()),
        CompressionTypeVariant::Deflate => Ok("avro.gz".to_string()),
        CompressionTypeVariant::Snappy => Ok("avro.snappy".to_string()),
        CompressionTypeVariant::Bzip2 => Ok("avro.bz2".to_string()),
        CompressionTypeVariant::Lz4 => Ok("avro.lz4".to_string()),
        CompressionTypeVariant::Zstd => Ok("avro.zstd".to_string()),
        _ => internal_err!("Unsupported compression type for Avro format"),
    }
}

fn fetch_decoys(ledger: &TestLedger, exclude: &[G1Projective], n: usize) -> Vec<DecoyInput> {
    let mut decoys = Vec::new();
    let mut excluded_set = BTreeSet::new();

    // Convert excluded public keys to compressed format for comparison
    for &pk in exclude {
        excluded_set.insert(pk.to_affine().to_compressed());
    }

    // Collect all commitments from the ledger
    for (&pk_bytes, &commitment) in &ledger.commitments {
        // Skip if this public key is in the exclusion list
        if excluded_set.contains(&pk_bytes) {
            continue;
        }

        // Create DecoyInput from the commitment
        let decoy = DecoyInput {
            commitment: commitment.into(),
            public_key: pk_bytes.into(),
        };

        decoys.push(decoy);

        // Stop once we've collected n decoys
        if decoys.len() >= n {
            break;
        }
    }

    decoys
}

