use bitvec_simd::BitVec;

fn resize_alternating(bitvec: &mut BitVec, new_len: usize) {
    let old_len = bitvec.len();
    if new_len <= old_len {
        return;
    }

    let mut new_bits = BitVec::new();
    new_bits.extend_from_slice(bitvec);
    let mut fill_pattern = false;

    for _ in old_len..new_len {
        new_bits.push(fill_pattern);
        fill_pattern = !fill_pattern;
    }

    *bitvec = new_bits;
}

use indextree::NodeId;
use crate::{Tree, Span};

fn format_tree_with_metadata(tree: &Tree, indent_level: usize) -> String {
    let mut result = String::new();
    let mut indent = "  ".repeat(indent_level);

    for node in &tree.nodes {
        let span = &node.span;
        let start_time = span.start_time;
        let end_time = span.end_time;
        let elapsed = end_time.saturating_duration_since(start_time);
        let is_long_running = elapsed.as_secs() > 5;

        let node_id = node.id;
        let parent_id = node.parent_id;

        let mut marker = "";
        if is_long_running {
            marker = "⚠️ ";
        }

        let mut metadata = String::new();
        if let Some(parent) = tree.nodes.get(parent_id) {
            metadata.push_str(&format!("Parent: {}", parent.id));
        }

        let line = format!(
            "{}{}[{}] {} {}ms ({})",
            indent,
            marker,
            node_id,
            span.name,
            elapsed.as_millis(),
            metadata
        );

        result.push_str(&line);
        result.push('\n');

        // Recursively format children
        let children = tree.nodes.iter().filter(|n| n.parent_id == node_id);
        for child in children {
            result.push_str(&format_tree_with_metadata(tree, indent_level + 1));
        }
    }

    result
}

fn start_auto_refresh(&mut self, interval: Duration) {
    let behaviour = self.behaviour.clone();
    let namespaces = self.namespaces.clone();

    tokio::spawn(async move {
        loop {
            time::sleep(interval).await;
            let mut behaviour = behaviour.lock().await;
            for namespace in namespaces.iter() {
                if let Some(peer_id) = behaviour.get_namespace(namespace).await {
                    behaviour.re_register_namespace(namespace, peer_id).await;
                }
            }
        }
    });
}

