fn is_incoming_waiting(module: &GatewayClientModule, op_id: OperationId) -> Result<bool, anyhow::Error> {
    let state_machines = module.state_machines();
    let state_machine = state_machines.get(&op_id).ok_or(anyhow::anyhow!("State machine not found for operation ID"))?;

    let mut stream = state_machine.notifier().subscribe();
