use permutate::{Permutator, PermutatorWrapper as _};

fn compute_indexes(lens: &[usize], mut n: usize) -> Vec<usize> {
    let mut indexes = Vec::new();
    let mut remaining = lens;
    let mut current_len = lens.len();

    while current_len > 0 {
        let mut factorial = 1;
        for _ in 1..current_len {
            factorial *= current_len;
        }
        let mut index = n / factorial;
        n %= factorial;
        indexes.push(index);
        remaining = &remaining[1..];
        current_len -= 1;
    }

    indexes
}

