use vortex_buffer::{Alignment, Buffer};

impl<T> Buffer<T> {
    pub fn slice_ref_with_alignment(&self, subset: &[T], alignment: Alignment) -> Self {
        if !alignment.is_aligned_to(Alignment::of::<T>()) {
            panic!("slice_ref alignment must at least align to type T");
        }
        if !self.alignment.is_aligned_to(alignment) {
            panic!("slice_ref subset alignment must at least align to the buffer alignment");
        }
        if subset.as_ptr().align_offset(*alignment) != 0 {
            panic!("slice_ref subset must be aligned to {:?}", alignment);
        }
        let subset_u8 = unsafe { std::slice::from_raw_parts(subset.as_ptr().cast(), std::mem::size_of_val(subset)) };
        Self {
            bytes: self.bytes.slice_ref(subset_u8),
            length: subset.len(),
            alignment,
            _marker: Default::default(),
        }
    }
}

