fn determine_payment_strategy(
    lightning_manager: &dyn IGatewayClientV1,
    payment_data: PaymentData,
) -> Result<PaymentStrategy, Error> {
    // Check if Lightning is available and suitable for the payment
    let lightning_available = lightning_manager.is_lightning_available()?;
    let lightning_fee = lightning_manager.estimate_lightning_fee(&payment_data)?;

    // Check if direct swap is possible with available federations
    let swap_possible = payment_data.federation_id.is_some() && lightning_manager.is_swap_supported()?;
    let swap_fee = if swap_possible {
        lightning_manager.estimate_swap_fee(&payment_data)?
    } else {
        // Default to a high fee if swap is not possible
        100000
    };

    // Compare fees and decide the optimal strategy
    if lightning_available && lightning_fee < swap_fee {
        Ok(PaymentStrategy::Lightning)
    } else if swap_possible {
        Ok(PaymentStrategy::DirectSwap)
    } else {
        Err(Error::NoAvailablePaymentMethod)
    }
}

