fn list_active_connections(transport: &mut Boxed<(PeerId, StreamMuxerBox)>) -> Result<Vec<(PeerId, StreamMuxerBox)>, Error> {
    let mut connections = Vec::new();
    let mut event_stream = transport.event_stream();

    while let Some(event) = event_stream.next().await {
        match event {
            TransportEvent::Connected(peer_id, muxer) => {
                connections.push((peer_id, muxer));
            }
            _ => {}
        }
    }

    Ok(connections)
}

