use std::path::Path;
use anyhow::anyhow;

#[derive(Debug)]
pub enum ArchiveFormat {
    Z,
    Zip,
    Gzip,
    Bzip2,
    Lz,
    Xz,
    Lzma,
    P7z,
    Tar,
    TarZ,
    TarGzip,
    TarBzip2,
    TarLz,
    TarXz,
    TarLzma,
    Tar7z,
    TarZstd,
    Rar,
    Zstd,
}

impl ArchiveFormat {
    pub fn get_archive_format_from_file_path<P: AsRef<Path>>(file_path: P) -> anyhow::Result<ArchiveFormat> {
        let file_path = file_path.as_ref();

        if let Some(file_name) = file_path.file_name() {
            if let Some(file_name) = file_name.to_str() {
                let file_name = file_name.to_ascii_lowercase();

                if file_name.ends_with("tar.z") {
                    return Ok(ArchiveFormat::TarZ);
                } else if file_name.ends_with(".tar.gz") || file_name.ends_with(".tgz") {
                    return Ok(ArchiveFormat::TarGzip);
                } else if file_name.ends_with(".tar.bz2") || file_name.ends_with(".tbz2") {
                    return Ok(ArchiveFormat::TarBzip2);
                } else if file_name.ends_with(".tar.lz") {
                    return Ok(ArchiveFormat::TarLz);
                } else if file_name.ends_with(".tar.xz") || file_name.ends_with(".txz") {
                    return Ok(ArchiveFormat::TarXz);
                } else if file_name.ends_with(".tar.lzma") || file_name.ends_with(".tlz") {
                    return Ok(ArchiveFormat::TarLzma);
                } else if file_name.ends_with(".tar.7z") || file_name.ends_with(".tar.7z.001") || file_name.ends_with(".t7z") {
                    return Ok(ArchiveFormat::Tar7z);
                } else if file_name.ends_with(".tar.zst") {
                    return Ok(ArchiveFormat::TarZstd);
                } else if file_name.ends_with(".tar") {
                    return Ok(ArchiveFormat::Tar);
                } else if file_name.ends_with(".z") {
                    return Ok(ArchiveFormat::Z);
                } else if file_name.ends_with(".zip") {
                    return Ok(ArchiveFormat::Zip);
                } else if file_name.ends_with(".gz") {
                    return Ok(ArchiveFormat::Gzip);
                } else if file_name.ends_with(".bz2") {
                    return Ok(ArchiveFormat::Bzip2);
                } else if file_name.ends_with(".lz") {
                    return Ok(ArchiveFormat::Lz);
                } else if file_name.ends_with(".xz") {
                    return Ok(ArchiveFormat::Xz);
                } else if file_name.ends_with(".lzma") {
                    return Ok(ArchiveFormat::Lzma);
                } else if file_name.ends_with(".7z") || file_name.ends_with(".7z.001") {
                    return Ok(ArchiveFormat::P7z);
                } else if file_name.ends_with(".rar") {
                    return Ok(ArchiveFormat::Rar);
                } else if file_name.ends_with(".zst") {
                    return Ok(ArchiveFormat::Zstd);
                }
            }
        }

        Err(anyhow!("Unknown archive format."))
    }
}

fn is_valid_archive_format<P: AsRef<Path>>(file_path: P) -> bool {
    ArchiveFormat::get_archive_format_from_file_path(file_path).is_ok()
}

use std::os::raw::{c_void, c_ulong};
use crate::{umash_params, umash_sink, umash_state, umash_fp_state, umash_fp};

extern "C" {
    fn umash_params_derive(params: *mut umash_params, bits: u64, key: *const c_void);
    fn umash_full(params: *const umash_params, seed: u64, which: i32, data: *const c_void, n_bytes: c_ulong) -> u64;
    fn umash_fprint(params: *const umash_params, seed: u64, data: *const c_void, n_bytes: c_ulong) -> umash_fp;
    fn umash_init(state: *mut umash_state, params: *const umash_params, seed: u64, which: i32);
    fn umash_sink_update(sink: *mut umash_sink, data: *const c_void, n_bytes: c_ulong);
    fn umash_digest(state: *const umash_state) -> u64;
    fn umash_fp_init(state: *mut umash_fp_state, params: *const umash_params, seed: u64);
    fn umash_fp_digest(state: *const umash_fp_state) -> umash_fp;
}

fn chunk_hashes(params: &umash_params, seed: u64, data: &[u8], chunk_size: usize) -> Vec<u64> {
    let mut hashes = Vec::new();
    let data_ptr = data.as_ptr() as *const c_void;
    let total_bytes = data.len() as c_ulong;

    for chunk_start in 0..total_bytes {
        let chunk_end = std::cmp::min(chunk_start + chunk_size, total_bytes);
        let chunk_len = chunk_end - chunk_start;
        let chunk_data = unsafe { std::slice::from_raw_parts(data_ptr.offset(chunk_start as isize), chunk_len as usize) };

        let hash = unsafe {
            umash_full(
                params as *const umash_params,
                seed,
                0,
                chunk_data.as_ptr() as *const c_void,
                chunk_len as c_ulong
            )
        };
        hashes.push(hash);
    }

    hashes
}

fn retry_request<T, P>(client: &HttpClient, method: &str, params: P, retries: usize) -> Result<T, Error>
where
    T: DeserializeOwned,
    P: ToRpcParams + Clone + Send,
{
    let mut remaining_retries = retries;
    loop {
        match client.request(method, params.clone()) {
            Ok(response) => return Ok(response),
            Err(err) if remaining_retries > 0 => {
                remaining_retries -= 1;
                // Optionally add a delay before retrying
                std::thread::sleep(std::time::Duration::from_millis(500));
                continue;
            }
            Err(err) => return Err(err),
        }
    }
}

use bswap::leu32;  
use bswap::u8::FromHexError;  

fn hex_to_leu32_vec(hex: &str) -> Result<Vec<u32>, FromHexError> {  
    let hex_str = hex.trim();  
    let hex_bytes = hex_str.as_bytes();  
    let mut result = Vec::new();  
    let mut buffer = [0u8; 4];  
    let mut index = 0;  

    while index + 4 <= hex_bytes.len() {  
        for i in 0..4 {  
            if index + i >= hex_bytes.len() {  
                break;  
            }  
            let byte = hex_bytes[index + i];  
            if !hex::is_hex_digit(byte) {  
                return Err(FromHexError::InvalidHexDigit);  
            }  
            buffer[i] = hex::hex_digit_to_u8(byte);  
        }  
        index += 4;  
        result.push(leu32::decode(&buffer));  
    }  

    Ok(result)  
}

