use libftdi1_sys::*;
use std::ffi::CStr;

fn setup_bitbang_mode(ftdi: *mut ftdi_context, bitmask: u8, mode: u8) -> Result<(), String> {
    unsafe {
        // Check if the FTDI context is valid
        if ftdi.is_null() {
            return Err("Invalid FTDI context".to_string());
        }

        // Reset the FTDI device
        let reset_result = ftdi_usb_reset(ftdi);
        if reset_result != 0 {
            return Err("Failed to reset FTDI device".to_string());
        }

        // Set the bitbang mode
        let set_result = ftdi_set_bitmode(ftdi, bitmask, mode);
        if set_result != 0 {
            return Err("Failed to set bitbang mode".to_string());
        }

        Ok(())
    }
}

fn ini_to_map(ini: &Ini) -> std::collections::HashMap<String, std::collections::HashMap<String, String>> {
    let mut result = std::collections::HashMap::new();
    let sections = ini.sections();

    // Handle the general section
    if let Some(general) = ini.get("general") {
        let mut general_map = std::collections::HashMap::new();
        for (key, value) in general {
            general_map.insert(key.to_string(), value.to_string());
        }
        result.insert("__General__".to_string(), general_map);
    }

    // Handle other sections
    for (section, entries) in sections {
        let mut section_map = std::collections::HashMap::new();
        for (key, value) in entries {
            section_map.insert(key.to_string(), value.to_string());
        }
        result.insert(section.to_string(), section_map);
    }

    result
}

use async_stream::stream;
use futures_util::stream::StreamExt;

fn merge_streams<S1, S2>(mut stream1: S1, mut stream2: S2) -> impl futures_core::stream::Stream<Item = (Option<S1::Item>, Option<S2::Item>)>
where
    S1: futures_core::stream::Stream + Unpin,
    S2: futures_core::stream::Stream + Unpin,
{
    stream! {
        loop {
            let item1 = stream1.next().await;
            let item2 = stream2.next().await;

            if item1.is_none() && item2.is_none() {
                break;
            }

            yield (item1, item2);
        }
    }
}

fn zip_streams_to_map<'en, K, V, KS, VS, E>(keys: KS, values: VS, encoder: E) -> Result<E::Ok, E::Error>
where
    KS: futures::stream::Stream<Item = K> + Send + Unpin,
    VS: futures::stream::Stream<Item = V> + Send + Unpin,
    K: destream::en::IntoStream<'en> + Send + 'en,
    V: destream::en::IntoStream<'en> + Send + 'en,
    E: destream::en::Encoder<'en>,
{
    let zipped = futures::stream::Zip::new(keys.map(|k| k.into_stream().map(|k| (k, None)))).zip(values.map(|v| v.into_stream().map(|v| (None, Some(v)))));
    let mut encoder = encoder;
    let mut result = Ok(encoder.encode_seq(zipped.map(|((k, _), (_, v))| (k, v))));

    futures::stream::FusedStream::fuse(zipped).for_each(|((k, _), (_, v))| {
        if let Err(e) = encoder.encode_item((k, v)) {
            result = Err(e);
        }
        Ok(())
    }).await;

    result
}

fn build_filtered_query<Id: IdType, Data: DataType, CODEC: JsonCodec<Data>>(
    &self,
    filters: Vec<(String, String, String)>,
) -> String {
    let mut query = "SELECT * FROM ".to_string();
    query.push_str(self.table_name.as_str());
    query.push_str(" WHERE ");

    let mut conditions = Vec::new();

    for (field, op, value) in filters {
        let condition = match op.as_str() {
            "=" => format!("{} = {}", field, value),
            "LIKE" => format!("{} LIKE {}", field, value),
            "IN" => {
                let values: Vec<String> = value
                    .split(',')
                    .map(|s| s.trim().to_string())
                    .collect();
                format!("{} IN ({})", field, values.join(", "))
            }
            "BETWEEN" => {
                let parts: Vec<&str> = value.split_whitespace().collect();
                if parts.len() != 2 {
                    return "ERROR: Invalid BETWEEN clause".to_string();
                }
                format!("{} BETWEEN {} AND {}", field, parts[0], parts[1])
            }
            _ => return "ERROR: Unknown operator".to_string(),
        };
        conditions.push(condition);
    }

    query.push_str(&conditions.join(" AND "));
    query
}

