fn select_compressed<'a, F: EmbedableFile>(file: &'a F, accept_encoding: &str) -> (&'a [u8], &'static str) {
    let mut encodings = accept_encoding.split(',').filter(|s| !s.trim().is_empty());
    let mut best_encoding = "identity";
    let mut best_quality = 1.0;

    for encoding in encodings {
        let encoding = encoding.trim();
        let mut parts = encoding.split_whitespace();
        let encoding_type = parts.next().unwrap_or("identity");
        let quality = parts.next().and_then(|s| s.parse::<f64>().ok()).unwrap_or(1.0);

        if encoding_type == "br" {
            if quality > best_quality {
                best_quality = quality;
                best_encoding = "br";
            }
        } else if encoding_type == "gzip" {
            if quality > best_quality {
                best_quality = quality;
                best_encoding = "gzip";
            }
        } else if encoding_type == "identity" {
            if quality > best_quality {
                best_quality = quality;
                best_encoding = "identity";
            }
        }
    }

    match best_encoding {
        "br" => {
            if let Ok(br_data) = file.get_encoded("br") {
                (br_data, "br")
            } else {
                if let Ok(gzip_data) = file.get_encoded("gzip") {
                    (gzip_data, "gzip")
                } else {
                    if let Ok(identity_data) = file.get_encoded("identity") {
                        (identity_data, "identity")
                    } else {
                        panic!("No encoding available for the requested content");
                    }
                }
            }
        }
        "gzip" => {
            if let Ok(gzip_data) = file.get_encoded("gzip") {
                (gzip_data, "gzip")
            } else {
                if let Ok(identity_data) = file.get_encoded("identity") {
                    (identity_data, "identity")
                } else {
                    panic!("No encoding available for the requested content");
                }
            }
        }
        "identity" => {
            if let Ok(identity_data) = file.get_encoded("identity") {
                (identity_data, "identity")
            } else {
                panic!("No encoding available for the requested content");
            }
        }
        _ => panic!("Unsupported encoding"),
    }
}

fn fuzz_trimmed<F>(hook: bool, mut closure: F)
where
    F: FnMut(&[u8]) + std::panic::RefUnwindSafe,
{
    afl::fuzz(hook, move |data: &[u8]| {
        let trimmed = data.iter().filter(|&&b| !b.is_ascii_whitespace()).collect::<Vec<_>>();
        closure(&trimmed);
    });
}

fn validate_incoming_offer(offer: &IncomingContractOffer, now_secs: u64) -> Result<(), anyhow::Error> {
    if offer.amount == Amount::zero() {
        return Err(anyhow!("Offer amount must be non-zero"));
    }

    if offer.expiry.is_none() {
        return Err(anyhow!("Offer must have an expiry time"));
    }

    let expiry = offer.expiry.unwrap();
    if expiry < now_secs {
        return Err(anyhow!("Offer expiry has passed"));
    }

    Ok(())
}

use crate::FluvioSocket;
