#[derive(Encoder, Decoder)]
struct EchoRequest {
    msg: String,
}

impl EchoRequest {
    fn new(msg: String) -> Self {
        EchoRequest { msg }
    }
}

impl Request for EchoRequest {
    const API_KEY: u16 = 1000;
    type Response = EchoResponse;
}

#[derive(Encoder, Decoder)]
struct EchoResponse {
    msg: String,
}

fn connect_multiple_servers_and_aggregate(addrs: &[&str], request: &RequestMessage<EchoRequest>) -> Result<Vec<String>, SocketError> {
    let sockets = addrs
        .iter()
        .map(|&addr| {
            FluvioSocket::connect(addr)
                .and_then(|mut socket| socket.send_request(request.clone()))
                .map(|response| response.msg)
        })
        .collect::<Vec<_>>();

    let responses = try_join_all(sockets)?;
    Ok(responses)
}

use ckb_app_config::NetworkConfig;
use multiaddr::Multiaddr;

fn generate_peer_list(network: &NetworkConfig, dns_seeds: &[String]) -> Vec<Multiaddr> {
    let mut peer_list = Vec::new();

    // Add bootnodes
    if let Some(bootnodes) = &network.bootnodes {
        for bootnode in bootnodes {
            if let Ok(addr) = Multiaddr::try_from(bootnode) {
                peer_list.push(addr);
            }
        }
    }

    // Add DNS seeds
    for &seed in dns_seeds {
        if let Ok(addr) = Multiaddr::try_from(seed.as_str()) {
            peer_list.push(addr);
        }
    }

    // Add public addresses
    if let Some(public_addresses) = &network.public_addresses {
        for addr in public_addresses {
            if let Ok(addr) = Multiaddr::try_from(addr) {
                peer_list.push(addr);
            }
        }
    }

    peer_list
}

fn calculate_dependencies(platform: Platform, op: &Operator) -> anyhow::Result<DependencyGraph> {
    let mut graph = DependencyGraph::new();
    let mut package_records = HashMap::new();

    let mut entries = op.list()?;
    while let Some(entry) = entries.next() {
        let entry = entry?;
        if !entry.is_file() {
            continue;
        }

        let path = entry.path();
        if !path.ends_with(".tar.bz2") && !path.ends_with(".conda") {
            continue;
        }

        let package_name = path.file_stem().and_then(|s| s.to_str()).unwrap_or("");
        let package_path = path.to_string_lossy().to_string();

        let reader = op.reader(&path)?;
        let package_record = if path.ends_with(".tar.bz2") {
            package_record_from_tar_bz2_reader(reader)?
        } else {
            package_record_from_conda_reader(reader)?
        };

        if package_record.platform() != platform {
            continue;
        }

        package_records.insert(package_name.to_string(), package_record);
    }

    for (&package_name, &package_record) in &package_records {
        for dep in &package_record.dependencies {
            if let Some(dep_name) = dep.name() {
                graph.add_dependency(package_name, dep_name);
            }
        }
    }

    Ok(graph)
}

fn safe_unpack_batch<T, R>(reader: &mut R, buffer: &mut [T]) -> std::io::Result<usize>
where
    T: Packed,
    R: Unpacker,
{
    let mut count = 0;
    let mut pos = 0;

    while pos < buffer.len() {
        let result = reader.unpack(&mut buffer[pos]);
        match result {
            Ok(()) => {
                count += 1;
                pos += 1;
            }
            Err(e) => {
                // If unpacking fails, return the number of successfully unpacked items
                return Err(e);
            }
        }
    }

    Ok(count)
}

fn active_contributor_percent(&self) -> f64 {
    let total_stake = self.total_stake();
    let active_stake = self.active_contributors_stake();

    if total_stake == 0 {
        return 0.0;
    }

    (active_stake as f64 / total_stake as f64) * 100.0
}

fn total_stake(&self) -> u64 {
    self.validators.values().map(|v| v.stake).sum()
}

fn active_contributors_stake(&self) -> u64 {
    self.validators
        .iter()
        .filter(|(_, validator)| validator.last_voted_fork_slots > 0)
        .map(|(_, validator)| validator.stake)
        .sum()
}

use ndarray::Array3;
use ndrustfft::{ndfft, FftHandler, Complex};

fn apply_3d_fft(data: &Array3<Complex<f64>>) -> Array3<Complex<f64>> {
    let mut result = data.clone();

    // Apply FFT along axis 0
    let mut handler = FftHandler::new();
    let fft_result = ndfft(&result, 0, &mut handler);
    result = fft_result;

    // Apply FFT along axis 1
    let fft_result = ndfft(&result, 1, &mut handler);
    result = fft_result;

    // Apply FFT along axis 2
    let fft_result = ndfft(&result, 2, &mut handler);
    result = fft_result;

    // Apply custom normalization: divide by N for each axis
    let n0 = data.shape()[0] as f64;
    let n1 = data.shape()[1] as f64;
    let n2 = data.shape()[2] as f64;

    for i in 0..n0 {
        for j in 0..n1 {
            for k in 0..n2 {
                let norm = 1.0 / (n0 * n1 * n2);
                result[[i, j, k]] = result[[i, j, k]] * norm;
            }
        }
    }

    result
}

