}

fn get_signature_analysis(&self) -> SignatureAnalysis {
    let transaction = self.transaction();
    let message = transaction.message();
    let signature_details = message.signature_details();

    let required_signers = signature_details.required_signers();
    let signer_count = signature_details.signer_count();
    let missing_signers = required_signers - signer_count;

    SignatureAnalysis {
        required_signers,
        actual_signers: signer_count,
        missing_signers,
        is_valid: missing_signers == 0,
        signature_details: signature_details.clone(),
    }
}

struct SignatureAnalysis {
    required_signers: usize,
    actual_signers: usize,
    missing_signers: usize,
    is_valid: bool,
    signature_details: TransactionSignatureDetails,
}

use kuchiki::parse_html;
use kuchiki::nodes::{Node, NodeExt};

fn summarize_structure(html: &str) -> String {
    let doc = parse_html(html).unwrap();
    let mut result = String::new();
    summarize_node(&doc, &mut result, 0);
    result
}

fn summarize_node(node: &Node, result: &mut String, depth: usize) {
    if node.is_element() {
        let element = node.as_element().unwrap();
        let tag_name = element.tag_name();
        let attributes = element.attributes();
        let mut attr_str = String::new();
        for (name, value) in attributes {
            attr_str.push_str(&format!("{}=\"{}\" ", name, value));
        }
        result.push_str(&format!("{}<{}{}>\n", "  ".repeat(depth), tag_name, attr_str));
        for child in element.children() {
            summarize_node(child, result, depth + 1);
        }
        result.push_str(&format!("{}<{}{} />\n", "  ".repeat(depth), tag_name, attr_str));
    } else if node.is_text() {
        let text = node.as_text().unwrap();
        result.push_str(&format!("{}{}\n", "  ".repeat(depth), text));
    }
}

