fn field_has_non_nullable_arg_without_default<'a>(type_name: &str, field_name: &str, ctx: &Context<'a>) -> bool {
    let type_def = ctx.get_type(type_name).unwrap();
    let field = type_def.get_field(field_name).unwrap();

    if let ast::FieldDef::ObjectFieldDef(field_def) = field {
        if let Some(arg) = field_def.arguments.first() {
            if arg.default_value.is_none() && arg.is_non_null {
                return true;
            }
        }
    }

    false
}

fn conditional_middleware<H>(
    (req, handler): Next<Request, H>
) -> Result<Response>
where
    H: Handler<Request, Output = Result<Response>>,
{
    if req.headers().contains_key("X-Feature-Flag") {
        if let Some(value) = req.headers().get("X-Feature-Flag") {
            if value == "beta" {
                let mut new_req = req;
                new_req.headers_mut().insert("X-Processed-by", "beta-middleware".parse().unwrap());
                return handler.handle(new_req);
            }
        }
    }
    handler.handle(req)
}

fn create_collection_with_composite_index(
    storage: &mut MongoStorage,
    table_name: &str,
    column_defs: Vec<ColumnDef>,
    composite_keys: Vec<String>,
) -> Result<()> {
    // Build the validator based on column definitions
    let validator = Validator::from_column_defs(&column_defs)
        .map_err(|e| e.into())?;

    // Create the collection with the validator
    storage.create_collection(table_name, &validator)
        .map_err(|e| e.into())?;

    // Build the composite index
    let index_model = build_composite_index_model(&composite_keys);

    // Add the composite index to the collection
    storage.create_index(table_name, index_model)
        .map_err(|e| e.into())?;

    Ok(())
}

fn build_composite_index_model(keys: &[String]) -> IndexModel {
    let mut index_options = IndexOptions::default();
    index_options.set_name("composite_index".to_string());
    index_options.set_unique(false);
    index_options.set_background(false);

    let mut index_spec = doc! {};
    for key in keys {
        index_spec.insert(key, 1);
    }

    IndexModel::from_doc(index_spec, Some(index_options))
}

