use chia_protocol::{Bytes32, CoinSpend};
use crate::{announcements_for_spend, announcement_id, Announcements, SimulatorError};

fn validate_announcements_consistency(coin_spends: &[CoinSpend]) -> Result<(), String> {
    let mut all_announcements = Announcements::new();
    let mut announcement_ids = Vec::new();

    for spend in coin_spends {
        let spend_announcements = announcements_for_spend(spend);
        for ann in spend_announcements {
            let ann_id = announcement_id(&ann);
            if all_announcements.contains(&ann_id) {
                return Err(format!("Announcement {} is already present in the set", ann_id));
            }
            all_announcements.insert(ann_id);
            announcement_ids.push(ann_id);
        }
    }

    let mut spent_announcement_ids = Vec::new();

    for spend in coin_spends {
        let spend_announcements = announcements_for_spend(spend);
        for ann in spend_announcements {
            let ann_id = announcement_id(&ann);
            if let Some(ann) = ann {
                if ann.announcement_id() != ann_id {
                    return Err(format!("Announcement ID mismatch: expected {}, got {}", ann_id, ann.announcement_id()));
                }
                spent_announcement_ids.push(ann_id);
            }
        }
    }

    for &id in &announcement_ids {
        if !spent_announcement_ids.contains(&id) {
            return Err(format!("Announcement {} is not spent", id));
        }
    }

    Ok(())
}

use yadf::fs::{find_dupes_partial, dedupe, filter::FileFilter};
use yadf::hasher::Hasher;
use yadf::{Factor, Path};
use yadf::bag::Replicates;

fn duplicates_with_factor<H, P>(dirs: &[P], factor: Factor) -> Replicates<'static, H::Hash, Path>
where
    H: Hasher,
    P: AsRef<std::path::Path>,
{
    // Find all duplicate groups using the partial duplicate detection
    let mut duplicates = find_dupes_partial(dirs, &FileFilter::default());

    // Deduplicate the found groups to get the final set of replicates
    let replicates = dedupe(&mut duplicates);

    // Filter the replicates based on the provided replication factor
    replicates.filter(|group| group.len() >= factor as usize)
}

