fn check_stage_mint_limit(deps: Deps, whitelist_addr: &Addr, stage_id: u32) -> Result<(), ContractError> {
    let stage_response: StageResponse = deps.querier.query_wasm_smart(
        whitelist_addr,
        &TieredWhitelistQueryMsg::Stage { stage_id },
    )?;

    let max_mint_count = match stage_id {
        1 => WHITELIST_FS_MINT_COUNT.load(deps.storage)?,
        2 => WHITELIST_SS_MINT_COUNT.load(deps.storage)?,
        3 => WHITELIST_TS_MINT_COUNT.load(deps.storage)?,
        _ => return Err(ContractError::InvalidStageId {}),
    };

    if stage_response.mint_count >= max_mint_count {
        return Err(ContractError::StageMintLimitExceeded {});
    }

    Ok(())
}

use dora_message::metadata::Metadata;
use dora_message::metadata::ArrowTypeInfo;
use dora_core::config::DataId;
use crate::event_stream::event::{Event, RawData};
use arrow::array::ArrayRef;
use eyre::Result;
use arrow::array::{ArrayRef, Array};
use arrow::array::StringArray;
use arrow::array::UInt64Array;
use arrow::array::ListArray;
use arrow::array::PrimitiveArray;
use arrow::datatypes::{DataType, Field, Schema};
use std::collections::HashMap;
use std::rc::Rc;

fn batch_inputs(events: &[Event], target_id: &DataId) -> Result<ArrayRef> {
    let mut data_map = HashMap::new();
    let mut metadata_map = HashMap::new();

    for event in events {
        if let Event::Input { data_id, data, metadata } = event {
            if data_id != target_id {
                continue;
            }

            if let Some(raw_data) = data.downcast_ref::<RawData>() {
                let data_type = raw_data.data_type();
                let data_name = raw_data.data_name();
                let data_value = raw_data.data_value();

                let metadata = metadata.clone();
                let data_type = data_type.clone();
                let data_name = data_name.clone();

                data_map.entry(data_name)
                    .or_insert_with(Vec::new)
                    .push(data_value);

                metadata_map.entry(data_name)
                    .or_insert_with(Vec::new)
                    .push(metadata);
            }
        }
    }

    if data_map.is_empty() {
        return Ok(Arc::new(arrow::array::ArrayRef::new(arrow::array::NullArray::new(0))));
    }

    let fields: Vec<Field> = data_map.keys().map(|name| {
        let data_type = data_map.get(name).unwrap().first().unwrap().data_type();
        Field::new(name, data_type, false)
    }).collect();

    let schema = Schema::new(fields);

    let arrays: Vec<ArrayRef> = data_map
        .into_iter()
        .map(|(name, values)| {
            let data_type = values.first().unwrap().data_type();
            let array = match data_type {
                DataType::Utf8 => Arc::new(StringArray::from(values.iter().map(|v| v.as_str()).collect::<Vec<_>>())) as ArrayRef,
                DataType::UInt64 => Arc::new(UInt64Array::from(values.iter().map(|v| v.parse().unwrap()).collect::<Vec<_>>())) as ArrayRef,
                DataType::List(inner) => {
                    let inner_type = inner.clone();
                    let list_values: Vec<Vec<String>> = values.iter().map(|v| {
                        v.parse::<Vec<String>>().unwrap()
                    }).collect();
                    let list_array = ListArray::new(
                        inner_type,
                        Arc::new(UInt64Array::from(list_values.iter().map(|v| v.len() as u64).collect::<Vec<_>>())) as ArrayRef,
                        list_values.into_iter().map(|v| Arc::new(StringArray::from(v)) as ArrayRef).collect(),
                    );
                    Arc::new(list_array) as ArrayRef
                },
                _ => {
                    let array = PrimitiveArray::new(data_type, values.iter().map(|v| v.parse().unwrap()).collect::<Vec<_>>());
                    Arc::new(array) as ArrayRef
                }
            };
            (name, array)
        })
        .collect();

    let arrays: Vec<ArrayRef> = arrays.into_iter().map(|(_, array)| array).collect();

    let array = arrow::array::concat(&arrays);
    Ok(array)
}

