fn realloc_secure(ptr: NonNull<[u8]>, new_len: usize) -> Option<NonNull<[u8]>> {
    let old_len = ptr.len();
    if new_len == old_len {
        return Some(ptr);
    }

    // Check if we need to allocate new memory
    let new_ptr = if new_len > old_len {
        // Allocate new buffer with the same size as the old one
        let new_size = new_len;
        let new_ptr = unsafe { malloc_sized(new_size) };
        if new_ptr.is_null() {
            return None;
        }

        // Copy the old data to the new buffer
        unsafe {
            ptr::copy_nonoverlapping(ptr.as_ptr(), new_ptr.as_ptr(), old_len);
        }

        // Zero the new region
        unsafe {
            memzero(new_ptr.as_ptr().add(old_len), new_len - old_len);
        }

        // Set the same protection as the original buffer
        let original_protection = unsafe { mprotect(ptr.as_ptr(), old_len, Prot::Read | Prot::Write) };
        if original_protection.is_err() {
            unsafe { free(new_ptr) };
            return None;
        }

        new_ptr
    } else {
        // Shrink the buffer
        let new_size = new_len;
        let new_ptr = unsafe { malloc_sized(new_size) };
        if new_ptr.is_null() {
            return None;
        }

        // Copy the data to the new buffer
        unsafe {
            ptr::copy_nonoverlapping(ptr.as_ptr(), new_ptr.as_ptr(), new_len);
        }

        // Free the old buffer
        unsafe {
            free(ptr);
        }

        new_ptr
    };

    // Return the new buffer with the updated length
    Some(NonNull::new(new_ptr).unwrap().slice(new_len))
}

fn flash_leds(rp: &Redpitaya, delay: Duration) {
