use crate::{GroupInfo, split_and_insert};
use std::cmp::Reverse;

fn generate_markdown_summary(groups: &[GroupInfo], top_n: usize) -> String {
    if groups.is_empty() || top_n == 0 {
        return String::from("# No Identical File Groups Found\n\nNo file groups were identified as identical.");
    }

    let mut sorted_groups = groups.to_vec();
    sorted_groups.sort_by_key(|g| Reverse(g.total_size));
    let top_groups = &sorted_groups[..top_n.min(sorted_groups.len())];

    let mut markdown = String::with_capacity(1024);
    markdown.push_str("# Largest Identical File Groups\n\n");
    markdown.push_str("| Size | File Count | Total Size |\n");
    markdown.push_str("|------|------------|------------|\n");

    for group in top_groups {
        let size = split_and_insert(group.size);
        let total_size = split_and_insert(group.total_size);
        markdown.push_str(&format!("| {} | {} | {} |\n", size, group.file_count, total_size));
    }

    markdown
}

