use crate::instance::InstanceVersion;
use std::ffi::OsStr;
use std::fs;
use std::io;

fn clean_stale_data(path_prefix: &OsStr, keep_version: InstanceVersion) -> Result<(), io::Error> {
    // Iterate through all files in the directory
    if let Ok(entries) = fs::read_dir(path_prefix) {
        for entry in entries {
            let entry = entry?;
            let path = entry.path();
            let file_name = path.file_name().and_then(|n| n.to_str()).ok_or(io::Error::new(io::ErrorKind::InvalidData, "Invalid filename"))?;

            // Check if the file is a data file (e.g., starts with "data_")
            if file_name.starts_with("data_") {
                // Extract version from filename
                if let Some(version_str) = file_name.strip_prefix("data_") {
                    if let Ok(version) = version_str.parse::<InstanceVersion>() {
                        // If the version is not the one to keep, delete it
                        if version != keep_version {
                            fs::remove_file(path)?;
                        }
                    }
                }
            }
        }
    }

    Ok(())
}

