        table: table.to_string(),
        column: column.to_string(),
        ref_table: ref_table.to_string(),
        ref_column: ref_column.to_string(),
        on_delete: OnDelete::Cascade,
        on_update: OnUpdate::Cascade,
    };

    format!(
        "ALTER TABLE {}.{} ADD CONSTRAINT fk_{} FOREIGN KEY ({}) REFERENCES {}.{} ({}) ON DELETE CASCADE ON UPDATE CASCADE",
        fk.namespace, fk.table, fk.column, fk.column, fk.ref_table, fk.ref_table, fk.ref_column
    )
}

fn unreachable_functions(&self) -> HashSet<FunctionId> {
    let mut visited = HashSet::new();
    let mut queue = VecDeque::new();

    // Start with main graph nodes
    for node in &self.main_graph {
        if let Node::Function(fid) = node {
            queue.push_back(*fid);
            visited.insert(*fid);
        }
    }

    // Start with shared symbols (if they are functions)
    for &node in &self.shared_symbols {
        if let Node::Function(fid) = node {
            if !visited.contains(&fid) {
                queue.push_back(fid);
                visited.insert(fid);
            }
        }
    }

    // Traverse call graph to mark reachable functions
    while let Some(current) = queue.pop_front() {
        if let Some(called) = self.call_graph.get(&current) {
            for &called_node in called {
                if let Node::Function(fid) = called_node {
                    if !visited.contains(&fid) {
                        visited.insert(fid);
                        queue.push_back(fid);
                    }
                }
            }
        }
    }

    // Collect all functions not in visited
    let mut result = HashSet::new();
    for function in self.source_module.functions.values() {
        if !visited.contains(&function.id) {
            result.insert(function.id);
        }
    }

    result
}

fn prune_unreachable(guard: &DropGuard, addresses: Vec<IpAddr>) {
