fn timed_handshake<B>(builder: B, stream: tokio::net::TcpStream) -> Result<(TlsStream<tokio::net::TcpStream, B::Output>, std::time::Duration), Error>
where
    B: Builder,
    B::Output: Unpin,
{
    let start = std::time::Instant::now();
    let acceptor = builder.build()?;
    let tls_stream = TlsAcceptor::new(acceptor).accept(stream)?;
    let duration = start.elapsed();
    Ok((tls_stream, duration))
}

fn setup_custom_asset_coins(
    owner: Address,
    assets: &[(&AssetId, u64)],
    num_coins: u64,
) -> Vec<Coin> {
    let mut rng = rand::thread_rng();
    let mut coins = Vec::new();

    for (asset_id, total_amount) in assets {
        let mut remaining = *total_amount;
        let mut coin_count = 0;

        while remaining > 0 && coin_count < num_coins {
            let amount = rng.gen_range(1..remaining);
            coins.push(Coin::new(*asset_id, owner, amount));
            remaining -= amount;
            coin_count += 1;
        }
    }

    coins
}

