use hmac_sha512::HMAC;

fn hkdf_sha512(salt: &[u8], ikm: &[u8], info: &[u8], okm_len: usize) -> Vec<u8> {
    // Step 1: Extract
    let prk = extract(salt, ikm);

    // Step 2: Expand
    expand(&prk, info, okm_len)
}

fn extract(salt: &[u8], ikm: &[u8]) -> Vec<u8> {
    let hmac = HMAC::new(salt, ikm);
    hmac.output().to_vec()
}

fn expand(prk: &[u8], info: &[u8], okm_len: usize) -> Vec<u8> {
    let mut okm = Vec::with_capacity(okm_len);
    let mut key_material = Vec::new();
    let mut counter = 0;

    while okm.len() < okm_len {
        let mut hmac = HMAC::new(prk, &key_material);
        hmac.update(info);
        hmac.update(&[counter]);
        key_material = hmac.output().to_vec();
        okm.extend(key_material);
        counter += 1;
    }

    okm[..okm_len].to_vec()
}

fn send_transaction_with_rate_limit(&self, transaction: &Transaction, rate_limit_ms: u64) -> TransportResult<()> {
    let wire = bincode::serialize(transaction).expect("serialization should succeed");
    let leaders = self.leader_tpu_service.unique_leader_tpu_sockets(self.fanout_slots);
    for leader in &leaders {
        let conn = self.connection_cache.get_nonblocking_connection(leader);
        conn.send_data(&wire).await?;
        sleep(Duration::from_millis(rate_limit_ms)).await;
    }
    Ok(())
}

