fn send_yuv_frame_chunked(
    tx: &Sender,
    frame: &YuvFrame<'_>,
    max_chunk_size: usize,
) -> Result<()> {
    // Send metadata first
    let metadata = serde_json::to_vec(&frame.info).map_err(|e| Error::Custom(e.to_string()))?;
    tx.send_with_timeout(&metadata, Duration::from_secs(5))?; // 5 seconds timeout

    // Send Y plane
    send_plane_chunked(tx, frame.y_pixels, max_chunk_size, "y")?;

    // Send U plane
    send_plane_chunked(tx, frame.u_pixels, max_chunk_size, "u")?;

    // Send V plane
    send_plane_chunked(tx, frame.v_pixels, max_chunk_size, "v")?;

    Ok(())
}

fn send_plane_chunked(
    tx: &Sender,
    data: &[u8],
    max_chunk_size: usize,
    plane_name: &str,
) -> Result<()> {
    let mut offset = 0;
    while offset < data.len() {
        let chunk_size = min(max_chunk_size, data.len() - offset);
        let chunk = &data[offset..offset + chunk_size];
        tx.send_with_timeout(chunk, Duration::from_secs(5))?;
        offset += chunk_size;
    }
    Ok(())
}

