use rfc2047_decoder::{Decoder, Error, RecoverStrategy};

fn decode_subject(raw_headers: &[u8]) -> Result<String, Error> {
    let mut decoder = Decoder::new();
    let mut result = String::new();
    let mut in_word = false;
    let mut current_word = String::new();

    for &byte in raw_headers {
        if byte == b'=' {
            in_word = true;
            current_word.push(byte);
            continue;
        }

        if byte == b'?' && in_word {
            // Start of a potential encoded word
            let mut encoded_word = String::new();
            let mut in_encoded = false;

            for &b in raw_headers {
                if b == b'?' {
                    if in_encoded {
                        // End of encoded word
                        in_encoded = false;
                        let decoded = decoder.decode(&encoded_word)?;
                        result.push_str(&decoded);
                        current_word.clear();
                        in_word = false;
                        break;
                    } else {
                        // Start of encoded word
                        in_encoded = true;
                    }
                } else if in_encoded {
                    encoded_word.push(b);
                } else if in_word {
                    current_word.push(b);
                } else {
                    result.push(b);
                }
            }
            continue;
        }

        if in_word {
            current_word.push(byte);
        } else {
            result.push(byte);
        }
    }

    if in_word {
        // Handle any remaining characters in the word
        let decoded = decoder.decode(&current_word)?;
        result.push_str(&decoded);
    }

    Ok(result)
}

fn get_env_var(name: &str) -> Option<Vec<u8>> {
    // Query the length of the environment variable
    let len = unsafe { sys_getenv(name.as_ptr() as *const _, ptr::null_mut()) };
    if len == 0 {
        return None;
    }

    // Allocate a buffer of the required size
    let mut buffer = Vec::with_capacity(len as usize);

    // Fetch the environment variable value
    unsafe {
        let ptr = buffer.as_mut_ptr() as *mut u8;
        let result = sys_getenv(name.as_ptr() as *const _, ptr);
        if result == 0 {
            buffer.set_len(len as usize);
            Some(buffer)
        } else {
            None
        }
    }
}

