}

fn top_n_enum(table: &Table<usize>, rows: &[usize], n: u32) -> NLargestCount {
    let mut counts = HashMap::new();

    for &row in rows {
        if let ColumnType::Enum(ref enum_data) = table.column_type(row) {
            if let Some(category) = enum_data.get(row) {
                *counts.entry(category).or_insert(0) += 1;
            }
        }
    }

    let mut items: Vec<_> = counts.into_iter().map(|(k, v)| (v, k)).collect();
    items.sort_by(|a, b| b.cmp(a));

    let mut result = Vec::with_capacity(n as usize);
    for i in 0..items.len().min(n as usize) {
        result.push(items[i].1);
    }

    NLargestCount { top: result }
}

