struct RateLimiter {
    max_rate: Duration,
    last_publish: Option<Instant>,
}

impl RateLimiter {
    fn new(max_rate: Duration) -> Self {
        RateLimiter {
            max_rate,
            last_publish: None,
        }
    }

    fn can_publish(&self) -> bool {
        if let Some(last) = self.last_publish {
            let elapsed = Instant::now() - last;
            elapsed >= self.max_rate
        } else {
            true
        }
    }

    fn record_publish(&mut self) {
        self.last_publish = Some(Instant::now());
    }
}

fn rate_limited_publish(
    limiter: &mut RateLimiter,
    behaviour: &mut Behaviour,
    topic: &Topic,
    data: Bytes,
) {
    if limiter.can_publish() {
        behaviour.publish(topic, data);
        limiter.record_publish();
    }
}

fn select_cheapest_gateway<API>(api: &API, invoice: &Bolt11Invoice) -> anyhow::Result<(SafeUrl, RoutingInfo)>
where
    API: LightningFederationApi + Send + Sync,
{
    let gateways = api.list_vetted_gateways()?;
    let mut cheapest_gateway = None;
    let mut min_fee = std::u64::MAX;

    for gateway in gateways {
        let routing_info = api.get_routing_info(&gateway)?;
        let fee = calculate_fee(&invoice, &routing_info)?;

        if fee < min_fee {
            min_fee = fee;
            cheapest_gateway = Some((gateway.url, routing_info));
        }
    }

    cheapest_gateway.ok_or_else(|| anyhow!("No vetted gateways found"))
}

fn calculate_fee(invoice: &Bolt11Invoice, routing_info: &RoutingInfo) -> anyhow::Result<u64> {
    let amount = invoice.amount_milli_satoshis() as u64;
    let fee_rate = routing_info.fee_rate;

    // Calculate fee as a percentage of the invoice amount
    let fee = (amount * fee_rate) / 1000;

    Ok(fee)
}

