fn monitor_peer_connections(
    dashboard_api: &DynDashboardApi,
    interval: Duration,
    callback: impl Fn(BTreeMap<PeerId, Option<Duration>>) + Send + Sync + 'static,
) {
    let dashboard_api = Arc::new(dashboard_api.clone());
    let callback = Arc::new(callback);

    thread::spawn(move || {
        let mut last_rtt = BTreeMap::new();
        loop {
            let current_rtt = {
                let mut rtt_map = BTreeMap::new();
                if let Ok(peers) = dashboard_api.get_connected_peers() {
                    for peer in peers {
                        if let Ok(rtt) = dashboard_api.get_peer_rtt(peer) {
                            rtt_map.insert(peer, Some(rtt));
                        } else {
                            rtt_map.insert(peer, None);
                        }
                    }
                }
                rtt_map
            };

            if current_rtt != last_rtt {
                callback(current_rtt.clone());
                last_rtt = current_rtt;
            }

            thread::sleep(interval);
        }
    });
}

