struct TokenCache {
    private_key: String,
    full_identifier: String,
    token: String,
    expiration: OffsetDateTime,
}

impl TokenCache {
    fn new(private_key_pem: impl Into<String>, full_identifier: impl Into<String>) -> Self {
        let private_key = private_key_pem.into();
        let full_identifier = full_identifier.into();
        let token = generate_jwt_token(&private_key, &full_identifier).expect("Failed to generate JWT token");
        let expiration = OffsetDateTime::now_utc() + Duration::seconds(3600); // Token valid for 1 hour
        TokenCache {
            private_key,
            full_identifier,
            token,
            expiration,
        }
    }

    fn get_token(&self) -> String {
        if self.is_token_expired() {
            self.refresh_token();
        }
        self.token.clone()
    }

    fn is_token_expired(&self) -> bool {
        OffsetDateTime::now_utc() >= self.expiration
    }

    fn refresh_token(&mut self) {
        let new_token = generate_jwt_token(&self.private_key, &self.full_identifier)
            .expect("Failed to refresh JWT token");
        self.token = new_token;
        self.expiration = OffsetDateTime::now_utc() + Duration::seconds(3600);
    }
}

