fn combine_filters_and(filters: Vec<Filter>) -> Option<Filter> {
    if filters.is_empty() {
        return None;
    }

    let mut result = filters.into_iter().next().unwrap();

    for filter in filters.into_iter().skip(1) {
        let new_filter = Filter {
            field: filter.field,
            logic_op: Some(LogicOp::And),
            filter_type: FilterType::Nested(Box::new(filter)),
        };
        result = new_filter;
    }

    Some(result)
}

