use spl_token_metadata_interface::state::TokenMetadata;
use spl_type_length_value::state::TlvStateBorrowed;

fn validate_and_parse_metadata(account_data: &[u8]) -> Result<TokenMetadata, String> {
    let mut tlv = TlvStateBorrowed::new(account_data);
    let mut metadata = None;

    while let Some(entry) = tlv.next() {
        if entry.tag == 0x42 { // 'B' for Metadata
            let mut metadata_bytes = Vec::new();
            while let Some(byte) = entry.value.next() {
                metadata_bytes.push(*byte);
            }
            if let Ok(parsed) = TokenMetadata::try_from_slice(&metadata_bytes) {
                metadata = Some(parsed);
                break;
            } else {
                return Err("Failed to parse TokenMetadata".to_string());
            }
        }
    }

    match metadata {
        Some(meta) => {
            if meta.update_authority.is_none() {
                return Err("Update authority is missing in metadata".to_string());
            }
            Ok(meta)
        }
        None => Err("Metadata entry not found".to_string()),
    }
}

