use crate::error::{ErrorLevel, ValidationErrors, ValidationError};

fn generate_markdown_report(errors: &ValidationErrors) -> String {
    let mut report = String::new();
    let mut error_counts = std::collections::HashMap::new();

    // Count error types
    for error in &errors.errors {
        let level = error.level;
        let error_type = error.error_type.clone();
        *error_counts.entry(error_type).or_insert(0) += 1;
    }

    // Header
    report.push_str("# Validation Error Summary Report\n\n");

    // Error count table
    report.push_str("## Error Type Counts\n\n");
    report.push_str("| Error Type | Count |\n");
    report.push_str("|------------|------|\n");

    for (error_type, &count) in &error_counts {
        report.push_str(&format!("| {} | {} |\n", error_type, count));
    }

    // Unapproved external types table
    report.push_str("\n## Unapproved External Types\n\n");
    report.push_str("| External Type | Error Level |\n");
    report.push_str("|---------------|-------------|\n");

    for error in &errors.errors {
        if let ValidationError::UnapprovedExternalType { external_type, level } = error {
            report.push_str(&format!("| {} | {} |\n", external_type, level));
        }
    }

    report
}

