fn monitor_bitcoin_sync(
    rpc_monitor: &ServerBitcoinRpcMonitor,
    threshold: f64,
    interval_duration: Duration,
) {
    let status_receiver = rpc_monitor.status_receiver.clone();
    let threshold = threshold;

    let mut interval = interval(interval_duration);

    tokio::spawn(async move {
        while let Ok(status) = status_receiver.changed().await {
            if let Some(sync_percentage) = status {
                if sync_percentage < threshold {
                    warn!("Bitcoin sync percentage dropped below threshold: {}", sync_percentage);
                }
            }
        }
    });
}

fn FadeInComponent() -> View {
