        }
    }
}

fn compact_if_large_range<K: leveldb::database::key::Key + Ord>(db: &leveldb::database::Database<K>, start: &K, end: &K, min_keys: usize) -> Result<(), leveldb::database::error::Error> {
    let read_options = leveldb::options::ReadOptions::new();
    read_options.set_iterate(true);
    read_options.set_prefix(start);
    read_options.set_suffix(end);

    let mut count = 0;
    if let Ok(mut iter) = db.iterator_with_options(&read_options) {
        while let Some(key) = iter.next() {
            if key.key() >= start && key.key() <= end {
                count += 1;
            } else {
                break;
            }
        }
    }

    if count > min_keys {
        let compaction_options = leveldb::compaction::CompactionOptions::new();
        compaction_options.set_start(start);
        compaction_options.set_end(end);
        let compaction = leveldb::compaction::Compaction::new(compaction_options);
        compaction.run(db)?;
    }

    Ok(())
}

