fn filter_and_aggregate_files(
    ctx: &dyn Session,
    store: &dyn ObjectStore,
    table_path: &ListingTableUrl,
    filters: &[Expr],
    file_extension: &str,
    partition_cols: &[(String, DataType)],
    min_size_bytes: u64,
) -> Result<Vec<PartitionedFile>> {
    // Get the pruned partition list based on the filters
    let pruned_partitions = pruned_partition_list(
        ctx,
        store,
        table_path,
        filters,
        file_extension,
        partition_cols,
    )?;

    // Filter files by size and collect them
    let mut result = Vec::new();
    for partition in pruned_partitions {
        let files = partition.files();
        for file in files {
            if file.size_bytes > min_size_bytes {
                result.push(file.clone());
            }
        }
    }

    Ok(result)
}

