fn apply_common_album_info(dir: &Path, album_title: &str, cover: Picture) -> Result<()> {
    if !dir.exists() {
        return Err(Error::Io(std::io::Error::new(std::io::ErrorKind::NotFound, "Directory not found")));
    }

    if !dir.is_dir() {
        return Err(Error::Io(std::io::Error::new(std::io::ErrorKind::InvalidArgument, "Path is not a directory")));
    }

    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        if path.is_file() {
            if let Some(extension) = path.extension() {
                if ["mp3", "flac", "m4a"].contains(&extension.to_str().unwrap_or("")) {
                    let mut tag = Tag::new(&path)?;
                    tag.set_album(album_title);
                    tag.set_picture(Picture::new(
                        MimeType::JPEG,
                        cover.data.clone(),
                        cover.description.clone(),
                    ));
                    tag.write()?;
                }
            }
        }
    }

    Ok(())
}

