use fuel_indexer_database_types::{Table, Column, Persistence, TableType};
use crate::queries::{type_id_latest, type_id_list_by_name, list_column_by_id};
use sqlx::Result;

fn create_table_sql_for_type(
    conn: &mut IndexerConnection,
    namespace: &str,
    identifier: &str,
    type_name: &str,
) -> sqlx::Result<String> {
    let type_id = type_id_latest(conn, namespace, identifier, type_name)?;
    let table_id = type_id_list_by_name(conn, namespace, identifier, type_name)?;

    let table = Table::get_by_id(conn, table_id)?;
    let columns = list_column_by_id(conn, table_id)?;

    let columns_sql = columns
        .iter()
        .map(|col| {
            let data_type = match col.data_type {
                Persistence::String => "TEXT",
                Persistence::Integer => "INTEGER",
                Persistence::Boolean => "BOOLEAN",
                Persistence::Float => "FLOAT",
                Persistence::Timestamp => "TIMESTAMP",
                _ => "TEXT",
            };

            let nullable = if col.nullable {
                "NULL"
            } else {
                "NOT NULL"
            };

            let default = if let Some(default) = &col.default {
                format!("DEFAULT {}", default)
            } else {
                String::new()
            };

            format!("{} {} {}{}", col.name, data_type, nullable, default)
        })
        .collect::<Vec<String>>()
        .join(",\n");

    let primary_key = if let Some(pk) = table.primary_key {
        format!("PRIMARY KEY ({})", pk)
    } else {
        String::new()
    };

    let table_type = match table.table_type {
        TableType::Regular => String::new(),
        TableType::View => "VIEW",
        TableType::Index => "INDEX",
    };

    let sql = format!(
        "CREATE {} TABLE {} ({}){};",
        table_type, table.name, columns_sql, primary_key
    );

    Ok(sql)
}

fn filter_segments_by_offset(&mut self, offset: u64) {
