            start <= offset && end >= offset
        })
        .cloned()
        .collect();
}

use dubins_paths::{DubinsPath, FloatType, PathType};

fn path_duration(
    path: &DubinsPath,
    linear_speed: FloatType,
    angular_speed: FloatType,
) -> FloatType {
    let mut duration = FloatType::zero();

    let mut current_position = path.start();
    let mut current_angle = path.start().angle();

    for segment in &path.segments {
        match segment {
            PathType::Straight { distance } => {
                let time = *distance / linear_speed;
                duration += time;
                current_position = current_position.translate_forward(*distance, current_angle);
            }
            PathType::LeftArc { radius, angle } | PathType::RightArc { radius, angle } => {
                let angular_velocity = angular_speed.abs();
                let time = *angle / angular_velocity;
                duration += time;
                let turn_angle = *angle;
                current_angle += turn_angle;
                // Update position based on arc movement
                let arc_length = radius * turn_angle;
                current_position = current_position.translate_forward(arc_length, current_angle);
            }
        }
    }

    duration
}

