use std::os::raw::{c_int, c_char, c_void};
use sixel_sys::{sixel_dither_create, sixel_dither_initialize, sixel_dither_set_diffusion_type, sixel_output_new, sixel_output_destroy, sixel_encode, PixelFormat, MethodForLargest, MethodForRepColor, QualityMode, DiffusionMethod, status};

fn encode_rgb_to_sixel(rgb: &[u8], width: i32, height: i32) -> Result<Vec<u8>, i32> {
    let mut dither = sixel_dither_create();
    let mut output = sixel_output_new();

    if dither.is_null() || output.is_null() {
        return Err(-1);
    }

    sixel_dither_set_diffusion_type(dither, DiffusionMethod::Atkinson);
    sixel_dither_initialize(dither, width, height, PixelFormat::Rgb24, MethodForLargest::Max, MethodForRepColor::None, QualityMode::Fast);

    let mut buffer = vec![0u8; 1024 * 1024]; // Assuming a reasonable buffer size
    let mut buffer_len = buffer.len() as c_int;
    let mut status = status::SUCCESS;

    unsafe {
        status = sixel_encode(dither, output, rgb.as_ptr(), width, height, PixelFormat::Rgb24, buffer.as_mut_ptr(), &mut buffer_len);
    }

    if status != status::SUCCESS {
        sixel_output_destroy(output);
        sixel_dither_destroy(dither);
        return Err(-2);
    }

    let result = buffer[..buffer_len as usize].to_vec();
    sixel_output_destroy(output);
    sixel_dither_destroy(dither);
    Ok(result)
}

fn filter_peers_by_subnet(
    peers: &[ResponsePeer<Ipv4Addr>],
    subnet: Ipv4Addr,
    prefix_len: u8,
) -> Vec<ResponsePeer<Ipv4Addr>> {
    peers
        .iter()
        .filter(|peer| {
            let peer_ip = peer.ip();
            let subnet_net = subnet;
            let subnet_prefix = prefix_len;
            let peer_prefix = peer_ip.prefix_len();
            let subnet_mask = 32 - subnet_prefix;
            let peer_mask = 32 - peer_prefix;

            if subnet_mask != peer_mask {
                return false;
            }

            let subnet_network = subnet_net & (!((1 << subnet_mask) - 1));
            let peer_network = peer_ip & (!((1 << peer_mask) - 1));

            subnet_network == peer_network
        })
        .cloned()
        .collect()
}

use anyhow::Result;
use crate::backup::{DatabaseBackupSource, MutationRangeEntry, MutationRangeKey};

fn fetch_logs_in_time_range(
    source: &impl DatabaseBackupSource,
    start_ms: u64,
    end_ms: u64,
) -> Result<Vec<MutationRangeEntry>> {
    let mut result = Vec::new();
    let mut key = MutationRangeKey::min();

    loop {
        if key.last_modified_ms > end_ms {
            break;
        }

        if key.last_modified_ms >= start_ms {
            result.push(key.entry.clone());
        }

        key = source.next_key(key)?;
        if key == MutationRangeKey::max() {
            break;
        }
    }

    Ok(result)
}

