use switchboard_solana::prelude::*;
use switchboard_solana::AggregatorAccountData;
use switchboard_solana::SwitchboardDecimal;
use switchboard_solana::SwitchboardError;
use anchor_lang::prelude::*;

fn is_significant_change(agg: &AggregatorAccountData, percent_threshold: f64) -> anchor_lang::Result<bool> {
    // Check if the aggregator has a valid latest result
    if agg.latest_result.is_none() {
        return Ok(false);
    }

    // Get the latest result
    let latest_result = agg.latest_result.unwrap();

    // Check if the aggregator has a valid previous confirmed round
    if agg.previous_confirmed_round.is_none() {
        return Ok(false);
    }

    // Get the previous confirmed round value
    let previous_value = agg.previous_confirmed_round.unwrap();

    // Calculate the absolute change
    let absolute_change = latest_result.value - previous_value.value;

    // Calculate the percentage change
    let percentage_change = if previous_value.value.abs() > 0.0 {
        (absolute_change / previous_value.value.abs()) * 100.0
    } else {
        0.0
    };

    // Check if the percentage change exceeds the threshold
    Ok(percentage_change.abs() > percent_threshold)
}

