fn AnimatedElement() -> impl IntoView {
    let (is_animated, set_is_animated) = create_signal(false);
    let element_ref = create_node_ref();

    let start_animation = move || {
        set_is_animated(true);
        let element = element_ref.get();
        if let Some(element) = element {
            let style = element.style();
            let mut opacity = 1.0;
            let mut scale = 1.0;

            let animate = move || {
                opacity -= 0.05;
                scale -= 0.05;
                style.set("opacity", opacity.to_string());
                style.set("transform", format!("scale({})", scale));

                if opacity > 0.0 {
                    request_animation_frame(animate);
                } else {
                    set_is_animated(false);
                }
            };

            request_animation_frame(animate);
        }
    };

    view! {
        <button on:click=start_animation>
            "Start Animation"
        </button>
        <div
            class="animate-element"
            style=move || {
                if is_animated() {
                    "opacity: 1.0; transform: scale(1.0); transition: all 0.5s ease;"
                } else {
                    "opacity: 0.0; transform: scale(0.0); transition: all 0.5s ease;"
                }
            }
            node_ref=element_ref
        />
    }
}

