use crate::Decimal256;

fn decimal_to_percentage(value: Decimal256) -> String {
    let scaled = value * Decimal256::from(100);
    let integer_part = scaled.to_u128().unwrap_or(0) as u32;
    let fractional_part = (scaled - Decimal256::from(integer_part as u128)) * Decimal256::from(100);
    let fractional_u16 = fractional_part.to_u128().unwrap_or(0) as u16;
    let fractional_str = if fractional_u16 < 10 {
        format!("0{}", fractional_u16)
    } else {
        fractional_u16.to_string()
    };
    format!("{}{}.{}", integer_part, fractional_str, "%")
}

use std::sync::Arc;
use ckb_types::packed::Byte32;
use ckb_verification::TxVerificationCache;
use ckb_store::ChainStore;
use ckb_error::Error;
use ckb_types::core::BlockNumber;
use tokio::sync::RwLock;

fn prune_tx_cache<CS>(cache: &Arc<RwLock<TxVerificationCache>>, min_block_number: BlockNumber)
where
    CS: ChainStore + Sync + Send + 'static,
{
    if min_block_number == 0 {
        return;
    }

    let cache_guard = cache.read().unwrap();
    let entries: Vec<(Byte32, BlockNumber)> = cache_guard
        .iter()
        .filter(|(_, block_number)| *block_number < min_block_number)
        .cloned()
        .collect();
    drop(cache_guard);

    let mut cache_guard = cache.write().unwrap();
    for (tx_hash, block_number) in entries {
        cache_guard.remove(&tx_hash);
    }
}

