    let workspace = document.get("workspace").and_then(|w| w.as_table());
    if let Some(workspace_table) = workspace {
        let members = workspace_table.get("members").and_then(|m| m.as_array());
        if let Some(members_array) = members {
            let mut crate_names = Vec::new();
            for item in members_array {
                if let Some(name) = item.as_str() {
                    crate_names.push(name.to_string());
                }
            }
            return Ok(crate_names);
        }
    }

    Ok(vec![])
}

fn convert_image_to_base64_url(image: &Image) -> EcoString {
    let format = match image.kind {
        ImageKind::Raster(RasterFormat::Png) => "png",
        ImageKind::Raster(RasterFormat::Jpeg) => "jpeg",
        ImageKind::Raster(RasterFormat::Gif) => "gif",
        ImageKind::Raster(RasterFormat::Webp) => "webp",
        ImageKind::Svg => "svg",
        _ => return EcoString::new(),
    };

    let data = match image.data {
        Some(data) => data,
        None => return EcoString::new(),
    };

    let base64 = base64::prelude::BASE64_STANDARD.encode(&data);
    eco_format!("data:image/{};base64,{}", format, base64)
}

use tokio_schedule::{every, Job};
use chrono::Utc;
use std::future::Future;
use std::sync::Arc;

fn schedule_dynamic_interval<F, Fut>(initial_interval_secs: u64, task: F) -> impl Future<Output = ()>
where
    F: Fn() -> Fut + Send + Sync + 'static,
    Fut: Future<Output = u64> + Send + 'static,
{
    let interval = initial_interval_secs;
    let job = Job::new(every(interval).seconds());

    let mut next_interval = interval;

    let task = Arc::new(task);
    let task_clone = Arc::clone(&task);

    async move {
        let mut job = job;
        let mut next_run = Utc::now();

        loop {
            let result = task_clone().await;
            next_interval = result;

            let duration = chrono::Duration::seconds(next_interval as i64);
            next_run += duration;

            job = job.reschedule_at(next_run);
            tokio::spawn(job);
            tokio::sleep_until(next_run).await;
        }
    }
}

use crate::{connection::Connection, endpoint::Endpoint, Error};
use libp2p_identity::Keypair;
use libp2p_core::PeerId;
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::thread;

fn open_multiple_connections(
    endpoints: Vec<Endpoint>,
    keypair: &Keypair,
) -> Result<Vec<(PeerId, Connection)>, Error> {
    let mut connections = Vec::new();
    let mut handles = Vec::new();

    for endpoint in endpoints {
        let keypair_clone = Arc::new(keypair.clone());
        let endpoint_clone = endpoint.clone();
        let handle = thread::spawn(move || {
            let connection = Connection::new(endpoint_clone, keypair_clone)
                .map_err(|e| e.into())?;
            Ok((connection.peer_id, connection))
        });

        handles.push(handle);
    }

    for handle in handles {
        let result = handle.join().expect("Thread failed to join");
        connections.push(result?)
    }

    Ok(connections)
}

