use deno_core::{JsRuntime, error::AnyError, v8};
use deno_core::v8::Function;

fn create_my_interface_checker(runtime: &mut JsRuntime) -> Result<v8::Global<v8::Function>, AnyError> {
    let isolate = runtime.isolate();
    let scope = &mut v8::HandleScope::new(isolate);
    let context = v8::Context::new(scope);
    let scope = &mut v8::Scope::new(scope, context);

    // Create a function that checks if a value is an instance of MyInterface
    let check_function = v8::Function::new(scope, "isMyInterface", |args: &mut v8::FunctionCallbackArguments, _: v8::Maybe<v8::Handle<v8::Value>>| {
        let value = args[0].to_object(scope).unwrap();
        let interface = runtime.get_interface("MyInterface");
        if let Some(interface) = interface {
            let is_instance = interface.is_instance(value);
            args.get isolate().return_value(v8::Boolean::new(scope, is_instance));
        } else {
            args.get isolate().return_value(v8::Boolean::new(scope, false));
        }
    });

    let global = v8::Global::new(scope, check_function);
    Ok(global)
}

use ini_roundtrip::{Parser, Item};

fn config_to_ini(config: &Config) -> String {
    let mut parser = Parser::new();
    let mut ini_string = String::new();

    // Add sections and their properties in order
    for section in &config.sections {
        parser.begin_section(section.name.as_str());

        for (key, value) in &section.properties {
            parser.add_item(Item::new(key.as_str(), value.as_str()));
        }

        parser.end_section();
    }

    ini_string.push_str(parser.to_string());
    ini_string
}

