fn format_test_result(result: &TestResult) -> String {
    let mut output = String::new();
    format_test_result_helper(result, &mut output);
    output
}

fn format_test_result_helper(result: &TestResult, output: &mut String) {
    match result.status {
        Ok(()) => {
            let green = colors::Color::Green;
            output.push_str(&format!("{}PASS{} ", green, colors::Reset));
        }
        Err(_) => {
            let red = colors::Color::Red;
            output.push_str(&format!("{}FAIL{} ", red, colors::Reset));
        }
    }

    output.push_str(&result.name);

    if !result.sub_tests.is_empty() {
        output.push('\n');
        for sub_result in &result.sub_tests {
            format_test_result_helper(sub_result, output);
        }
    }
}

