fn notify_batch_account_updates(&self, updates: &[ReplicaAccountInfoV3<'_>], slot: Slot, is_startup: bool) {
    let plugin_manager = self.plugin_manager.read().unwrap();
    let plugins = plugin_manager.get_plugins();
    let mut total_updates = 0;

    for plugin in plugins.values() {
        if let Some(plugin) = plugin.as_any().downcast_ref::<dyn GeyserPluginManager>() {
            if let Some(batch_update) = plugin.batch_update() {
                let batched_updates = updates.iter().filter(|info| {
                    let account_key = info.account_key();
                    batch_update.is_account_interesting(account_key)
                }).cloned().collect::<Vec<_>>();

                if !batched_updates.is_empty() {
                    let measure = Measure::start("notify_batch_account_updates");
                    if let Err(e) = plugin.notify_account_updates(&batched_updates, slot, is_startup) {
                        error!("Failed to notify plugin: {}", e);
                    }
                    measure.stop();
                    inc_new_counter_debug!("notify_batch_account_updates_time", "time", measure.as_nanos() as u64);
                    total_updates += batched_updates.len();
                }
            }
        }
    }

    trace!("Notified {} account updates in batch", total_updates);
}

fn manage_multiple_rendezvous_nodes(
