use portable_pty::{CommandBuilder, PtySize, native_pty_system};
use std::io::Write;

fn main() {
    // Set up the pty system
    native_pty_system().unwrap();

    // Define the environment variables to set or override
    let mut env_vars = std::env::vars().map(|(k, v)| (k, v)).collect::<Vec<_>>();
    env_vars.push(("CUSTOM_VAR".to_string(), "custom_value".to_string()));

    // Build the command to execute
    let mut cmd = CommandBuilder::new("sh")
        .args(["-c", "echo $CUSTOM_VAR"])
        .envs(env_vars);

    // Spawn the child process with the pty
    let (mut pty, mut child) = portable_pty::start(cmd).unwrap();

    // Write to the pty (optional)
    writeln!(pty).unwrap();

    // Read from the pty (optional)
    let mut buffer = [0; 1024];
    let n = pty.read(&mut buffer).unwrap();
    if n > 0 {
        println!("Output: {}", &buffer[..n]);
    }

    // Wait for the child process to exit
    let status = child.wait().unwrap();
    println!("Child exited with status: {}", status);
}

