use std::path::Path;
use std::io;
use path_dedot::ParseDot;

fn path_to_file_url(path: &Path) -> io::Result<String> {
    let dedotted = path
        .components()
        .filter_map(|component| match component {
            std::path::Component::Normal(name) => Some(name),
            _ => None,
        })
        .collect::<Vec<_>>();

    let encoded_components: Vec<String> = dedotted
        .iter()
        .map(|component| {
            component
                .to_str()
                .ok_or(io::Error::new(io::ErrorKind::InvalidData, "Invalid component"))
                .to_string()
        })
        .map(|s| {
            s.chars()
                .map(|c| {
                    if c.is_alphanumeric() || c == '-' || c == '_' || c == '.' || c == '~' {
                        c
                    } else {
                        format!("%%%02X", c as u8)
                    }
                })
                .collect::<String>()
        })
        .collect();

    let url = format!("file://{}", encoded_components.join("/"));

    Ok(url)
}

