pub struct EventBuilder<D, M> {
    data: D,
    metadata: M,
    filters: Vec<String>,
}

impl<D, M> EventBuilder<D, M> {
    pub fn new(data: D, metadata: M) -> Self {
        EventBuilder {
            data,
            metadata,
            filters: Vec::new(),
        }
    }
}

pub trait EventBuilderTrait {
    fn with_filters(self, filters: Vec<String>) -> Self;
    fn with_metadata<M>(self, metadata: M) -> Self;
}

impl<D, M> EventBuilderTrait for EventBuilder<D, M> {
    fn with_filters(mut self, filters: Vec<String>) -> Self {
        self.filters = filters;
        self
    }

    fn with_metadata<M>(mut self, metadata: M) -> Self {
        self.metadata = metadata;
        self
    }
}

impl<D, M> From<EventBuilder<D, M>> for Event<D, M> {
    fn from(builder: EventBuilder<D, M>) -> Self {
        Event {
            data: builder.data,
            metadata: builder.metadata,
            filters: builder.filters,
        }
    }
}

