fn send_webhook_with_avatar_and_thread(
    bot: &Bot,
    webhook_id: Id<WebhookMarker>,
    token: &str,
    content: &str,
    avatar_url: &str,
    thread_id: Id<ChannelMarker>,
    thread_name: &str,
) -> Result<(), Error> {
    let http = HttpClient::new(bot.token().to_string());
    let webhook_url = format!("https://discord.com/api/webhooks/{}/{}", webhook_id, token);

    let mut embed = Embed::default();
    embed.author = Some(EmbedAuthor::new("", Some(avatar_url.to_string()), None));
    embed.title = Some("".to_string());
    embed.description = Some(content.to_string());
    embed.footer = Some(EmbedFooter::new("Sent via webhook", None));
    embed.image = Some(EmbedImage::new(avatar_url.to_string(), None));
    embed.provider = Some(EmbedProvider::new("", ""));
    embed.fields = vec![EmbedField::new("", "", false)];

    let message = Message {
        content: Some(content.to_string()),
        embeds: Some(vec![embed]),
        allowed_mentions: Some(AllowedMentions::new()
            .allowed_user_ids(vec![])
            .allowed_role_ids(vec![])
            .allowed_channel_ids(vec![])
            .allowed_mention_types(AllowedMentionTypes::new()
                .users(false)
                .roles(false)
                .channels(false)
                .everyone(false))),
        flags: Some(MessageFlags::SUPPRESS_NOTIFICATIONS),
        components: Some(vec![ActionRow::new(vec![Button::new(
            "primary",
            "Click me",
            "https://example.com",
            ComponentType::Button,
            false,
            false,
        )])]),
        ..Default::default()
    };

    let thread_name = thread_name.to_string();
    let thread_id = thread_id;

    let response = http.create_message(webhook_url, &message).await?;
    let message_id = response.id;

    let thread = bot.create_thread(thread_id, thread_name, Some(message_id)).await?;

    Ok(())
}

use anyhow::Result;
use fs::Fs;
use std::path::{Path, PathBuf};
use std::collections::HashSet;

fn list_installed_plugins(prettier: &Prettier) -> Result<Vec<String>> {
    let mut plugins = HashSet::new();
    let prettier_path = prettier.path();
    let mut paths = Vec::new();

    if prettier_path.exists() && prettier_path.is_dir() {
        paths.push(prettier_path);
    }

    for path in paths {
        if let Ok(entries) = Fs::read_dir(&path) {
            for entry in entries {
                if let Ok(entry) = entry {
                    let path = entry.path();
                    if path.is_dir() && path.join("package.json").exists() {
                        if let Ok(contents) = Fs::read_to_string(&path.join("package.json")) {
                            if let Ok(json) = serde_json::from_str(&contents) {
                                if let Some(kw) = json.get("keywords") {
                                    if let Some(kw_list) = kw.as_array() {
                                        for keyword in kw_list {
                                            if let Some(keyword_str) = keyword.as_str() {
                                                if keyword_str == "prettier-plugin" {
                                                    if let Ok(name) = Fs::read_to_string(path.join("name")) {
                                                        plugins.insert(name.trim().to_string());
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    Ok(Vec::from_iter(plugins))
}

