fn total_fees(resolved: &[Arc<ResolvedTransaction>]) -> Result<Capacity, Error> {
    let mut total_input_capacity = Capacity::zero();
    let mut total_output_capacity = Capacity::zero();

    for transaction in resolved {
        if let Some(tx) = transaction.as_ref() {
            // Skip cellbase transaction
            if tx.is_cellbase() {
                continue;
            }

            // Sum input capacities
            for input in tx.inputs() {
                if let Some(input_type) = input.type_() {
                    if let Some(capacity) = input_type.capacity() {
                        total_input_capacity = total_input_capacity.saturating_add(capacity);
                    }
                }
            }

            // Sum output capacities
            for output in tx.outputs() {
                if let Some(output_type) = output.type_() {
                    if let Some(capacity) = output_type.capacity() {
                        total_output_capacity = total_output_capacity.saturating_add(capacity);
                    }
                }
            }
        }
    }

    let total_fee = total_input_capacity.saturating_sub(total_output_capacity);
    Ok(total_fee)
}

fn check_transaction_uniqueness<DB>(transactions: &[MaybeCheckedTransaction], db: &DB) -> Result<(), ExecutorError>
where
    DB: StorageAsRef<ProcessedTransactions>,
{
    for transaction in transactions {
        if let Some(id) = &transaction.id {
            if db.as_ref().contains_key(id) {
                return Err(ExecutorError::TransactionIdAlreadyProcessed);
            }
        }
    }
    Ok(())
}

use afl;

fn fuzz_with_custom_panic<F>(mut closure: F)
where
    F: FnMut(&[u8]) + std::panic::RefUnwindSafe,
{
    let original_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(|info| {
        // Log the panic information
        println!("Panic occurred: {:?}", info);
        // Restore the original panic hook
        std::panic::set_hook(original_hook);
    }));

    afl::fuzz_nohook(|data| {
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            closure(data);
        }));
        match result {
            Ok(_) => {}
            Err(e) => {
                // Re-apply the custom panic hook in case it was reset
                std::panic::set_hook(Box::new(|info| {
                    println!("Panic occurred: {:?}", info);
                    std::panic::set_hook(original_hook);
                }));
                // Re-panic to allow the fuzzer to continue
                std::panic::resume_unwind(e);
            }
        }
    });
}

fn pretty_print_hir(expr: &hir::Expr, source: &str) -> String {
    let mut result = String::new();
    let line_col = LineColLookup::new(source);
    let start_line = line_col.line_col(expr.span.start).0;
    let start_col = line_col.line_col(expr.span.start).1;
    let end_line = line_col.line_col(expr.span.end).0;
    let end_col = line_col.line_col(expr.span.end).1;

    writeln!(&mut result, "Expression:").unwrap();
    writeln!(&mut result, "  Span: {}:{} - {}:{}", start_line, start_col, end_line, end_col).unwrap();
    writeln!(&mut result, "  Source:").unwrap();

    for line in start_line..=end_line {
        let line_str = source.lines().nth(line - 1).unwrap_or("");
        let line_len = line_str.len();
        let start_pos = if line == start_line { expr.span.start - line_col.offset(line) } else { 0 };
        let end_pos = if line == end_line { expr.span.end - line_col.offset(line) } else { line_len };

        let mut line_with_highlight = String::new();
        let mut pos = 0;

        while pos < line_len {
            if pos >= end_pos {
                break;
            }

            let ch = line_str.chars().nth(pos).unwrap();
            if pos >= start_pos && pos < end_pos {
                write!(&mut line_with_highlight, "\x1b[1;31m{} \x1b[0m", ch).unwrap();
            } else {
                write!(&mut line_with_highlight, "{} ", ch).unwrap();
            }
            pos += 1;
        }

        writeln!(&mut result, "    Line {}: {}", line, line_with_highlight).unwrap();
    }

    result
}

use zbus_lockstep::{get_signal_body_type, LockstepError};
use zvariant::Type;

fn validate_struct_against_signal<T>(
    xml: impl std::io::Read,
    interface_name: &str,
    signal_name: &str,
) -> Result<(), Box<dyn std::error::Error>>
where
    T: zvariant::Type,
{
    let signal_type = get_signal_body_type(xml, interface_name, signal_name)
        .map_err(|e| Box::new(LockstepError::from(e)) as Box<dyn std::error::Error>)?;

    let struct_type = Type::type_name::<T>();

    if signal_type != struct_type {
        return Err(format!(
            "Type mismatch: expected signal type '{}', got struct type '{}'",
            signal_type, struct_type
        ).into());
    }

    Ok(())
}

