fn filter_by_platform(&self, platform: &Platform) -> Self {
    let mut result = VirtualPackages::new();
    let mut is_windows = false;
    let mut is_linux = false;
    let mut is_osx = false;
    let mut is_cuda = false;
    let mut is_libc = false;
    let mut is_archspec = false;

    match platform {
        Platform::Linux => {
            is_linux = true;
        }
        Platform::Windows => {
            is_windows = true;
        }
        Platform::Osx => {
            is_osx = true;
        }
        Platform::Cuda => {
            is_cuda = true;
        }
        Platform::LibC => {
            is_libc = true;
        }
        Platform::Archspec => {
            is_archspec = true;
        }
        _ => {}
    }

    if is_windows {
        result.windows = self.windows.clone();
    }
    if is_linux {
        result.linux = self.linux.clone();
    }
    if is_osx {
        result.osx = self.osx.clone();
    }
    if is_cuda {
        result.cuda = self.cuda.clone();
    }
    if is_libc {
        result.libc = self.libc.clone();
    }
    if is_archspec {
        result.archspec = self.archspec.clone();
    }

    result
}

