use crate::Properties;
use crate::rawvalue::RawValue;

fn to_toml(props: &Properties) -> String {
    let mut toml_lines = Vec::new();
    for (key, value) in props {
        let key = key.to_string();
        let value = match value {
            RawValue::String(s) => s.to_string(),
            RawValue::Boolean(b) => b.to_string(),
            RawValue::Integer(i) => i.to_string(),
            RawValue::Float(f) => f.to_string(),
        };

        // Handle special cases
        match key.as_str() {
            "indent_style" => {
                if value == "space" || value == "tab" {
                    toml_lines.push(format!("indent_style = \"{}\"", value));
                } else {
                    toml_lines.push(format!("indent_style = {}", value));
                }
            }
            _ => {
                // Quote the value if it contains spaces or special characters
                if value.contains(' ') || value.contains('\n') || value.contains('\t') {
                    toml_lines.push(format!("{} = \"{}\"", key, value));
                } else {
                    toml_lines.push(format!("{} = {}", key, value));
                }
            }
        }
    }

    toml_lines.join("\n")
}

fn filter_outline_by_level(outline: &Outline, min_level: usize) -> Outline {
    fn filter_recursive(items: &[OutlineItem], min_level: usize) -> Vec<OutlineItem> {
        items.iter().filter_map(|item| {
            if item.heading_level >= min_level {
                let mut filtered_children = filter_recursive(&item.children, min_level);
                if filtered_children.is_empty() {
                    Some(OutlineItem {
                        position: item.position.clone(),
                        heading_level: item.heading_level,
                        text: item.text.clone(),
                        children: Vec::new(),
                    })
                } else {
                    Some(OutlineItem {
                        position: item.position.clone(),
                        heading_level: item.heading_level,
                        text: item.text.clone(),
                        children: filtered_children,
                    })
                }
            } else {
                None
            }
        }).collect()
    }

    Outline {
        items: filter_recursive(&outline.items, min_level),
    }
}

