    let img = ImageBuffer::from_raw(width, height, pixels.to_vec())
        .ok_or("Invalid pixel data")?;
    let mut buffer = Vec::new();
    img.write_to(&mut buffer, ImageOutputFormat::Png)?;
    Ok(buffer)
}

