fn extract_indices<T, N, M>(vector: &FixedVector<T, N>, indices: &[usize>) -> Result<FixedVector<T, M>, Error>
where
    T: Clone,
    N: Unsigned,
    M: Unsigned,
{
    if indices.is_empty() {
        return Err(Error::new("Indices list is empty"));
    }

    let mut seen = Vec::new();
    let mut valid_indices = Vec::new();

    for &index in indices {
        if index >= N::to_usize() {
            return Err(Error::new("Index out of bounds"));
        }

        if seen.contains(&index) {
            return Err(Error::new("Duplicate index in indices list"));
        }

        seen.push(index);
        valid_indices.push(index);
    }

    if valid_indices.len() != M::to_usize() {
        return Err(Error::new("Indices list length does not match target FixedVector length"));
    }

    let mut result = FixedVector::new();
    for &index in &valid_indices {
        result.push(vector[index].clone());
    }

    Ok(result)
}

