fn primary_key_for_table(table: &Table) -> PrimaryKey {
    // Find the column with the name "ID"
    let id_column = table.columns.iter().find(|col| col.name == "ID");

    // Ensure the ID column exists
    let id_column = id_column.expect("Table must have an ID column");

    // Create the primary key constraint using the ID column
    PrimaryKey {
        name: format!("pk_{}", table.name),
        columns: vec![id_column.name.clone()],
        data_type: DbType::from_column_type(id_column.data_type),
    }
}

use std::path::Path;
