fn merge_files_to_string(
    base: &Path,
    other: &Path,
    this: &Path,
) -> io::Result<String> {
    let base_content = std::fs::read_to_string(base)?;
    let other_content = std::fs::read_to_string(other)?;
    let this_content = std::fs::read_to_string(this)?;

    let merged = Merge3::new()
        .with_markers(StandardMarkers)
        .merge(&base_content, &other_content, &this_content)
        .map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;

    Ok(merged)
}

use std::time::Duration;
use tokio_with_wasm::time::{interval, Interval};

struct Debouncer {
    interval: Interval,
    pending: Option<Duration>,
}

impl Debouncer {
    fn new(pause: Duration) -> Self {
        Debouncer {
            interval: interval(pause),
            pending: None,
        }
    }

    async fn reset(&mut self, payload: Box<dyn FnMut() -> () + 'static>) {
        if let Some(pending) = self.pending {
            self.interval.cancel();
        }
        self.pending = Some(self.interval.set().await);
        self.interval.set_callback(Box::new(move || {
            if let Some(duration) = self.pending {
                if duration == self.interval.elapsed() {
                    payload();
                    self.pending = None;
                }
            }
        }));
    }

    async fn trigger(&mut self, payload: Box<dyn FnMut() -> () + 'static>) {
        self.reset(payload).await;
    }
}

use hdwallet_bitcoin::{Network, PrivKey, Error};
use hdwallet::{ExtendedPrivKey, DefaultKeyChain, KeyChain};

fn derive_bitcoin_master_key(seed: &[u8], network: Network) -> Result<String, Error> {
    // Create the extended private key from the seed
    let extended_priv_key = ExtendedPrivKey::new_master(network, seed)?;

    // Derive the master private key from the extended private key
    let master_priv_key = extended_priv_key.derive_priv(0, None)?;

    // Serialize the master private key into the appropriate format
    let priv_key = PrivKey::from_slice(master_priv_key.as_ref())?;

    // Convert the private key to a string representation
    Ok(priv_key.to_string())
}

