fn from_paths<P>(paths: P) -> FileResult<FileChangeSet>
    where
        P: IntoIterator,
        P::Item: AsRef<Path>,
{
    let mut change_set = FileChangeSet::new();
    for path in paths {
        let path = path.as_ref();
        if path.is_file() {
            let content = std::fs::read_to_string(path)?;
            let snapshot = FileSnapshot::new(ImmutPath::from_path(path)?, Bytes::from(content));
            change_set.insertions.push(snapshot);
        }
    }
    Ok(change_set)
}

use super::*;

fn project_point(point: &Vector3, projection: &Matrix4x4) -> Vector2 {
    let homogeneous = projection * Vector4::new(point.x, point.y, point.z, 1.0);
    let w = homogeneous.w;
    let x = homogeneous.x / w;
    let y = homogeneous.y / w;
    Vector2::new(x, y)
}

use std::collections::HashMap;
use std::sync::Arc;
use arrow::record_batch::RecordBatch;
use arrow::datatypes::{Schema, DataType};
use arrow::array::{Int32Array, Int64Array, Float32Array, Float64Array, BooleanArray, StringArray, BinaryArray};
use datafusion_common::{Result, DataFusionError};
use apache_avro::{Writer, Schema as AvroSchema, types::Value};

fn write_batch_to_avro<W: std::io::Write>(
    batch: &RecordBatch,
    writer: W,
) -> Result<()> {
    let schema = batch.schema();
    let avro_schema = schema_to_avro_schema(schema)?;
    let mut avro_writer = Writer::new(avro_schema, writer);
    for i in 0..batch.num_rows() {
        let row = batch.row(i);
        let avro_record = row_to_avro_record(row, &schema)?;
        avro_writer.write(avro_record)?;
    }
    Ok(())
}

fn schema_to_avro_schema(schema: &Schema) -> Result<AvroSchema> {
    let fields = schema.fields().iter().map(|field| {
        let name = field.name().to_string();
        let data_type = field.data_type();
        let avro_type = data_type_to_avro_type(data_type);
        Ok(AvroSchema::record(name, vec![(name, avro_type)]))
    }).collect::<Result<Vec<_>>>()?;
    Ok(AvroSchema::record("record".to_string(), fields))
}

fn data_type_to_avro_type(data_type: &DataType) -> AvroSchema {
    match data_type {
        DataType::Int32 => AvroSchema::int(),
        DataType::Int64 => AvroSchema::long(),
        DataType::Float32 => AvroSchema::float(),
        DataType::Float64 => AvroSchema::double(),
        DataType::Boolean => AvroSchema::boolean(),
        DataType::Utf8 => AvroSchema::string(),
        DataType::Binary => AvroSchema::bytes(),
        _ => panic!("Unsupported data type"),
    }
}

fn row_to_avro_record(row: &arrow::array::ArrayRef, schema: &Schema) -> Result<Value> {
    let mut record = HashMap::new();
    for (i, field) in schema.fields().iter().enumerate() {
        let array = row.column(i);
        let value = match array {
            Int32Array::new(_) => {
                let value = array.as_any().downcast_ref::<Int32Array>().unwrap().value(0);
                Value::from(value as i64)
            },
            Int64Array::new(_) => {
                let value = array.as_any().downcast_ref::<Int64Array>().unwrap().value(0);
                Value::from(value)
            },
            Float32Array::new(_) => {
                let value = array.as_any().downcast_ref::<Float32Array>().unwrap().value(0);
                Value::from(value as f64)
            },
            Float64Array::new(_) => {
                let value = array.as_any().downcast_ref::<Float64Array>().unwrap().value(0);
                Value::from(value)
            },
            BooleanArray::new(_) => {
                let value = array.as_any().downcast_ref::<BooleanArray>().unwrap().value(0);
                Value::from(value)
            },
            StringArray::new(_) => {
                let value = array.as_any().downcast_ref::<StringArray>().unwrap().value(0);
                Value::from(value)
            },
            BinaryArray::new(_) => {
                let value = array.as_any().downcast_ref::<BinaryArray>().unwrap().value(0);
                Value::from(value)
            },
            _ => panic!("Unsupported array type"),
        };
        record.insert(field.name().to_string(), value);
    }
    Ok(Value::record(record))
}

use aotuv_lancer_vorbis_sys::*;
use std::ptr;
use std::os::raw::c_long;
use std::mem::MaybeUninit;

fn decode_to_mono(input: &[u8]) -> Result<Vec<f32>, i32> {
    unsafe {
        let mut decoder = ptr::null_mut();
        let mut error = 0;
        let mut info = MaybeUninit::uninit();
        let mut stream = MaybeUninit::uninit();
        let mut buffer = MaybeUninit::uninit();
        let mut buffer_size = 0;
        let mut samples = 0;
        let mut sample_rate = 0;
        let mut channel_count = 0;

        // Initialize decoder
        error = vorbis_decoder_init(&mut decoder, input.as_ptr(), input.len() as c_long);
        if error != 0 {
            return Err(error);
        }

        // Get info
        error = vorbis_decoder_get_info(decoder, info.as_mut_ptr());
        if error != 0 {
            vorbis_decoder_delete(decoder);
            return Err(error);
        }

        // Get stream info
        error = vorbis_decoder_get_stream_info(decoder, stream.as_mut_ptr());
        if error != 0 {
            vorbis_decoder_delete(decoder);
            return Err(error);
        }

        // Get buffer size
        error = vorbis_decoder_get_buffer_size(decoder, &mut buffer_size);
        if error != 0 {
            vorbis_decoder_delete(decoder);
            return Err(error);
        }

        // Allocate buffer
        buffer = MaybeUninit::new(ptr::null_mut());
        error = vorbis_decoder_get_buffer(decoder, buffer.as_mut_ptr(), buffer_size);
        if error != 0 {
            vorbis_decoder_delete(decoder);
            return Err(error);
        }

        // Get sample rate and channel count
        sample_rate = vorbis_decoder_get_sample_rate(decoder);
        channel_count = vorbis_decoder_get_channels(decoder);

        // Check if stereo
        if channel_count != 2 {
            vorbis_decoder_delete(decoder);
            return Err(-1); // Not stereo
        }

        // Decode and mix
        let mut mono_samples = Vec::new();
        let mut sample = MaybeUninit::uninit();
        let mut output = MaybeUninit::uninit();
        let mut output_size = 0;
        let mut output_ptr = ptr::null_mut();
        let mut decoded_samples = 0;

        loop {
            error = vorbis_decoder_get_output(decoder, output.as_mut_ptr(), &mut output_size);
            if error != 0 {
                break;
            }

            output_ptr = output.as_mut_ptr();
            decoded_samples = output_size / channel_count;

            for i in 0..decoded_samples {
                let left = *output_ptr.add(i * channel_count);
                let right = *output_ptr.add(i * channel_count + 1);
                let mono = (left as f32 + right as f32) / 2.0;
                mono_samples.push(mono);
            }

            error = vorbis_decoder_flush(decoder);
            if error != 0 {
                break;
            }
        }

        vorbis_decoder_delete(decoder);

        Ok(mono_samples)
    }
}

fn total_commission_of_high_stake_validators(vote_accounts: &VoteAccounts, stake_threshold: u64) -> u64 {
    let mut total_commission = 0;
    for vote_account in vote_accounts.accounts.iter() {
        if let Some(stake) = vote_account.vote.get_stake() {
            if stake > stake_threshold {
                if let Some(commission) = vote_account.vote.get_commission() {
                    total_commission += commission;
                }
            }
        }
    }
    total_commission
}

