use std::io::Read;
use base64::prelude::BASE64_STANDARD;
use ecow::EcoString;
use flate2::read::GzDecoder;
use ttf_parser::GlyphId;
use typst_library::foundations::Bytes;
use typst_library::text::Font;
use typst_utils::hash128;
use xmlparser::{Tokenizer, Token};

fn convert_svg_glyph_to_base64_url(font: &Font, id: GlyphId) -> Option<EcoString> {
    let glyph_data = font.get_glyph(id).ok()?;
    let bytes = glyph_data.as_bytes()?;
    let mut decoder = GzDecoder::new(bytes);
    let mut contents = Vec::new();
    decoder.read_to_end(&mut contents).ok()?;

    let mut tokenizer = Tokenizer::new(&contents);
    let mut svg_content = String::new();
    let mut in_svg = false;

    while let Some(token) = tokenizer.next() {
        match token {
            Token::StartTag(name, _) if name == b"svg" => {
                in_svg = true;
                svg_content.push_str("<svg");
            }
            Token::EndTag(name, _) if name == b"svg" => {
                in_svg = false;
                svg_content.push_str("</svg>");
            }
            Token::Text(text) if in_svg => {
                svg_content.push_str(text);
            }
            _ => {}
        }
    }

    if !in_svg {
        return None;
    }

    let mut view_box = None;
    let mut width = "100%";
    let mut height = "100%";

    let mut tokenizer = Tokenizer::new(svg_content.as_bytes());
    while let Some(token) = tokenizer.next() {
        match token {
            Token::StartTag(name, attrs) if name == b"svg" => {
                for (name, value) in attrs {
                    if name == b"viewBox" {
                        view_box = Some(value);
                    } else if name == b"width" {
                        width = value;
                    } else if name == b"height" {
                        height = value;
                    }
                }
            }
            _ => {}
        }
    }

    if view_box.is_none() {
        return None;
    }

    let view_box = view_box.unwrap();
    let data_url = format!(
        "data:image/svg+xml;base64,{}",
        BASE64_STANDARD.encode(svg_content.as_bytes())
    );

    Some(EcoString::from(data_url))
}

