fn convert_to_snark_and_get_receipt(client: &Client, session_uuid: String, method_id: [u32; 8]) -> Result<Receipt, SdkErr> {
    // Convert the session to a SNARK
    let snark_id = client.convert_to_snark(session_uuid.clone(), method_id)?;

    // Wait for the SNARK conversion to complete
    let mut snark_id_bytes = [0u8; 32];
    snark_id.to_bytes(&mut snark_id_bytes);
    let mut snark_id_str = String::new();
    bincode::serialize_into(&mut snark_id_str, &snark_id_bytes).unwrap();

    let mut snark_id_result = None;
    while snark_id_result.is_none() {
        std::thread::sleep(Duration::from_secs(5));
        let snark_id_opt = client.get_snark_id(snark_id_str.clone())?;
        if let Some(id) = snark_id_opt {
            snark_id_result = Some(id);
        }
    }

    let snark_id = snark_id_result.unwrap();

    // Download the receipt
    let receipt_bytes = client.get_receipt(&snark_id)?;
    let receipt: Receipt = bincode::deserialize(&receipt_bytes)?;

    Ok(receipt)
}

