fn rename_file_with_retries<TSys>(sys: &TSys, old_path: &Path, new_path: &Path) -> std::io::Result<()>
where
    TSys: FsRename + ThreadSleep,
{
    let mut retries = 3;
    loop {
        match sys.rename(old_path, new_path) {
            Ok(_) => return Ok(()),
            Err(e) => {
                if retries == 0 {
                    return Err(e);
                }
                retries -= 1;
                sys.sleep(std::time::Duration::from_millis(100));
            }
        }
    }
}

use std::collections::HashMap;
use std::fs;
use std::io::{BufRead, BufReader};
use std::path::Path;
use dotenv_flow::{Result, from_path_iter};

fn load_with_extra_substitutions<P: AsRef<Path>>(path: P, extra: &HashMap<String, String>) -> Result<()> {
    let file = fs::File::open(path)?;
    let reader = BufReader::new(file);

    for line in reader.lines() {
        let line = line?;
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }

        let mut parts = line.split('=');
        let key = parts.next().unwrap().trim().to_string();
        let value = parts.next().unwrap().trim().to_string();

        // Apply extra substitutions
        let mut substituted_value = value;
        for (k, v) in extra {
            if substituted_value.contains(k.as_str()) {
                substituted_value = substituted_value.replace(k.as_str(), v);
            }
        }

        // Apply dotenv_flow substitution
        let substituted_value = from_path_iter!(substituted_value, |s| s);

        // Set the environment variable
        std::env::set_var(&key, substituted_value);
    }

    Ok(())
}

