use www_authenticate::{WwwAuthenticate, Challenge};
use hyperx::header::Raw;

fn parse_www_authenticate(header: &str) -> hyperx::Result<WwwAuthenticate> {
    let raw_header = Raw::from_str(header)?;
    let mut www_authenticate = WwwAuthenticate::default();
    let mut challenges = Vec::new();

    for token in raw_header.split(',') {
        let token = token.trim();
        if token.is_empty() {
            continue;
        }

        let mut parts = token.split('=');
        let scheme = parts.next().ok_or(hyperx::Error::invalid())?;
        let mut scheme = scheme.trim();

        if scheme.eq_ignore_ascii_case("Bearer") {
            let mut params = std::collections::HashMap::new();
            let mut remaining = parts.next().ok_or(hyperx::Error::invalid())?;
            remaining = remaining.trim_matches('\"').trim();

            for param in remaining.split(';') {
                let param = param.trim();
                if param.is_empty() {
                    continue;
                }

                let mut param_parts = param.split('=');
                let name = param_parts.next().ok_or(hyperx::Error::invalid())?;
                let value = param_parts.next().ok_or(hyperx::Error::invalid())?;
                params.insert(name.trim().to_string(), value.trim().to_string());
            }

            challenges.push(Challenge::Bearer(params));
        } else if scheme.eq_ignore_ascii_case("Basic") {
            let mut params = std::collections::HashMap::new();
            let mut remaining = parts.next().ok_or(hyperx::Error::invalid())?;
            remaining = remaining.trim_matches('\"').trim();

            for param in remaining.split(';') {
                let param = param.trim();
                if param.is_empty() {
                    continue;
                }

                let mut param_parts = param.split('=');
                let name = param_parts.next().ok_or(hyperx::Error::invalid())?;
                let value = param_parts.next().ok_or(hyperx::Error::invalid())?;
                params.insert(name.trim().to_string(), value.trim().to_string());
            }

            challenges.push(Challenge::Basic(params));
        } else {
            return Err(hyperx::Error::invalid());
        }
    }

    www_authenticate.challenges = challenges;
    Ok(www_authenticate)
}

fn hashmap_diff<K, V>(left: &HashMap<K, V>, right: &HashMap<K, V>) -> Vec<(K, diffus::edit::map::Edit<V>)>
where
    K: Hash + Eq + Clone,
    for<'a> V: Diffable<'a>,
{
    let mut edits = Vec::new();
    let all_keys: std::collections::HashSet<_> = left.keys().cloned().chain(right.keys().cloned()).collect();

    for key in all_keys {
        let left_value = left.get(&key).cloned();
        let right_value = right.get(&key).cloned();

        let edit = match (left_value, right_value) {
            (Some(left_val), Some(right_val)) => {
                if left_val == right_val {
                    diffus::edit::map::Edit::NoChange
                } else {
                    diffus::edit::map::Edit::Change(left_val, right_val)
                }
            },
            (Some(_), None) => diffus::edit::map::Edit::Remove,
            (None, Some(_)) => diffus::edit::map::Edit::Insert,
            (None, None) => diffus::edit::map::Edit::NoChange,
        };

        edits.push((key, edit));
    }

    edits
}

use js_sys::{Array, Uint8Array};
use libp2p_webtransport_websys::bindings::{WebTransportOptions, WebTransportHash};
use libp2p_webtransport_websys::Error;

pub fn add_server_cert_hash(opts: &mut WebTransportOptions, hash_bytes: &[u8]) -> Result<(), Error> {
    let digest = Uint8Array::from(hash_bytes);
    let mut hash = WebTransportHash::new();
    hash.algorithm("sha-256").value(&digest);

    let hashes = Array::new();
    hashes.push(&hash);
    opts.server_certificate_hashes(&hashes);
    Ok(())
}

use fax::ByteReader;
use fax::maps::mode;
use fax::maps::Mode;

fn extract_modes(data: &[u8]) -> Vec<Mode> {
    let mut reader = ByteReader::new(data);
    let mut modes = Vec::new();
    let mut bytes_read = 0;

    while bytes_read < data.len() {
        // Check if we have enough bytes for the current mode
        if bytes_read + 1 > data.len() {
            break;
        }

        let mode_byte = data[bytes_read];
        bytes_read += 1;

        // Determine the mode based on the byte value
        let mode = match mode_byte {
            0x00 => Mode::Pass,
            0x01 => Mode::Vertical,
            0x02 => Mode::Horizontal,
            0x03 => Mode::VerticalHorizontal,
            0x04 => Mode::VerticalRepeat,
            0x05 => Mode::HorizontalRepeat,
            0x06 => Mode::VerticalHorizontalRepeat,
            0x07 => Mode::Reserved,
            _ => Mode::Reserved,
        };

        modes.push(mode);
    }

    modes
}

use std::sync::Arc;
use databend_client::{APIClient, Result};
use tokio_stream::StreamExt;

fn fetch_all_rows(client: &Arc<APIClient>, sql: &str) -> Result<Vec<Vec<String>>> {
    let mut rows = Vec::new();
    let mut stream = client.query(sql)?;

    while let Some(result) = stream.next().await {
        let result = result?;
        for row in result.rows {
            let mut row_data = Vec::new();
            for field in row.fields {
                row_data.push(field.value.to_string());
            }
            rows.push(row_data);
        }
    }

    Ok(rows)
}

fn filter_functions_by_keyword(docs: &Documentation, keyword: &str) -> Vec<Metadata> {
