        .filter_map(|item| {
            if let Item::Function(func) = item {
                if func.doc().is_some() {
                    if !func.doc().unwrap().contains(keyword) {
                        Some(func.metadata().clone())
                    } else {
                        None
                    }
                } else {
                    Some(func.metadata().clone())
                }
            } else {
                None
            }
        })
        .collect()
}

