fn filter_by_material(obj_data: &ObjData, material_name: &str) -> ObjData {
    let mut new_obj_data = ObjData::new();
    let mut groups_to_include = HashSet::new();
    let mut objects_to_include = HashSet::new();

    for group in &obj_data.groups {
        if let Some(material) = group.material.as_ref() {
            if material.name == material_name {
                groups_to_include.insert(group.name.clone());
            }
        }
    }

    for object in &obj_data.objects {
        if groups_to_include.contains(&object.group) {
            objects_to_include.insert(object.name.clone());
        }
    }

    for material in &obj_data.materials {
        if material.name == material_name {
            new_obj_data.materials.push(material.clone());
            break;
        }
    }

    for group in &obj_data.groups {
        if groups_to_include.contains(&group.name) {
            new_obj_data.groups.push(group.clone());
        }
    }

    for object in &obj_data.objects {
        if objects_to_include.contains(&object.name) {
            new_obj_data.objects.push(object.clone());
        }
    }

    new_obj_data
}

fn merge_aggregates(target: &mut LastVotedForkSlotsAggregate, source: LastVotedForkSlotsAggregate) {
    // Merge validator reports
    for (pubkey, report) in source.validator_reports {
        *target.validator_reports.entry(pubkey).or_insert_with(HashMap::new) = report;
    }

    // Merge stake maps
    for (pubkey, stake) in source.stake_map {
        *target.stake_map.entry(pubkey).or_insert_with(HashMap::new) = stake;
    }

    // Merge slots that need repair
    for slot in source.slots_to_repair {
        target.slots_to_repair.insert(slot);
    }

    // Merge last_voted_fork_slots
    for (slot, last_voted) in source.last_voted_fork_slots {
        *target.last_voted_fork_slots.entry(slot).or_insert_with(HashMap::new) = last_voted;
    }
}

