fn export_config(config: &CKBAppConfig, output_path: &Path) -> Result<(), ExitCode> {
    // Create parent directories if they do not exist
    if let Err(e) = fs::create_dir_all(output_path.parent().unwrap()) {
        return Err(ExitCode::from(e));
    }

    // Serialize the configuration to TOML
    let config_str = match to_string(config) {
        Ok(s) => s,
        Err(e) => return Err(ExitCode::from(e)),
    };

    // Write the TOML string to the output file
    let mut file = match fs::File::create(output_path) {
        Ok(f) => f,
        Err(e) => return Err(ExitCode::from(e)),
    };

    if let Err(e) = file.write_all(config_str.as_bytes()) {
        return Err(ExitCode::from(e));
    }

    Ok(())
}

fn user_can_share(&self, user_id: u64, cx: &App) -> bool {
    if let Some(call) = self.active_call(cx) {
        if let Some(room) = call.room() {
            if let Some(local_participant) = room.local_participant() {
                if local_participant.role() == ChannelRole::Moderator {
                    return true;
                }
            }

            for participant in room.remote_participants() {
                if participant.id() == user_id && participant.role() == ChannelRole::Moderator {
                    return true;
                }
            }
        }
    }

    false
}

