use crate::bindings::{WebTransportOptions, WebTransportHash};
use js_sys::{Array, Uint8Array};
use multihash::Multihash;

fn build_webtransport_options<I>(
    hashes: I,
) -> crate::bindings::WebTransportOptions
where
    I: IntoIterator<Item = Multihash<64>>,
{
    let mut array = Array::new();
    for hash in hashes {
        let mut bytes = Vec::with_capacity(hash.digest.len());
        bytes.extend_from_slice(&hash.digest);
        let uint8_array = Uint8Array::new_with_length(bytes.len() as u32);
        uint8_array.set_u8_array_with_length(&bytes);
        let hash_obj = WebTransportHash::new_with_byte_array(&uint8_array);
        array.push(&hash_obj);
    }
    let mut options = WebTransportOptions::new();
    options.set_server_certificate_hashes(&array);
    options
}

fn to_vec_checked(&self) -> Result<Vec<u8>, ()> {
    let mut result = Vec::new();
    let mut current_block = self.as_ptr();

    while !current_block.is_null() {
        unsafe {
            let block = RcBlock::from_raw(current_block as *mut c_void);
            let ptr = block.as_mut_ptr();
            let len = block.len();

            if ptr.is_null() || len == 0 {
                return Err(());
            }

            // Check if the block is contiguous and can be safely copied
            if !slice::from_raw_parts(ptr, len).is_empty() {
                result.extend_from_slice(slice::from_raw_parts(ptr, len));
            }

            // Move to the next block
            current_block = block.next();
        }
    }

    Ok(result)
}

use arrow_schema::ArrowError;
use parquet_variant::Variant;
use parquet_variant_json::{variant_to_json_string, variant_to_json_value};
use serde_json::Value;
use chrono::DateTime;
use chrono::Utc;
use chrono::DateTime;
