use std::collections::HashMap;

fn variant_to_custom_json(variant: &Variant) -> Result<String, ArrowError> {
    let json_value = variant_to_json_value(variant)?;
    let formatted_value = format_json_value(&json_value)?;
    Ok(variant_to_json_string(&formatted_value)?)
}

fn format_json_value(value: &Value) -> Result<Value, ArrowError> {
    match value {
        Value::Object(obj) => {
            let mut new_obj = HashMap::new();
            for (key, val) in obj {
                let formatted_val = format_json_value(val)?;
                new_obj.insert(key.clone(), formatted_val);
            }
            Ok(Value::Object(new_obj))
        }
        Value::Array(arr) => {
            let mut new_arr = Vec::new();
            for val in arr {
                let formatted_val = format_json_value(val)?;
                new_arr.push(formatted_val);
            }
            Ok(Value::Array(new_arr))
        }
        Value::String(s) => {
            if let Ok(dt) = parse_timestamp(s) {
                Ok(Value::String(format_timestamp(&dt)))
            } else {
                Ok(value.clone())
            }
        }
        _ => Ok(value.clone()),
    }
}

fn parse_timestamp(s: &str) -> Result<DateTime<Utc>, ArrowError> {
    let datetime = DateTime::parse_from_rfc3339(s)
        .map_err(|e| ArrowError::InvalidArgument(format!("Invalid timestamp: {}", e)))?;
    Ok(datetime.with_timezone(&Utc))
}

fn format_timestamp(dt: &DateTime<Utc>) -> String {
    let naive = dt.naive_utc();
    let formatted = format!(
        "{}-{:02}-{:02} {:02}:{:02}:{:02}.{:06}",
        naive.year(),
        naive.month(),
        naive.day(),
        naive.hour(),
        naive.minute(),
        naive.second(),
        naive.nanosecond()
    );
    formatted
}

fn set_tiered_whitelist(
    deps: DepsMut,
    env: Env,
    info: MessageInfo,
    whitelist_addr: &str,
) -> Result<Response, ContractError> {
    // Check if the caller is authorized
    nonpayable(info)?;

    // Query the current configuration
    let config: crate::state::Config = CONFIG.load(deps.storage)?;
    let config_version = config.version;

    // Query the factory parameters to get minimum mint price
    let factory_response: vending_factory::msg::ParamsResponse =
        deps.querier.query_wasm_smart(vending_factory::contract_addr(), &vending_factory::msg::QueryMsg::Params {})
            .map_err(|e| ContractError::QueryError(e.to_string()))?;

    let min_mint_price = factory_response.min_mint_price;

    // Query the tiered whitelist contract to get its configuration
    let whitelist_config: sg_tiered_whitelist::msg::TieredWhitelistConfigResponse =
        deps.querier.query_wasm_smart(whitelist_addr, &sg_tiered_whitelist::msg::QueryMsg::Config {})
            .map_err(|e| ContractError::QueryError(e.to_string()))?;

    // Validate that the tiered whitelist has the correct stages
    let allowed_stages = ["fs", "ss", "ts"];
    let whitelist_stages: Vec<&str> = whitelist_config.stages.iter().map(|s| s.as_str()).collect();
    let mut valid_stages = true;
    for stage in &whitelist_stages {
        if !allowed_stages.contains(stage) {
            valid_stages = false;
            break;
        }
    }

    if !valid_stages {
        return Err(ContractError::InvalidStage(format!("Invalid stage in whitelist: {:?}", whitelist_stages)));
    }

    // Check that the mint price aligns with the factory's minimum requirement
    if whitelist_config.mint_price < min_mint_price {
        return Err(ContractError::InvalidMintPrice(format!(
            "Whitelist mint price {} is below factory minimum {}",
            whitelist_config.mint_price, min_mint_price
        )));
    }

    // Validate that the whitelist does not exceed the allowed mint counts
    let fs_mint_count = WHITELIST_FS_MINT_COUNT.load(deps.storage)?;
    let ss_mint_count = WHITELIST_SS_MINT_COUNT.load(deps.storage)?;
    let ts_mint_count = WHITELIST_TS_MINT_COUNT.load(deps.storage)?;

    let whitelist_fs_mint_count = whitelist_config.fs_mint_count;
    let whitelist_ss_mint_count = whitelist_config.ss_mint_count;
    let whitelist_ts_mint_count = whitelist_config.ts_mint_count;

    if whitelist_fs_mint_count > fs_mint_count {
        return Err(ContractError::ExceedsMaxMintCount(format!(
            "Whitelist fs mint count {} exceeds max allowed {}",
            whitelist_fs_mint_count, fs_mint_count
        )));
    }

    if whitelist_ss_mint_count > ss_mint_count {
        return Err(ContractError::ExceedsMaxMintCount(format!(
            "Whitelist ss mint count {} exceeds max allowed {}",
            whitelist_ss_mint_count, ss_mint_count
        )));
    }

    if whitelist_ts_mint_count > ts_mint_count {
        return Err(ContractError::ExceedsMaxMintCount(format!(
            "Whitelist ts mint count {} exceeds max allowed {}",
            whitelist_ts_mint_count, ts_mint_count
        )));
    }

    // Update the whitelist address in the configuration
    let mut new_config = config;
    new_config.whitelist_addr = whitelist_addr.to_string();
    new_config.version = config_version + 1;

    CONFIG.save(deps.storage, &new_config)?;

    // Build the response
    let mut response = Response::new();
    response.add_message(WasmMsg::Execute {
        contract_addr: whitelist_addr.to_string(),
        msg: to_json_binary(&sg_tiered_whitelist::msg::ExecuteMsg::Initialize {}),
        funds: vec![],
    });

    Ok(response)
}

