use vortex_dtype::datetime::TimeUnit;
use crate::{DateTimePartsArray, timestamp, TimestampParts};

fn combine_parts_to_timestamp(array: &DateTimePartsArray, time_unit: TimeUnit) -> VortexResult<ArrayRef> {
    let mut result = PrimitiveArray::new(
        time_unit.to_dtype(),
        Validity::new_unchecked(array.len()),
        Vec::with_capacity(array.len()),
    );

    for i in 0..array.len() {
        let parts = array.get(i).unwrap();
        let timestamp_value = timestamp::combine(
            parts.year as i64,
            parts.month as u8,
            parts.day as u8,
            parts.hour as u8,
            parts.minute as u8,
            parts.second as u8,
            parts.subsecond as u64,
            time_unit,
        );
        result.data_mut().push(timestamp_value);
    }

    Ok(result.into())
}

