fn parse_lock_versions(lock_path: &Path) -> Result<HashMap<String, String>, std::io::Error> {
    let contents = fs::read_to_string(lock_path)?;
    let mut dependencies = HashMap::new();
    let lines: Vec<&str> = contents.lines().collect();

    for line in lines {
        if line.trim().starts_with("package") {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 3 {
                let crate_name = parts[1].trim_matches('"');
                let version = parts[2].trim_matches('"');
                dependencies.insert(crate_name.to_string(), version.to_string());
            }
        }
    }

    Ok(dependencies)
}

use fuzzyhash::FuzzyHash;

fn most_similar<'a>(target: &FuzzyHash, candidates: impl IntoIterator<Item=&'a str>) -> Option<String> {
    let mut best_match = None;
    let mut max_similarity = 0;

    for candidate in candidates {
        if let Ok(c_hash) = FuzzyHash::from_str(candidate) {
            let similarity = target.similarity(&c_hash);
            if similarity > max_similarity {
                max_similarity = similarity;
                best_match = Some(candidate.to_string());
            }
        }
    }

    best_match
}

