struct MetricRateLimiter {
    limit: usize,
    buffer: Vec<Metric>,
    last_check: SystemTime,
}

impl MetricRateLimiter {
    fn new(limit_per_sec: usize) -> Self {
        MetricRateLimiter {
            limit: limit_per_sec,
            buffer: Vec::new(),
            last_check: UNIX_EPOCH,
        }
    }

    fn add_metric(&mut self, metric: Metric) -> bool {
        let now = SystemTime::now();
        let duration = now.duration_since(self.last_check).unwrap_or_default();
        let elapsed_seconds = duration.as_secs();

        // Clear expired metrics
        let current_time = now.duration_since(UNIX_EPOCH).unwrap().as_secs();
        let cutoff_time = current_time - elapsed_seconds;
        self.buffer = self.buffer.into_iter().filter(|m| {
            let m_time = m.timestamp();
            m_time >= cutoff_time
        }).collect();

        // Check if we can add the new metric
        if self.buffer.len() < self.limit {
            self.buffer.push(metric);
            self.last_check = now;
            true
        } else {
            false
        }
    }
}

fn batch_request_with_start_id<R>(&self, batch: BatchRequestBuilder<'_>, start_id: u64) -> impl Future<Output = Result<BatchResponse<'_, R>, Error>> + Send
where
    R: DeserializeOwned + fmt::Debug + 'static,
{
    let mut request_ids = generate_batch_id_range(start_id, batch.requests().len() as u64);
    let requests: Vec<Request> = batch
        .requests()
        .iter()
        .enumerate()
        .map(|(i, req)| Request {
            id: request_ids.next().unwrap(),
            method: req.method().to_string(),
            params: req.params().clone(),
        })
        .collect();

    let client = self.clone();
    let batch_requests = requests;

    async move {
        let mut responses = Vec::with_capacity(batch_requests.len());
        for request in batch_requests {
            let response = client.request(request).await?;
            responses.push(response);
        }
        Ok(BatchResponse::new(responses))
    }
}

use deno_process::ProcessError;
use std::process::Command;
#[cfg(unix)]
use std::os::unix::process::CommandExt;
#[cfg(windows)]
use deno_subprocess_windows::CommandExt;

fn spawn_detached_process(
    cmd: &str,
    args: &[&str],
) -> Result<u32, ProcessError> {
    let mut command = Command::new(cmd);
    for &arg in args {
        command.arg(arg);
    }

    #[cfg(unix)]
    {
        command.stdin(None)
              .stdout(None)
              .stderr(None)
              .detached(true);
    }

    #[cfg(windows)]
    {
        command.creation_flags(deno_subprocess_windows::CREATE_NEW_PROCESS_GROUP | deno_subprocess_windows::CREATE_DETACHED);
    }

    let child = command.spawn()?;
    Ok(child.id())
}

fn batch_insert_range(db: &leveldb::database::Database<i32>, start: i32, count: usize, value_prefix: &[u8]) -> Result<(), leveldb::database::error::Error> {
    let mut batch = Writebatch::new();
    let mut options = WriteOptions::new();
    options.set_sync(false);

    for i in 0..count {
        let key = format!("{}{}", start + i, value_prefix).into_bytes();
        batch.put(key, value_prefix);
    }

    db.write_batch(&mut batch, &options)
}

