}

impl<S> Service<Request> for LoggingService<S>
where
    S: Service<Request, Response = Response, Error = ExchangeError, Future = Pin<Box<dyn Future<Output = Result<Response, ExchangeError>>>>>,
{
    type Response = S::Response;
    type Error = S::Error;
    type Future = S::Future;

    fn poll_ready(&mut self, cx: &mut std::task::Context<'_>) -> std::task::Poll<Result<(), Self::Error>> {
        self.inner.poll_ready(cx)
    }

    fn call(&mut self, req: Request) -> Self::Future {
        tracing::info!("Received request: {:?}", req);
        let fut = self.inner.call(req);
        Box::pin(fut.map(move |res| {
            tracing::info!("Sent response: {:?}", res);
            res
        }))
    }
}

fn build_range_sql<T>(range: &Range<T>) -> String
where
    T: fmt::Display + Normalizable,
{
    let lower = match range.start_bound() {
        std::ops::Bound::Included(value) => format!("{}{}", value.normalize(), '['),
        std::ops::Bound::Excluded(value) => format!("{}{}", value.normalize(), '('),
        std::ops::Bound::Unbounded => String::from(""),
    };

    let upper = match range.end_bound() {
        std::ops::Bound::Included(value) => format!("{}{}", value.normalize(), ']'),
        std::ops::Bound::Excluded(value) => format!("{}{}", value.normalize(), ')'),
        std::ops::Bound::Unbounded => String::from(""),
    };

    format!("{}{}", lower, upper)
}

fn monitor_bitcoin_sync(
    monitor: &ServerBitcoinRpcMonitor,
    critical_threshold: f64,
    check_interval: Duration,
) {
    let status_receiver = &monitor.status_receiver;
    let critical_threshold = critical_threshold;
    let check_interval = check_interval;

    tokio::spawn(async move {
        let mut last_sync_percent = None;
        loop {
            let status = match status_receiver.borrow().clone() {
                Some(status) => status,
                None => {
                    info!(target: LOG_SERVER, "Bitcoin RPC status not available");
                    time::sleep(check_interval).await;
                    continue;
                }
            };

            if let Some(sync_percent) = status.sync_percent {
                if last_sync_percent.is_some_and(|prev| (sync_percent - prev).abs() > 5.0) {
                    info!(target: LOG_SERVER, "Significant change in sync percentage: {:.2}%", sync_percent);
                }

                if sync_percent < critical_threshold {
                    info!(target: LOG_SERVER, "Critical sync percentage: {:.2}%, below threshold of {:.2}%", sync_percent, critical_threshold);
                    // Here you would trigger an alert, e.g., send a notification or log it
                }

                last_sync_percent = Some(sync_percent);
            }

            time::sleep(check_interval).await;
        }
    });
}

fn validate_symbol_table(symbol_table: &[u8]) -> bool {
    if symbol_table.len() < FSST_SYMBOL_TABLE_SIZE {
        return false;
    }

    // Check magic number
    if symbol_table[0] != FSST_MAGIC[0] || symbol_table[1] != FSST_MAGIC[1] || symbol_table[2] != FSST_MAGIC[2] {
        return false;
    }

    // Check version
    if symbol_table[3] != 1 {
        return false;
    }

    // Check length of symbol table
    let length = u32::from_le_bytes([symbol_table[4], symbol_table[5], symbol_table[6], symbol_table[7]]);
    if length != (symbol_table.len() as u32 - 8) {
        return false;
    }

    // Check if the remaining bytes are all zero (optional, depending on specification)
    for &byte in &symbol_table[8..] {
        if byte != 0 {
            return false;
        }
    }

    true
}

