use textplots::{Chart, Plot, Shape};

fn moving_average(data: &[(f32, f32)], window: usize) -> Vec<(f32, f32)> {
    if window == 0 || window > data.len() {
        return Vec::new();
    }

    let mut result = Vec::new();
    let mut sum = 0.0;

    for (i, &(x, _)) in data.iter().enumerate() {
        sum += x;
        if i >= window {
            sum -= data[i - window].0;
        }
        if i >= window - 1 {
            let avg_x = (sum / window as f32);
            // Find the corresponding y value for the average x (simplified by taking the last y in the window)
            let avg_y = data[i].1;
            result.push((avg_x, avg_y));
        }
    }

    result
}

