fn send_fragmented_text(
    ws: &mut WebSocket,
    message: &str,
) -> Result<(), WebSocketError> {
    let mut current_chunk = String::new();
    let mut is_final = false;
    let mut fragment_count = 0;
    let max_fragment_size = 1400; // Adjust based on your requirements

    for ch in message.chars() {
        if current_chunk.len() >= max_fragment_size {
            let chunk = current_chunk.clone();
            current_chunk.clear();
            ws.send(Frame::text(chunk, is_final))?;
            fragment_count += 1;
            is_final = false;
        }
        current_chunk.push(ch);
    }

    if !current_chunk.is_empty() {
        ws.send(Frame::text(current_chunk, is_final))?;
        fragment_count += 1;
    }

    Ok(())
}

