fn nsarray_to_i32_vec(obj: *mut Object) -> Result<Vec<i32>, String> {
    if obj.is_null() {
        return Err("NSArray is nil".to_string());
    }

    unsafe {
        let array = msg_send![obj, objectAtIndexedSubscript: 0]; // Check if array is valid
        if array.is_null() {
            return Err("NSArray is nil".to_string());
        }

        let array = msg_send![obj, isKindOfClass: class!(NSArray)];
        if array == msg_send![false] {
            return Err("Object is not an NSArray".to_string());
        }

        let count = msg_send![obj, count];
        if count == 0 {
            return Ok(Vec::new());
        }

        let mut result = Vec::with_capacity(count as usize);

        for i in 0..count {
            let obj = msg_send![obj, objectAtIndexedSubscript: i];
            if obj.is_null() {
                return Err("Array contains nil object".to_string());
            }

            let is_number = msg_send![obj, isKindOfClass: class!(NSNumber)];
            if is_number == msg_send![false] {
                return Err("Array contains non-NSNumber object".to_string());
            }

            let number = msg_send![obj, numberWithInt: 0]; // Get NSNumber object
            let value = msg_send![number, intValue];
            result.push(value);
        }

        Ok(result)
    }
}

