fn extract_family_info(attrs: &[GenlCtrlAttrs]) -> Option<FamilyInfo> {
    let mut family_id = None;
    let mut family_name = None;
    let mut version = None;
    let mut hdrsize = None;

    for attr in attrs {
        match attr {
            GenlCtrlAttrs::FamilyId(id) => family_id = Some(*id),
            GenlCtrlAttrs::FamilyName(name) => family_name = Some(name.clone()),
            GenlCtrlAttrs::Version(ver) => version = Some(*ver),
            GenlCtrlAttrs::Hdrsize(size) => hdrsize = Some(*size),
            _ => {} // Ignore other attributes
        }
    }

    family_id.and_then(|id| family_name.map(|name| FamilyInfo { family_id: id, family_name: name, version: version.unwrap(), hdrsize: hdrsize.unwrap() }))
}

fn args_summary<T: argh::ArgsInfo>() -> String {
    let mut summary = String::new();
    let info = T::info();

    // Add positional arguments
    if let Some(pos_args) = info.positionals() {
        summary.push_str("Positional arguments:\n");
        for arg in pos_args {
            summary.push_str(&format!("  {}\n", arg.name));
        }
    }

    // Add flags
    if let Some(flags) = info.flags() {
        summary.push_str("Flags:\n");
        for flag in flags {
            let kind = match flag.kind {
                FlagInfoKind::Short(s) => format!("--{}", s),
                FlagInfoKind::Long(l) => format!("--{}", l),
                FlagInfoKind::Both(s, l) => format!("--{} --{}", s, l),
            };
            summary.push_str(&format!("  {} {}\n", kind, flag.desc));
        }
    }

    // Add subcommands
    if let Some(subcommands) = info.subcommands() {
        summary.push_str("Subcommands:\n");
        for subcmd in subcommands {
            summary.push_str(&format!("  {}\n", subcmd.name));
        }
    }

    summary
}

use crate::context::Context;
use async_graphql_parser::{Positioned, types as ast};
use miette::miette;

fn find_duplicate_fields<'a>(
    type_name: &str,
    fields: &'a [Positioned<ast::FieldDefinition>],
    ctx: &mut Context<'a>,
) {
    let mut field_names = std::collections::HashMap::new();
    for field in fields {
        let name = &field.item.name;
        if let Some(prev_pos) = field_names.insert(name, field.position) {
            ctx.report(
                miette!(
                    "Duplicate field name '{}' in object type '{}'",
                    name,
                    type_name
                )
                .with_label(
                    "first occurrence",
                    prev_pos,
                )
                .with_label(
                    "second occurrence",
                    field.position,
                ),
            );
        }
    }
}

fn draw_shadow(
    engine: &mut Engine,
    quad: &Quad,
    shadow: &Shadow,
    pixels: &mut tiny_skia::PixmapMut<'_>,
    clip_mask: &mut tiny_skia::Mask,
) {
    let blur_radius = shadow.blur_radius;
    let offset = shadow.offset;
    let color = shadow.color;

    let size = pixels.size();
    let mut shadow_pixmap = Pixmap::new(size.width as u32, size.height as u32, pixels.color_space())
        .unwrap();

    let mut shadow_mask = Mask::new(IntSize::from_size(size))
        .unwrap()
        .with_paint(tiny_skia::Paint::new().unwrap())
        .unwrap();

    // Create a shadow effect using Gaussian blur
    let mut blur_paint = tiny_skia::Paint::new().unwrap();
    blur_paint.set_style(tiny_skia::Style::Fill);
    blur_paint.set_color(color.into());
    blur_paint.set_filter(tiny_skia::Filter::GaussianBlur(blur_radius as f32));
    blur_paint.set_alpha(color.alpha());

    // Apply the blur to the shadow pixmap
    engine.fill_rect(&mut shadow_pixmap, &quad, &blur_paint);

    // Apply the offset to the shadow
    let mut translate_paint = tiny_skia::Paint::new().unwrap();
    translate_paint.set_style(tiny_skia::Style::Fill);
    translate_paint.set_matrix(tiny_skia::Matrix::translation(offset.x as f32, offset.y as f32));
    translate_paint.set_color(color.into());
    translate_paint.set_alpha(color.alpha());

    engine.fill_rect(&mut shadow_pixmap, &quad, &translate_paint);

    // Apply the shadow to the main pixmap using the clip mask
    let mut composite_paint = tiny_skia::Paint::new().unwrap();
    composite_paint.set_style(tiny_skia::Style::Fill);
    composite_paint.set_mask(clip_mask.clone());
    composite_paint.set_color(color.into());
    composite_paint.set_alpha(color.alpha());

    engine.draw_image(pixels, &shadow_pixmap, &composite_paint);
}

