fn validate_epoch_consistency(
    block: &BlockView,
    epoch_ext: &EpochExt,
    consensus: &Consensus,
) -> Result<(), Error> {
    let block_epoch_number = block.epoch_number();
    let block_compact_target = block.compact_target();

    let expected_epoch_number = epoch_ext.epoch_number();
    let expected_compact_target = epoch_ext.compact_target();

    if block_epoch_number != expected_epoch_number {
        return Err(EpochError::InvalidEpochNumber {
            actual: block_epoch_number,
            expected: expected_epoch_number,
        }
        .into());
    }

    if block_compact_target != expected_compact_target {
        return Err(EpochError::InvalidCompactTarget {
            actual: block_compact_target,
            expected: expected_compact_target,
        }
        .into());
    }

    Ok(())
}

