use datafusion_common::Result;
use datafusion_datasource::PartitionedFile;
use futures::stream::{BoxStream, StreamExt, TryStreamExt};
use futures::channel::mpsc;
use std::pin::Pin;
use std::task::{Context, Poll};

fn merge_and_sort_partitioned_file_streams<'a>(
    streams: Vec<BoxStream<'a, Result<PartitionedFile>>>,
) -> Result<BoxStream<'a, Result<PartitionedFile>>> {
    let (mut tx, rx) = mpsc::channel(16);

    let mut futures = streams.into_iter().map(|stream| {
        Box::pin(async move {
            let mut stream = stream.try_stream()?;
            while let Some(item) = stream.next().await {
                tx.send(item?).await?;
            }
            Ok(())
        })
    });

    let mut merged = Pin::new(&mut futures).next().unwrap().boxed();

    for future in futures {
        merged = Pin::new(&mut merged).and_then(move |()| future);
    }

    let sorted = Box::pin(async move {
        let mut files = Vec::new();
        while let Some(file) = rx.next().await {
            files.push(file?);
        }
        files.sort_by(|a, b| a.file_path().cmp(b.file_path()));
        Ok(files.into_iter().map(Ok).boxed())
    });

    Ok(sorted)
}

