fn put_multiple_atomic(
    storage: &worker_sys::types::DurableObjectStorage,
    entries: &[(String, JsValue)],
) -> Result<js_sys::Promise, JsValue> {
    let transaction = storage.begin_transaction()?;
    let mut promises = vec![];

    for (key, value) in entries {
        let key = key.clone();
        let value = value.clone();
        let transaction_clone = transaction.clone();
        let promise = transaction_clone.put(key, value);
        promises.push(promise);
    }

    let promise = js_sys::Promise::all_with(iter::from_fn(|| promises.pop()));
    Ok(promise)
}

fn decrypt_and_validate(receiver_sec: &[u8], encrypted: &[u8], expected_checksum: &[u8]) -> Result<Vec<u8>, ecies::Error> {
    let decrypted = decrypt(receiver_sec, encrypted)?;
    let mut hasher = Sha256::new();
    hasher.update(&decrypted);
    let computed_checksum = hasher.finalize();
    if computed_checksum == expected_checksum {
        Ok(decrypted)
    } else {
        Err(ecies::Error::Invalid)
    }
}

