fn update_nested_field(
    storage: &MongoStorage,
    table_name: &str,
    key: Key,
    field_path: &str,
    new_value: Value,
) -> Result<()> {
    let mut update_doc = doc! {};
    let mut current_doc = doc! {};
    let mut parts = field_path.split('.');

    let mut current_key = parts.next().ok_or("Field path cannot be empty")?;

    for part in parts {
        current_doc.insert(current_key, doc! {});
        current_key = part;
    }

    current_doc.insert(current_key, new_value.into_bson()?);
    update_doc.insert("set", current_doc);

    let key_bson = key.into_bson()?;
    storage.update_one(table_name, key_bson, update_doc).chain_err(|| "Failed to update nested field")?;

    Ok(())
}

