fn find_empty_object_types(ctx: &mut Context<'_>) -> Vec<String> {
    let mut empty_object_types = Vec::new();
    let type_definitions = ctx.get_type_definitions();

    for type_def in type_definitions {
        if let ast::TypeDefinition::Object(obj) = type_def {
            let fields = obj.fields.iter().filter(|field| {
                let field_type = field.ty.as_ref().unwrap();
                if let ast::Type::Named(named) = field_type {
                    if let Some(extension) = named.extension {
                        return true;
                    }
                }
                true
            });

            if fields.count() == 0 {
                empty_object_types.push(obj.name.clone());
            }
        }
    }

    empty_object_types
}

