fn create_color_depth_framebuffer(
    ctx: &Context,
    width: i32,
    height: i32,
) -> Option<(Framebuffer, Texture, Renderbuffer)> {
    let texture = ctx.create_texture();
    let renderbuffer = ctx.create_renderbuffer();

    unsafe {
        // Configure color texture
        ctx.gl().glBindTexture(TEXTURE_2D, texture);
        ctx.gl().glTexImage2D(
            TEXTURE_2D,
            0,
            RGBA as i32,
            width,
            height,
            0,
            RGBA,
            UNSIGNED_BYTE,
            std::ptr::null(),
        );
        ctx.gl().glTexParameteri(TEXTURE_2D, TEXTURE_MIN_FILTER, LINEAR as i32);
        ctx.gl().glTexParameteri(TEXTURE_2D, TEXTURE_MAG_FILTER, LINEAR as i32);

        // Configure depth renderbuffer
        ctx.gl().glBindRenderbuffer(RENDERBUFFER, renderbuffer);
        ctx.gl().glRenderbufferStorage(
            RENDERBUFFER,
            DEPTH_COMPONENT16,
            width,
            height,
        );

        // Create framebuffer
        let framebuffer = ctx.create_framebuffer();
        ctx.gl().glBindFramebuffer(FRAMEBUFFER, framebuffer);

        // Attach color texture
        ctx.gl().glFramebufferTexture2D(
            FRAMEBUFFER,
            COLOR_ATTACHMENT0,
            TEXTURE_2D,
            texture,
            0,
        );

        // Attach depth renderbuffer
        ctx.gl().glFramebufferRenderbuffer(
            FRAMEBUFFER,
            DEPTH_ATTACHMENT,
            RENDERBUFFER,
            renderbuffer,
        );

        // Check framebuffer completeness
        let status = ctx.gl().glCheckFramebufferStatus(FRAMEBUFFER);
        if status != FRAMEBUFFER_COMPLETE {
            return None;
        }
    }

    Some((ctx.framebuffers().insert(framebuffer), texture, renderbuffer))
}

use futures::{AsyncReadExt, AsyncWriteExt};

fn request_response(stream: &mut Stream, payload: &[u8]) -> Result<Vec<u8>, Error> {
    // Write the length of the payload as a 32-bit little-endian value
    let payload_len = payload.len() as u32;
    stream.write_all(&payload_len.to_le_bytes()).await?;
    stream.write_all(payload).await?;
    stream.flush().await?;

    // Read the response length
    let mut response_len_bytes = [0u8; 4];
    stream.read_exact(&mut response_len_bytes).await?;
    let response_len = u32::from_le_bytes(response_len_bytes);

    // Read the response payload
    let mut response = vec![0u8; response_len as usize];
    stream.read_exact(&mut response).await?;

    Ok(response)
}

fn current_mint_price(deps: Deps, env: &Env) -> StdResult<Coin> {
