    }
}

use hdrs::Client;
use hdrs::Metadata;
use std::io;

fn dir_total_size(fs: &Client, path: &str) -> io::Result<u64> {
    let mut total_size = 0;
    let mut dir = fs.read_dir(path)?;

    while let Some(entry) = dir.next() {
        let entry = entry?;
        let metadata = fs.metadata(entry.path())?;
        if metadata.is_file() {
            total_size += metadata.len();
        } else if metadata.is_dir() {
            total_size += dir_total_size(fs, entry.path())?;
        }
    }

    Ok(total_size)
}

fn total_seconds(&self) -> f64 {
    let years = self.years as f64;
    let months = self.months as f64;
    let days = self.days as f64;
    let hours = self.hours as f64;
    let minutes = self.minutes as f64;
    let seconds = self.seconds as f64;

    // Convert years to seconds
    let years_seconds = years * 365.25 * 24 * 60 * 60;
    // Convert months to seconds (using average month length)
    let months_seconds = months * 30.44 * 24 * 60 * 60;
    // Convert days to seconds
    let days_seconds = days * 24 * 60 * 60;
    // Convert hours, minutes, and seconds to seconds
    let time_seconds = hours * 3600.0 + minutes * 60.0 + seconds;

    years_seconds + months_seconds + days_seconds + time_seconds
}

fn monitor_payment_operation(context: &LightningClientContext, operation_id: OperationId) -> Result<FinalSendOperationState, anyhow::Error> {
    let mut stream = context.subscribe_operation_state(operation_id);
    let mut final_state = None;

    while let Some(state) = stream.next().await {
        match state {
            Some(SendOperationState::Final(state)) => {
                final_state = Some(state);
                break;
            }
            Some(SendOperationState::Intermediate(_)) => {
                // Continue waiting for final state
            }
            None => {
                return Err(anyhow::anyhow!("Operation state stream ended unexpectedly"));
            }
        }
    }

    final_state.ok_or_else(|| anyhow::anyhow!("Operation did not reach a final state"))
}

use leptos::prelude::*;
use leptos_dom::helpers::set_timeout;
use std::time::Duration;

fn TimedAlert() -> impl IntoView {
    let (message, set_message) = create_signal("");
    let (show, set_show) = create_signal(false);
    let (timer_id, set_timer_id) = create_signal<Option<u32>>(None);

    let handle_timer = move || {
        set_show(false);
        set_message("".to_string());
        if let Some(id) = timer_id.get() {
            // In a real environment, you would cancel the timeout here
            // For demonstration, we just clear it
            set_timer_id(None);
        }
    };

    let start_timer = move |msg: &str, duration: Duration| {
        set_message(msg.to_string());
        set_show(true);
        if let Some(id) = timer_id.get() {
            // Cancel any existing timer
            set_timer_id(None);
        }
        let id = set_timeout(move || handle_timer(), duration.as_millis() as u32);
        set_timer_id(Some(id));
    };

    view! {
        <div>
            <button on:click=move |_| start_timer("This is a timed alert!", Duration::from_secs(3))>
                "Show Alert"
            </button>
            <div class="alert" class:hidden=move || !show()>
                {move || message()}
            </div>
        </div>
    }
}

use ipmpsc::{Sender, Receiver, SharedRingBuffer};
use anyhow::Result;
use serde::{Serialize, Deserialize};

fn fork_and_send() -> Result<()> {
    // Create a shared ring buffer with capacity for one message
    let buffer = SharedRingBuffer::new(1);

    // Create sender and receiver
    let (sender, receiver) = buffer.split();

    // Fork the process
    let child_pid = unsafe { libc::fork() };

    match child_pid {
        // In the child process
        0 => {
            // Child sends a message
            let message = 42u32;
            let serialized = bincode::serialize(&message).unwrap();
            sender.send(serialized)?;
            println!("Child sent message");
            Ok(())
        },
        // In the parent process
        _ => {
            // Parent receives the message
            let received = receiver.recv()?;
            let message: u32 = bincode::deserialize(&received).unwrap();
            println!("Parent received message: {}", message);
            Ok(())
        },
        // Error in fork
        -1 => Err(std::io::Error::last_os_error().into()),
    }
}

fn get_env_var(name: &str) -> Option<String> {
    let name_bytes = name.as_bytes();
    let name_len = name_bytes.len();

    // First syscall to get the length of the environment variable
    let len = unsafe { sys_getenv(name_bytes.as_ptr() as *const _, name_len as u64) };
    if len == 0 {
        return None;
    }

    // Allocate memory for the environment variable value
    let buffer = unsafe { sys_alloc_aligned(len as usize, WORD_SIZE) };
    if buffer.is_null() {
        return None;
    }

    // Second syscall to read the environment variable into the buffer
    let result = unsafe { sys_getenv(name_bytes.as_ptr() as *const _, name_len as u64, buffer, len as u64) };
    if result != len {
        unsafe { core::ptr::drop_in_place(buffer) };
        unsafe { sys_alloc_aligned(len as usize, WORD_SIZE) };
        return None;
    }

    // Convert buffer to String
    let buffer_slice = unsafe { slice::from_raw_parts_mut(buffer as *mut u8, len as usize) };
    let value = String::from_utf8(buffer_slice.to_vec()).ok()?;

    // Free the allocated buffer
    unsafe { core::ptr::drop_in_place(buffer) };

    Some(value)
}

