use crate::FriendlyDescription;
use std::collections::HashMap;

fn parse_friendly_descriptions(config: &str) -> Result<Vec<(String, FriendlyDescription<'static>)>, ExporterError> {
    let mut peers = HashMap::new();
    let mut current_public_key = None;
    let mut current_description = String::new();

    for line in config.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        if line.starts_with('[') && line.ends_with(']') {
            if let Some(public_key) = current_public_key.take() {
                if !current_description.is_empty() {
                    let friendly_description = FriendlyDescription::try_from(&current_description)?;
                    peers.insert(public_key, friendly_description);
                    current_description = String::new();
                }
            }
            continue;
        }

        if line.starts_with("public_key") {
            if let Some(pos) = line.find('=') {
                if let Some(public_key) = line[pos + 1..].trim().strip_prefix("0x").and_then(|s| s.parse::<String>().ok()) {
                    current_public_key = Some(public_key);
                }
            }
        } else if line.starts_with("friendly_name") || line.starts_with("friendly_json") {
            if let Some(pos) = line.find('=') {
                if let Some(description) = line[pos + 1..].trim().strip_prefix('"').and_then(|s| s.strip_suffix('"')).map(|s| s.to_string()) {
                    current_description = description;
                }
            }
        }
    }

    if let Some(public_key) = current_public_key {
        if !current_description.is_empty() {
            let friendly_description = FriendlyDescription::try_from(&current_description)?;
            peers.insert(public_key, friendly_description);
        }
    }

    let mut result = Vec::new();
    for (public_key, description) in peers {
        result.push((public_key, description));
    }

    Ok(result)
}

