fn verify_decryption_shares(
    contract: &fedimint_lnv2_common::contracts::IncomingContract,
    tpe_pks: &std::collections::BTreeMap<fedimint_core::PeerId, fedimint_tpe::PublicKeyShare>,
    shares: &std::collections::BTreeMap<fedimint_core::PeerId, fedimint_tpe::DecryptionKeyShare>,
) -> bool {
    if shares.len() < contract.min_decryption_shares {
        return false;
    }

    for (peer_id, share) in shares {
        if !tpe_pks.contains_key(peer_id) {
            return false;
        }

        if !share.verify(&tpe_pks[peer_id].public_key) {
            return false;
        }
    }

    true
}

use std::collections::BTreeSet;
use cron_parser::{parse_field, ParseError};

fn describe_cron(cron: &str) -> Result<String, ParseError> {
    let fields = parse_field(cron)?;
    let mut description = String::new();
    let mut first = true;

    for (i, field) in fields.iter().enumerate() {
        let field_name = match i {
            0 => "minute",
            1 => "hour",
            2 => "day of month",
            3 => "month",
            4 => "day of week",
            _ => "unknown",
        };

        let values: BTreeSet<_> = field.values.iter().collect();
        let mut values_str = String::new();
        let mut first_value = true;

        for value in &values {
            if !first_value {
                values_str.push(' ');
            }
            values_str.push_str(value);
            first_value = false;
        }

        if !first {
            description.push(' ');
        }
        description.push_str(field_name);
        description.push_str(": ");
        description.push_str(&values_str);
        first = false;
    }

    Ok(description)
}

fn hash_file(path: &Path) -> Result<Digest, Box<dyn std::error::Error>> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);
    let mut hasher = sha2_224::Hasher::new();

    for chunk in reader.bytes().chunks(65536) {
        if let Ok(chunk) = chunk {
            hasher.update(&chunk);
        }
    }

    Ok(hasher.finalize())
}

