use vortex_error::VortexResult;
use vortex_array::arrays::PrimitiveArray;
use vortex_scalar::Scalar;
use crate::{SparseArray, SparseVTable};

fn sparse_sum_i64(array: &SparseArray) -> VortexResult<i64> {
    let vtable = array.vtable();
    let fill_value = vtable.fill_value().as_i64()?;
    let mut sum = 0i64;

    for chunk in &array.chunks {
        let chunk_data = chunk.data();
        let chunk_length = chunk.length() as usize;

        // Process the chunk's data
        if chunk_data.len() >= chunk_length {
            for i in 0..chunk_length {
                let value = chunk_data[i].as_i64()?;
                sum += value;
            }
        } else {
            // If the chunk data is shorter than the chunk length, it's an error
            return Err(vortex_error::VortexError::new("Chunk data length mismatch"));
        }
    }

    Ok(sum)
}

