fn init_git_repo(path: &Path, username: &str, email: &str) -> XXResult<Git> {
    // Create the directory if it doesn't exist
    file::ensure_dir_exists(path)?;

    // Initialize Git repository
    let git = Git::new(path.to_path_buf());
    cmd::run("git init", path)?;

    // Configure user name and email
    cmd::run(&format!("git config user.name \"{}\"", username), path)?;
    cmd::run(&format!("git config user.email \"{}\"", email), path)?;

    // Create README.md file
    let readme_path = path.join("README.md");
    file::write_file(&readme_path, "# Project Name\n\nThis is the initial README file.")?;

    // Add and commit the README file
    cmd::run("git add README.md", path)?;
    cmd::run("git commit -m \"Initial commit\"", path)?;

    Ok(git)
}

fn fragmentation_ratio(allocator: &ZoneAllocator<'static>) -> f64 {
    let mut used_slots = 0;
    let mut total_slots = 0;

    for page in allocator.pages.iter() {
        if let Some(allocable_page) = page.as_ref() {
            let mut page_used_slots = 0;
            let mut page_total_slots = 0;

            for slot in allocable_page.slots.iter() {
                if slot.is_used() {
                    page_used_slots += 1;
                }
                page_total_slots += 1;
            }

            used_slots += page_used_slots;
            total_slots += page_total_slots;
        }
    }

    if total_slots == 0 {
        return 0.0;
    }

    (1.0 - (used_slots as f64 / total_slots as f64)) as f64
}

fn build_peg_in_descriptor(pubkeys: BTreeMap<PeerId, CompressedPublicKey>, threshold: usize) -> PegInDescriptor {
    let mut sorted_pubkeys: Vec<CompressedPublicKey> = pubkeys.values().cloned().collect();
    sorted_pubkeys.sort();

    let mut multisig_descriptor = Wsh::multi(sorted_pubkeys, threshold);
    let multisig_script = multisig_descriptor.to_script();

    let mut wpkh_descriptor = Wpkh::new(multisig_script);
    let wpkh_script = wpkh_descriptor.to_script();

    PegInDescriptor::new(wpkh_script)
}

