fn timeout_discovery<P>(behaviour: &mut Behaviour<P>, now: Instant)
where
    P: Provider,
{
    let mut expired_peers = Vec::new();
    let mut discovered_peers = VecDeque::new();

    // Drain the discovered nodes into a vector for processing
    std::mem::swap(&mut discovered_peers, &mut behaviour.discovered_peers);

    for peer in discovered_peers {
        if now < peer.expiration_time {
            // If the peer is still valid, reinsert it into the deque
            behaviour.discovered_peers.push_back(peer);
        } else {
            // If the peer has expired, record it for event emission
            expired_peers.push(peer);
        }
    }

    // Emit an Expired event for each expired peer
    for peer in expired_peers {
        behaviour
            .swarm
            .emit_event(Event::Expired(peer.peer_id, peer.address));
    }
}

fn with_transaction<F, Fut>(db: &mut Database, operation: F) -> IndexerResult<()>
where
    F: FnOnce(&mut Database) -> Fut,
    Fut: Future<Output = IndexerResult<()>>,
{
    let result = operation(db).await;
    if let Err(e) = result {
        // If there's an error, rollback the transaction
        db.rollback()?;
        return Err(e);
    }
    // If everything is successful, commit the transaction
    db.commit()?;
    Ok(())
}

