use std::collections::HashMap;
use time::{Duration, OffsetDateTime};
use utmp_rs::UtmpEntry;

fn compute_login_durations(entries: &[UtmpEntry]) -> HashMap<String, Duration> {
    let mut login_durations = HashMap::new();
    let mut login_processes = HashMap::new();

    for entry in entries {
        if let Some(login) = entry.as_login() {
            let pid = login.pid;
            let line = login.line.clone();
            let login_time = OffsetDateTime::from_unix_timestamp(login.tv_sec as i64);
            login_processes.insert((pid, line), login_time);
        }
    }

    for entry in entries {
        if let Some(process) = entry.as_process() {
            let pid = process.pid;
            let line = process.line.clone();
            if let Some(login_time) = login_processes.get(&(pid, line)) {
                let logout_time = OffsetDateTime::from_unix_timestamp(process.tv_sec as i64);
                let duration = logout_time - *login_time;
                let username = process.user.clone();
                *login_durations.entry(username).or_insert(Duration::zero()) += duration;
            }
        }
    }

    login_durations
}

use sha2::{Sha256, Digest};

fn compute_workspace_checksum(dependencies: &[Dependency]) -> String {
    let mut hasher = Sha256::new();
    for dep in dependencies {
        let mut dep_hasher = Sha256::new();
        dep_hasher.update(dep.name.as_bytes());
        dep_hasher.update(dep.version.as_bytes());
        if let Some(features) = &dep.features {
            dep_hasher.update(features.as_bytes());
        }
        let dep_hash = hex::encode(dep_hasher.finalize());
        hasher.update(dep_hash.as_bytes());
    }
    hex::encode(hasher.finalize())
}

fn create_nonce_signed_transaction(
    client: &RpcClient,
    nonce_pubkey: &Pubkey,
    payer: &Keypair,
    receiver: &Pubkey,
    amount: u64,
) -> Result<Transaction, Error> {
    let blockhash = client.get_latest_blockhash()?;
    let nonce_account = nonblocking::get_nonce_account(client, nonce_pubkey, &blockhash)?;
    let nonce_instruction = nonblocking::advance_nonce_account(
        nonce_pubkey,
        &nonce_account.owner,
        &nonce_account.redeemable,
        amount,
        &blockhash,
    )?;

    let mut transaction = Transaction::new_with_payer(
        &[nonce_instruction],
        Some(&nonce_pubkey),
    );

    transaction.sign(&[payer], blockhash);

    Ok(transaction)
}

use std::sync::Arc;
use datafusion_expr::ColumnarValue;
use datafusion_common::Result;
use arrow::array::{as_string_array, as_int32_array, StringBuilder};

fn repeat_string(args: [ColumnarValue; 2]) -> Result<ColumnarValue> {
    let string_array = as_string_array(&args[0].array)?;
    let repeat_array = as_int32_array(&args[1].array)?;

    let mut builder = StringBuilder::with_capacity(string_array.len());
    for i in 0..string_array.len() {
        let value = string_array.value(i);
        let repeat_count = repeat_array.value(i) as usize;
        for _ in 0..repeat_count {
            builder.push_value(value);
        }
    }

    Ok(ColumnarValue::new(Arc::new(builder.build()?)))
}

fn cut_ellipse_gradient(
    center: vec2<f32>,
    radius: f32,
    inner_ratio: f32,
    outer_color: Rgba<f32>,
    inner_color: Rgba<f32>,
) -> (Ellipse, Ellipse) {
    let outer_radius = radius;
    let inner_radius = radius * inner_ratio;

    let outer_ellipse = Ellipse::new(
        center,
        outer_radius,
        outer_radius,
        outer_color,
        mat3::identity(),
    );

    let inner_ellipse = Ellipse::new(
        center,
        inner_radius,
        inner_radius,
        inner_color,
        mat3::identity(),
    );

    (outer_ellipse, inner_ellipse)
}

fn record_operation_cache_hit_with_client(&self, client: Option<&Client>) {
