fn json_response_with_header<T: Serialize>(data: &T, name: &str, value: &str) -> HttpResponse {
    let headers = http::header::HeaderMap::new();
    let mut header_name = HeaderName::from_str(name).expect("Invalid header name");
    let header_value = HeaderValue::from_str(value).expect("Invalid header value");
    headers.insert(header_name, header_value);

    let json = serde_json::to_string(data).expect("Failed to serialize JSON");
    HttpResponse::Ok()
        .headers(headers)
        .content_type("application/json")
        .body(json)
}

fn generate_batch_uuids(timestamp_ms: u64, event_ids: &[&str]) -> Vec<(String, Result<uuid7::Uuid, &'static str>)> {
    let mut results = Vec::new();
    let mut generator = V7Generator::new(thread_rng());

    for &event_id in event_ids {
        let uuid_result = generator.next_with_timestamp(timestamp_ms);
        results.push((event_id.to_string(), uuid_result));
    }

    results
}

