}

fn set_repair_threshold(&mut self, new_threshold: f64) {
    self.repair_threshold = new_threshold;
    // Immediately apply the new threshold to determine which slots are marked for repair
    self.update_repair_slots();
}

fn update_repair_slots(&mut self) {
    let mut slots_to_repair = HashSet::new();
    let mut slots_to_skip = HashSet::new();
    let mut slot_count = 0;
    let mut repair_count = 0;

    for slot in self.last_voted_fork_slots_aggregate.iter() {
        slot_count += 1;
        if self.repair_threshold > 0.0 && self.repair_threshold < 1.0 {
            let probability = self.repair_threshold;
            let random_value = rand::random::<f64>();
            if random_value < probability {
                slots_to_repair.insert(*slot);
                repair_count += 1;
            } else {
                slots_to_skip.insert(*slot);
            }
        } else if self.repair_threshold >= 1.0 {
            slots_to_repair.insert(*slot);
        } else if self.repair_threshold <= 0.0 {
            slots_to_skip.insert(*slot);
        }
    }

    self.repair_slots = slots_to_repair;
    self.skip_slots = slots_to_skip;
    self.repair_count = repair_count;
    self.slot_count = slot_count;
}

