fn filter_transactions_by_signer(
    block: &generated::ConfirmedBlock,
    signer: &Pubkey,
) -> Vec<generated::Transaction> {
    block.transactions
        .iter()
        .filter(|tx| {
            tx.signatures
                .iter()
                .any(|sig| *sig == *signer)
        })
        .cloned()
        .collect()
}

fn aggregate_counters_by_bucket(counters: &[CounterPoint]) -> Vec<DataPoint> {
    let mut bucket_map = HashMap::new();

    for counter in counters {
        let timestamp = counter.timestamp;
        let bucket = (timestamp.duration_since(UNIX_EPOCH).unwrap().as_secs() / 1) as u64; // bucket by second
        let count = counter.count;

        *bucket_map.entry(bucket).or_insert(0) += count;
    }

    let mut data_points: Vec<DataPoint> = bucket_map
        .into_iter()
        .map(|(bucket, total)| DataPoint {
            timestamp: bucket,
            count: total,
        })
        .collect();

    data_points.sort_by_key(|dp| dp.timestamp);
    data_points
}

fn average_receipt_size_per_link(stats: &TestBandwidthStats, scenario: &TestScenario) -> Option<ByteSize> {
    if stats.links.is_empty() || scenario.links.is_empty() {
        return None;
    }

    let mut total_size = ByteSize(0);
    let mut active_link_count = 0;

    for &link_id in &scenario.links {
        if let Some(link_stats) = stats.links.get(link_id) {
            if link_stats.active {
                total_size += link_stats.total_data_sent;
                active_link_count += 1;
            }
        }
    }

    if active_link_count == 0 {
        return None;
    }

    Some(total_size / active_link_count as u64)
}

use kill_tree::{blocking::kill_tree_with_config, Config, Result};
use std::time::Duration;

fn kill_tree_with_retry(
    target_pid: u32,
    config: &Config,
    max_retries: u32,
    base_delay: Duration,
) -> Result<()> {
    let mut retries = 0;
    let mut delay = base_delay;

    loop {
        match kill_tree_with_config(target_pid, config) {
            Ok(()) => return Ok(()),
            Err(e) => {
                retries += 1;
                if retries >= max_retries {
                    return Err(e);
                }
                std::thread::sleep(delay);
                delay = delay * 2;
            }
        }
    }
}

