fn backup_config_files(root_dir: &Path) -> Result<(), io::Error> {
    let backup_dir = root_dir.join(".backup");
    fs::create_dir_all(&backup_dir)?;

    let config_files = get_config_files(root_dir);

    for file in config_files {
        let file_path = file.to_path_buf();
        let backup_path = backup_dir.join(file.file_name().unwrap());

        if file_path.exists() {
            fs::copy(&file_path, &backup_path)?;
        }
    }

    Ok(())
}

fn get_config_files(root_dir: &Path) -> Vec<PathBuf> {
    let mut config_files = Vec::new();
    let mut visited = HashSet::new();

    fn walk_dir(path: &Path, config_files: &mut Vec<PathBuf>, visited: &mut HashSet<PathBuf>) {
        if path.is_dir() {
            for entry in fs::read_dir(path).unwrap_or_default() {
                let entry_path = entry.unwrap().path();
                if entry_path.is_dir() {
                    walk_dir(&entry_path, config_files, visited);
                } else {
                    if is_config_file(&entry_path) {
                        if !visited.contains(&entry_path) {
                            config_files.push(entry_path);
                            visited.insert(entry_path);
                        }
                    }
                }
            }
        }
    }

    walk_dir(root_dir, &mut config_files, &mut visited);
    config_files
}

fn is_config_file(path: &Path) -> bool {
    let file_name = path.file_name().unwrap();
    let file_name_str = file_name.to_str().unwrap();

    file_name_str.ends_with(".conf") ||
    file_name_str.ends_with(".cfg") ||
    file_name_str.ends_with(".yml") ||
    file_name_str.ends_with(".json") ||
    file_name_str.ends_with(".ini")
}

