use crossterm_input::{TerminalInput, InputEvent, KeyEvent};
use crossterm_utils::Result;

fn read_until_delimiter(input: &TerminalInput, delimiter: u8) -> Result<String> {
    let mut result = String::new();
    let mut running = true;

    while running {
        match input.poll()? {
            InputEvent::Key(KeyEvent::Char(c)) => {
                if c as u8 == delimiter {
                    running = false;
                } else {
                    result.push(c);
                }
            }
            InputEvent::Key(KeyEvent::Ctrl(c)) => {
                if c as u8 == delimiter {
                    running = false;
                }
            }
            InputEvent::Key(KeyEvent::Enter) => {
                running = false;
            }
            _ => {}
        }
    }

    Ok(result)
}

use coremidi_sys::{MIDIClientCreate, MIDIInputPortCreate, MIDIPortRef, MIDIClientRef, MIDIPacketList, MIDIPacket, MIDIPacketNext};
use core_foundation_sys::string::{CFStringCreateWithCString, kCFStringEncodingUTF8};
use std::ptr::{null_mut,NonNull};

fn create_logging_input(port_name: &str) -> Result<MIDIPortRef, OSStatus> {
    let client_ref = unsafe { MIDIClientCreate(CFStringCreateWithCString(null_mut(), port_name.as_ptr() as _, kCFStringEncodingUTF8).as_concrete_type(), null_mut(), null_mut()) };
    if client_ref.is_null() {
        return Err(-1);
    }

    let port_ref = unsafe { MIDIInputPortCreate(client_ref, CFStringCreateWithCString(null_mut(), port_name.as_ptr() as _, kCFStringEncodingUTF8).as_concrete_type()) };
    if port_ref.is_null() {
        unsafe { MIDIClientDispose(client_ref) };
        return Err(-1);
    }

    unsafe {
        let callback: extern "C" fn(_: MIDIPortRef, _: *mut u8, _: usize) -> () = |port_ref, packet_list, _size| {
            let mut packet = MIDIPacketNext(packet_list, null_mut());
            while !packet.is_null() {
                let mut data = [0u8; 32];
                let data_len = unsafe { MIDIPacketGetData(packet, data.as_mut_ptr() as _) };
                for i in 0..data_len {
                    println!("{}", data[i]);
                }
                packet = MIDIPacketNext(packet_list, packet);
            }
        };

        MIDIInputPortSetReadProc(port_ref, Some(callback), null_mut());
    }

    Ok(port_ref)
}

