fn fetch_structured_rows(storage: &MongoStorage, table_name: &str) -> Result<Vec<(Key, DataRow)>> {
    let collection = storage.collection(table_name)?;
    let primary_key = get_primary_key(&collection)?;
    let mut cursor = collection.find(None, FindOptions::default())?;

    let mut rows = Vec::new();
    for result in cursor {
        let doc = result?;
        let key = doc.get(primary_key.as_str()).and_then(|v| v.as_str()).map(String::from).ok_or_else(|| "Primary key not found".into())?;
        let row = doc.into_row()?;
        rows.push((Key::from(key), row));
    }

    Ok(rows)
}

