fn compile_with_optimization<I>(
    inputs: I,
    opt_level: midenc_session::OptLevel,
) -> Result<midenc_codegen_masm::Package, midenc_hir::diagnostics::Report>
where
    I: IntoIterator<Item = midenc_session::InputFile>,
{
