fn lookup_receipt_with_retry(
    client: &Addr<ViewClientActor>,
    runtime_config: &RuntimeConfig,
    start_block: &views::BlockView,
    receipt_id: CryptoHash,
    shard_tracker: &ShardTracker,
    max_retries: u32,
) -> Result<views::ReceiptView, FailedToFetchData> {
    let mut current_block = start_block;
    let mut retries = 0;

    loop {
        if let Ok(receipt) = find_local_receipt_by_id_in_block(client, runtime_config, current_block, receipt_id, shard_tracker) {
            return Ok(receipt);
        }

        // If we've reached the end of the blockchain or max retries, return error
        if retries >= max_retries {
            return Err(FailedToFetchData);
        }

        // Fetch next block
        let next_block = match fetch_block(client, current_block.height + 1) {
            Ok(block) => block,
            Err(_) => {
                // If fetching next block fails, return error
                return Err(FailedToFetchData);
            }
        };

        current_block = &next_block;
        retries += 1;
    }
}

