use solana_vote::vote_account::VoteAccounts;
use solana_vote_interface::state::Lockout;

fn average_lockout_confirmation(vote_accounts: &VoteAccounts) -> f64 {
    let mut total_confirmation_count = 0;
    let mut active_vote_accounts = 0;

    for vote_account in &vote_accounts.vote {
        if let Some(lockout) = &vote_account.lockout {
            total_confirmation_count += lockout.confirmation_count;
            active_vote_accounts += 1;
        }
    }

    if active_vote_accounts == 0 {
        return 0.0;
    }

    total_confirmation_count as f64 / active_vote_accounts as f64
}

fn canonicalize_expression(expr: &SpannedExpr<'_>) -> String {
    match expr {
        SpannedExpr::Literal(Literal { value, .. }) => value.clone(),
        SpannedExpr::Ident(ident) => ident.name.clone(),
        SpannedExpr::BinOp { left, op, right } => {
            format!(
                "{} {} {}",
                canonicalize_expression(left),
                op.to_string(),
                canonicalize_expression(right)
            )
        }
        SpannedExpr::UnOp { op, expr } => {
            format!("{}{}", op.to_string(), canonicalize_expression(expr))
        }
        SpannedExpr::Group(expr) => canonicalize_expression(expr),
        SpannedExpr::Call { func, args } => {
            let args_str: Vec<String> = args.iter().map(canonicalize_expression).collect();
            format!("{}({})", canonicalize_expression(func), args_str.join(", "))
        }
        SpannedExpr::Conditional { cond, then_expr, else_expr } => {
            format!(
                "{} ? {} : {}",
                canonicalize_expression(cond),
                canonicalize_expression(then_expr),
                canonicalize_expression(else_expr)
            )
        }
        SpannedExpr::VarAccess { name, .. } => name.clone(),
        SpannedExpr::VarAssign { name, value } => {
            format!("{} = {}", name, canonicalize_expression(value))
        }
        SpannedExpr::Array { elements } => {
            let elements_str: Vec<String> = elements.iter().map(canonicalize_expression).collect();
            format!("[{}]", elements_str.join(", "))
        }
        SpannedExpr::Object { entries } => {
            let entries_str: Vec<String> = entries
                .iter()
                .map(|(k, v)| format!("{}: {}", k, canonicalize_expression(v)))
                .collect();
            format!("{{{}}}", entries_str.join(", "))
        }
        SpannedExpr::FieldAccess { expr, field } => {
            format!("{}.{}", canonicalize_expression(expr), field)
        }
        SpannedExpr::IndexAccess { expr, index } => {
            format!("{}[{}]", canonicalize_expression(expr), canonicalize_expression(index))
        }
        SpannedExpr::Function { name, args } => {
            let args_str: Vec<String> = args.iter().map(canonicalize_expression).collect();
            format!("{}({})", name, args_str.join(", "))
        }
        SpannedExpr::Block { exprs } => {
            let exprs_str: Vec<String> = exprs.iter().map(canonicalize_expression).collect();
            format!("{{ {} }}", exprs_str.join("; "))
        }
        SpannedExpr::If { cond, then_expr, else_expr } => {
            format!(
                "if ({}) {{ {} }} else {{ {} }}",
                canonicalize_expression(cond),
                canonicalize_expression(then_expr),
                canonicalize_expression(else_expr)
            )
        }
        SpannedExpr::For { var, iter, body } => {
            format!(
                "for ({}) {{ {} }}",
                canonicalize_expression(iter),
                canonicalize_expression(body)
            )
        }
        SpannedExpr::While { cond, body } => {
            format!(
                "while ({}) {{ {} }}",
                canonicalize_expression(cond),
                canonicalize_expression(body)
            )
        }
        SpannedExpr::Break => "break".to_string(),
        SpannedExpr::Continue => "continue".to_string(),
        SpannedExpr::Return => "return".to_string(),
        SpannedExpr::Try { expr } => {
            format!("try ({})", canonicalize_expression(expr))
        }
        SpannedExpr::Catch { expr, handler } => {
            format!("catch ({}) {{ {} }}", canonicalize_expression(expr), canonicalize_expression(handler))
        }
        SpannedExpr::Throw => "throw".to_string(),
        SpannedExpr::Assert { cond, msg } => {
            format!("assert ({}) {}", canonicalize_expression(cond), canonicalize_expression(msg))
        }
        SpannedExpr::Switch { expr, cases } => {
            let cases_str: Vec<String> = cases
                .iter()
                .map(|(val, body)| format!("case {}: {}", canonicalize_expression(val), canonicalize_expression(body)))
                .collect();
            format!("switch ({}) {{ {} }}", canonicalize_expression(expr), cases_str.join(", "))
        }
        SpannedExpr::Default { body } => {
            format!("default {{ {} }}", canonicalize_expression(body))
        }
        SpannedExpr::Label { name, expr } => {
            format!("{}: {}", name, canonicalize_expression(expr))
        }
        SpannedExpr::Goto { label } => format!("goto {}", label),
        SpannedExpr::MacroCall { name, args } => {
