fn sync_combined_output(state: &mut OpState, cmd: &str, args: &[&str]) -> Result<Vec<u8>, ProcessError> {
    let mut stdout = vec![];
    let mut stderr = vec![];

    let spawn_args = SpawnArgs {
        cmd: cmd.to_string(),
        args: args.iter().map(|&s| s.to_string()).collect(),
        stdin: Stdio::inherit(),
        stdout: StdioOrRid::from(ChildStdio::Pipe),
        stderr: StdioOrRid::from(ChildStdio::Pipe),
        ..Default::default()
    };

    let (child, _) = op_spawn_sync(state, spawn_args)?;

    let stdout_handle = child.stdout.unwrap();
    let stderr_handle = child.stderr.unwrap();

    let mut stdout_reader = std::io::BufReader::new(stdout_handle);
    let mut stderr_reader = std::io::BufReader::new(stderr_handle);

    // Read all stdout
    let mut buffer = vec![];
    let _ = stdout_reader.read_until(b'\0', &mut buffer);
    stdout.extend_from_slice(&buffer);

    // Read all stderr
    buffer.clear();
    let _ = stderr_reader.read_until(b'\0', &mut buffer);
    stderr.extend_from_slice(&buffer);

    // Concatenate stdout and stderr
    let mut result = vec![];
    result.extend_from_slice(&stdout);
    result.extend_from_slice(&stderr);

    Ok(result)
}

fn build_tree<'a>(arena: &'a Arena<TreeNode<'a>>, values: &[i32]) -> Vec<&'a TreeNode<'a>> {
    let chunks = arena.chunks.borrow_mut();
    let mut current = &mut chunks.current;
    let mut result = Vec::new();

    for &value in values {
        let node = TreeNode {
            value,
            parent: None,
            children: Vec::new(),
        };
        let node_ref = current.push(node);
        result.push(node_ref);
    }

    // Now wire parent and child pointers
    for i in 1..values.len() {
        if i > 0 {
            let parent = result[i - 1];
            let child = result[i];
            child.parent = Some(parent);
            parent.children.push(child);
        }
    }

    result
}

use crate::{HStmt, ParamType, CDataType, SqlDataType, Pointer, Len, ULen, SqlReturn, SQLBindParameter, SQLExecDirect};

fn bind_name_and_age(stmt: HStmt, name: &str, age: i32) -> SqlReturn {
    // Convert Rust string to null-terminated C string
    let c_name = name.as_bytes().to_vec();
    let c_name_ptr = c_name.as_ptr() as Pointer;
    let c_name_len = c_name.len() as ULen;
    let c_name_null_term = 1;

    // Bind the name parameter (SQL_C_CHAR, SQL_VARCHAR)
    let name_param_type = ParamType::SQL_C_CHAR;
    let name_data_type = SqlDataType::SQL_VARCHAR;
    let name_is_nullable = 0;
    let name_scale = 0;
    let name_precision = 50;

    let name_result = unsafe {
        SQLBindParameter(
            stmt,
            1,
            ParamType::SQL_PARAM_INPUT,
            name_param_type,
            name_data_type,
            name_precision,
            name_scale,
            c_name_ptr as Pointer,
            c_name_len,
            name_is_nullable,
        )
    };

    if name_result != SqlReturn::SQL_SUCCESS && name_result != SqlReturn::SQL_SUCCESS_WITH_INFO {
        return name_result;
    }

    // Bind the age parameter (SQL_C_INTEGER, SQL_INTEGER)
    let age_param_type = ParamType::SQL_C_LONG;
    let age_data_type = SqlDataType::SQL_INTEGER;
    let age_is_nullable = 0;
    let age_scale = 0;
    let age_precision = 0;

    let age_result = unsafe {
        SQLBindParameter(
            stmt,
            2,
            ParamType::SQL_PARAM_INPUT,
            age_param_type,
            age_data_type,
            age_precision,
            age_scale,
            &age as Pointer,
            0,
            age_is_nullable,
        )
    };

    if age_result != SqlReturn::SQL_SUCCESS && age_result != SqlReturn::SQL_SUCCESS_WITH_INFO {
        return age_result;
    }

    // Execute the statement
    unsafe { SQLExecDirect(stmt, std::ptr::null_mut(), 0) }
}

