fn reconnect(url: &str) -> Result<WebSocket, Error> {
    let mut retry_count = 0;
    let max_retries = 5;
    let mut backoff = Duration::from_secs(1);

    loop {
        match websocket(url) {
            Ok(socket) => return Ok(socket),
            Err(e) => {
                eprintln!("Connection failed: {}", e);
                retry_count += 1;
                if retry_count >= max_retries {
                    return Err(e);
                }
                sleep(backoff).await;
                backoff *= 2;
            }
        }
    }
}

use http::HeaderMap;
use std::sync::Arc;
use tracing::Span;
use crate::graphql::{OperationType, OperationName, GraphqlOperationAttributes};

fn record_http_request_graphql_attrs(span: &Span, headers: &HeaderMap) {
    let mut attributes = GraphqlOperationAttributes::default();

    // Extract operation type from headers
    if let Some(value) = headers.get("x-grafbase-operation-type") {
        if let Ok(op_type) = value.to_str() {
            if let Ok(op_type_enum) = OperationType::from_str(op_type) {
                attributes.operation_type = Some(op_type_enum);
            }
        }
    }

    // Extract operation name from headers
    if let Some(value) = headers.get("x-grafbase-operation-name") {
        if let Ok(name) = value.to_str() {
            if name.is_empty() {
                attributes.operation_name = None;
            } else {
                attributes.operation_name = Some(OperationName::new(name.to_string()));
            }
        }
    }

    // Extract GraphQL query from headers
    if let Some(value) = headers.get("x-grafbase-graphql-query") {
        if let Ok(query) = value.to_str() {
            attributes.graphql_query = Some(query.to_string());
        }
    }

    // Extract optional complexity from headers
    if let Some(value) = headers.get("x-grafbase-complexity") {
        if let Ok(complexity_str) = value.to_str() {
            if let Ok(complexity) = complexity_str.parse::<u64>() {
                attributes.complexity = Some(complexity);
            }
        }
    }

    // Record the attributes on the span
    span.record("operation_type", &attributes.operation_type);
    span.record("operation_name", &attributes.operation_name);
    span.record("graphql_query", &attributes.graphql_query);
    span.record("complexity", &attributes.complexity);
}

fn start_echo_server(port_a: &str, port_b: &str, baud_rate: u32) -> std::io::Result<()> {
    let poll = Poll::new()?;
    let mut events = Events::with_capacity(1024);

    // Open and configure serial ports
    let serial_a = serialport::new(port_a, baud_rate)
        .timeout(Duration::from_millis(100))
        .open()?;
    let serial_b = serialport::new(port_b, baud_rate)
        .timeout(Duration::from_millis(100))
        .open()?;

    // Register serial ports with poll
    let token_a = Token(0);
    let token_b = Token(1);
    poll.registry()
        .register(&mut serial_a, token_a, Interest::READABLE)?;
    poll.registry()
        .register(&mut serial_b, token_b, Interest::READABLE)?;

    loop {
        let timeout = None;
        let n = poll.poll(&mut events, timeout)?;
        for event in events.iter() {
            match event.token() {
                token_a => {
                    let mut buf = [0u8; 1024];
                    let len = serial_a.read(&mut buf)?;
                    if len > 0 {
                        serial_b.write_all(&buf[..len])?;
                    }
                }
                token_b => {
                    let mut buf = [0u8; 1024];
                    let len = serial_b.read(&mut buf)?;
                    if len > 0 {
                        serial_a.write_all(&buf[..len])?;
                    }
                }
                _ => unreachable!(),
            }
        }
    }
}

fn connect_multiple_buckets(
    &self,
    configs: Vec<NatsConnectionConfig>,
    link_cfg: &LinkConfig<'_>,
) -> anyhow::Result<HashMap<String, Store>> {
    let mut bucket_map = HashMap::new();
    for config in configs {
        let store = self.connect_bucket(&config, link_cfg)?;
        bucket_map.insert(config.name.clone(), store);
    }
    Ok(bucket_map)
}

fn connect_bucket(
    &self,
    config: &NatsConnectionConfig,
    link_cfg: &LinkConfig<'_>,
) -> anyhow::Result<Store> {
    let nats = self.connect_to_nats(config, link_cfg)?;
    let store = nats.kv().store(config.bucket_name.as_str())?;
    Ok(store)
}

fn connect_to_nats(
    &self,
    config: &NatsConnectionConfig,
    link_cfg: &LinkConfig<'_>,
) -> anyhow::Result<async_nats::Client> {
    let mut opts = async_nats::Options::default();
    if let Some(uri) = &config.uri {
        opts = opts.uri(uri);
    }
    if let Some(jwt) = &config.jwt {
        opts = opts.jwt(jwt);
    }
    if let Some(tls) = &config.tls {
        opts = opts.tls_config(tls);
    }
    let client = opts.connect().map_err(|e| anyhow::anyhow!("Failed to connect to NATS: {}", e))?;
    Ok(client)
}

use std::fs::File;
use std::io::{BufRead, BufReader, Write};
use std::path::Path;
use environment_platform::Environment;

fn get_port_for_environment(environment: &Environment) -> u16 {
    match environment {
        Environment::Development => 8080,
        Environment::Staging => 8081,
        Environment::Production => 8082,
    }
}

fn generate_environment_file(base_path: &str, output_path: &str, environment: Environment) -> Result<(), Box<dyn std::error::Error>> {
    let base_path = Path::new(base_path);
    let output_path = Path::new(output_path);

    if !base_path.exists() {
        return Err("Base environment file not found".into());
    }

    let mut file = File::create(output_path)?;
    let reader = BufReader::new(File::open(base_path)?);

    for line in reader.lines() {
        let line = line?;
        let mut new_line = line.clone();
        let port = get_port_for_environment(&environment);
        let stage = match environment {
            Environment::Development => "development",
            Environment::Staging => "staging",
            Environment::Production => "production",
        };

        new_line = new_line.replace("{{stage}}", stage);
        new_line = new_line.replace("{{port}}", &port.to_string());

        writeln!(file, "{}", new_line)?;
    }

    Ok(())
}

fn combine_customer_request(customer: Customer, request: Request) -> Combined {
    match (customer, request) {
        (Customer::V1 { name, age: age_v1, .. }, Request::V1 { start }) => {
            Combined::V1 {
                name,
                age: age_v1,
                start,
            }
        }
        (Customer::V2 { name, age: age_v2, favourite_colour, .. }, Request::V1 { start }) => {
            Combined::V2 {
                name,
                age: age_v2,
                favourite_colour,
                start,
            }
        }
        (Customer::V2 { name, age: age_v2, favourite_colour, .. }, Request::V2 { start, end }) => {
            Combined::V2 {
                name,
                age: age_v2,
                favourite_colour,
                start,
                end,
            }
        }
        (Customer::V3 { name, age: age_v2, favourite_colour, dob, .. }, Request::V2 { start, end }) => {
            Combined::V3 {
                name,
                age: age_v2,
                favourite_colour,
                dob,
                start,
                end,
            }
        }
        (Customer::V3 { name, age: age_v2, favourite_colour, dob, .. }, Request::V3 { start, end }) => {
            Combined::V3 {
                name,
                age: age_v2,
                favourite_colour,
                dob,
                start,
                end,
            }
        }
    }
}

use sitemap_rs::video::{Video, VideoError};

fn validate_videos(videos: Vec<Video>) -> (Vec<Video>, Vec<VideoError>) {
    let mut valid_videos = Vec::new();
    let mut errors = Vec::new();

    for video in videos {
        let mut error = VideoError::new();
        let mut valid = true;

        // Check if content location is valid
        if video.content_location.is_empty() {
            error.add_error("Content location is missing");
            valid = false;
        }

        // Check duration is between 1 and 28800 seconds
        if video.duration <= 0 || video.duration > 28800 {
            error.add_error("Duration must be between 1 and 28800 seconds");
            valid = false;
        }

        // Check rating is between 0.0 and 5.0
        if video.rating < 0.0 || video.rating > 5.0 {
            error.add_error("Rating must be between 0.0 and 5.0");
            valid = false;
        }

        // Check if video is valid
        if valid {
            valid_videos.push(video);
        } else {
            errors.push(error);
        }
    }

    (valid_videos, errors)
}

fn custom_sdp_offer(
    addr: SocketAddr,
    server_fingerprint: Fingerprint,
    ice_ufrag: &str,
    ice_pwd: &str,
    setup_active: bool,
) -> String {
    let ip_version = if addr.is_ipv4() { IpVersion::IP4 } else { IpVersion::IP6 };
    let target_ip = addr.ip();
    let target_port = addr.port();

    let fingerprint_algorithm = server_fingerprint.algorithm();
    let fingerprint_value = server_fingerprint.value();

    let setup = if setup_active { "active" } else { "passive" };

    let mut tt = TinyTemplate::new();
    tt.add_template("sdp_template", SERVER_SESSION_DESCRIPTION).unwrap();

    let context = DescriptionContext {
        ip_version,
        target_ip,
        target_port,
        fingerprint_algorithm: fingerprint_algorithm.to_string(),
        fingerprint_value: fingerprint_value.to_string(),
        ufrag: ice_ufrag.to_string(),
        pwd: ice_pwd.to_string(),
    };

    let sdp = tt.render("sdp_template", &context).unwrap();

    sdp
}

fn send_batch_outputs<I>(
    node: &mut DoraNode,
    outputs: I,
    parameters: MetadataParameters,
) -> eyre::Result<()>
where
    I: IntoIterator<Item = (DataId, arrow::array::ArrayData)>,
{
    for (data_id, array_data) in outputs {
        let size = required_data_size(&array_data);
        let sample = DataSample::with_capacity(size);
