        node.send_output(data_id, sample, parameters.clone())?;
    }
    Ok(())
}

use c3p0::postgres::PgC3p0Pool;
use c3p0::postgres::*;
use c3p0::C3p0Error;
use diesel::prelude::*;
use diesel::pg::PgConnection;
use diesel::result::QueryResult;
use diesel::insert_into;
use diesel::expression::bound::Bound;
use std::collections::HashMap;

#[derive(Clone)]
pub struct TestData {
    pub first_name: String,
    pub last_name: String,
}

fn bulk_insert(pool: &PgC3p0Pool, table: &str, records: &[TestData]) -> Result<usize, C3p0Error> {
    let mut conn = pool.get()?; // Get a connection from the pool

    // Create a map of column names to values for all records
    let mut column_map = HashMap::new();
    let mut column_names = Vec::new();

    // Extract column names from the first record
    if let Some(first_record) = records.first() {
        column_names = first_record
            .fields()
            .iter()
            .map(|field| field.name())
            .collect();
    }

    // Build the values for each record
    let values: Vec<Vec<Box<dyn diesel::expression::Expression>>> = records
        .iter()
        .map(|record| {
            column_names
                .iter()
                .map(|&name| {
                    let field = record
                        .fields()
                        .iter()
                        .find(|f| f.name() == name)
                        .unwrap();
                    Box::new(diesel::expression::bound::Bound::new(
                        field.value().clone(),
                        diesel::sql_types::Text,
                    ))
                })
                .collect()
        })
        .collect();

    // Build the INSERT statement
    let insert_stmt = insert_into(table)
        .values(values)
        .returning(diesel::dsl::sql_function!("pg_catalog.row_count"));

    // Execute the insert
    let result: Result<usize, C3p0Error> = conn.execute(insert_stmt);
    result
}

